#[derive(Debug, Clone, PartialEq, Eq)]
struct NodeToken {
    id: String,
    label: Option<ParsedLabel>,
    icon: Option<String>,
    shape: NodeShape,
    /// CSS classes from the `:::className` suffix (bd-8n2b5).
    ///
    /// The suffix is part of the TOKEN, so it belongs on the token. `parse_node_token_with_config`
    /// already truncates the raw string at `:::` to find the id and previously threw the remainder
    /// away, which is why `A:::urgent` styled nothing while `class A urgent` worked. Carrying it
    /// here means edge endpoints, `&` node lists and bare declarations all pick it up from the one
    /// function that decides where the id ends — no second copy of the splitting rules.
    classes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BlockDef {
    id: String,
    label: Option<String>,
    shape: NodeShape,
    span_cols: usize,
    is_space: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SequenceParticipantDeclaration {
    id: String,
    label: Option<ParsedLabel>,
    shape: NodeShape,
    classes: Vec<&'static str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum SequenceStatement {
    Participant(String),
    Actor(String),
    /// A fully-parsed message. The classifier parses the message ONCE (arrow, endpoints, labels,
    /// activation) into [`SequenceMessageData`]; lowering then only interns + pushes the edge, instead
    /// of re-parsing the raw line a second time (and cloning it). Boxed to keep the enum small.
    Message(Box<SequenceMessageData>),
    Autonumber {
        start: Option<u32>,
        increment: Option<u32>,
    },
    /// `autonumber off`, which mermaid uses to STOP numbering. Distinct from `Autonumber` because
    /// "off" is not a start value: it used to fail `"off".parse::<u32>()`, take the whole statement
    /// to `None`, and fall through to the message parser, so the directive was silently discarded and
    /// messages kept their numbers (bd-a8x7).
    AutonumberOff,
    HideFootbox,
    Link {
        actor: String,
        label: String,
        url: String,
    },
    Links {
        actor: String,
        entries: Vec<(String, String)>,
    },
    Note {
        position: fm_core::NotePosition,
        participants: Vec<String>,
        text: String,
    },
    Activate(String),
    Deactivate(String),
    BoxStart {
        label: String,
        color: Option<String>,
    },
    CreateParticipant(String),
    Destroy(String),
    FragmentStart {
        kind: fm_core::FragmentKind,
        label: String,
    },
    FragmentElse {
        label: String,
    },
    FragmentEnd,
}

#[derive(Debug, Clone)]
enum ClassStatement {
    /// Class block start with name and optional generic type parameters.
    BlockStart(String, Vec<String>),
    Ast(FlowAst),
    Node(NodeToken),
    /// A non-block declaration that carries generic parameters alongside its parsed label.
    ///
    /// `BlockStart` deliberately re-parses its source when it opens a member block. A bare
    /// declaration has no such second parse, so keeping the already-parsed token here prevents
    /// `class A~T~["Label"]` from losing `Label` while its generic parameters are recorded.
    NodeWithGenerics(NodeToken, Vec<String>),
    Member(fm_core::IrClassMember),
    Stereotype(String, fm_core::ClassStereotype),
    /// Cardinality labels to attach to the most recently created edge.
    Cardinality(Option<String>, Option<String>),
    /// An inline style for the most recently created edge — currently only the dashed line that
    /// makes a UML REALIZATION distinguishable from an inheritance (bd-u9hcc).
    EdgeInlineStyle(&'static str),
    /// `note for <class> "<text>"` — target name and note text (bd-1fw3).
    Note(String, String),
    End,
}

/// Parse mermaid input with auto-detection. Convenience entry point for external callers
/// and reproduction scripts.
#[must_use]
#[allow(dead_code)]
pub fn parse_mermaid(input: &str) -> ParseResult {
    let detection = crate::detect_type_with_confidence(input);
    parse_mermaid_with_detection_and_config(
        input,
        detection,
        MermaidParseMode::Compat,
        &ParserConfig::default(),
    )
}

/// Parse mermaid input with pre-computed detection results.
#[must_use]
#[allow(dead_code)] // Used by crate-level tests through the private module path.
pub fn parse_mermaid_with_detection(
    input: &str,
    detection: DetectedType,
    parse_mode: MermaidParseMode,
) -> ParseResult {
    parse_mermaid_with_detection_and_config(input, detection, parse_mode, &ParserConfig::default())
}

/// Parse mermaid input with pre-computed detection results and explicit parser behavior config./// Parse mermaid input with pre-computed detection results and explicit parser behavior config.
#[must_use]
pub fn parse_mermaid_with_detection_and_config(
    input: &str,
    detection: DetectedType,
    parse_mode: MermaidParseMode,
    config: &ParserConfig,
) -> ParseResult {
    let (content, front_matter_payload) = split_front_matter_block(input);
    // bd-ec1t: a fuzzy-matched header is a MIS-TYPED header, not a node. Detection has already
    // decided that; without this the statement loop interns the typo as a graph node and draws it.
    // Allocates only on the fuzzy path, which is the rare one.
    let fuzzy_blanked = (detection.method == crate::DetectionMethod::FuzzyKeyword)
        .then(|| blank_fuzzy_matched_header(content))
        .flatten();
    let content = fuzzy_blanked.as_deref().unwrap_or(content);
    let diagram_type = detection.diagram_type;
    // Capacity hint only (feeds `with_capacity_hint`'s node/edge estimates — no semantic
    // effect), so an approximate line count is fine. Count `\n` with memchr's SIMD scan: the
    // scalar `filter(..).count()` (and the equivalent `map(bool).sum()`) does NOT auto-vectorize
    // at opt=3/x86-64-v2 and profiled ~4.8% self; memchr's `\n` count measured ~14× faster on
    // realistic input, byte-identical (exact `\n` count). memchr is already in the build graph via
    // chumsky, so no bundle cost. `+ 1` matches `str::lines()` for input without a trailing newline.
    let input_lines = memchr::memchr_iter(b'\n', content.as_bytes()).count() + 1;
    let mut builder = IrBuilder::with_capacity_hint(diagram_type, input_lines);
    builder.set_parse_mode(parse_mode);
    builder.set_parser_config(*config);

    // Add detection warnings to builder
    for warning in &detection.warnings {
        builder.add_warning(warning.clone());
    }

    if let Some(front_matter_payload) = front_matter_payload {
        parse_front_matter_config(front_matter_payload, &mut builder);
    }

    // Deck configuration is deliberately parsed after the diagram body by the graph-deck semantic
    // pass. Until then, a successfully terminated multi-line deck block is source, not diagram
    // syntax: blank it with its newlines preserved so no body parser can mistake JSON5 keys for
    // nodes. Unterminated/over-limit blocks stay visible to recovery after recording an init error.
    let deck_directives = scan_multiline_deck_directives(content);
    for error in &deck_directives.errors {
        let message = match error.kind {
            MultilineDeckDirectiveErrorKind::TooLarge => format!(
                "Lines {}-{}: multi-line deck directive exceeds the {}-line or {}-byte limit",
                error.start_line, error.end_line, MAX_DECK_BLOCK_LINES, MAX_DECK_BLOCK_BYTES
            ),
            MultilineDeckDirectiveErrorKind::Unterminated => format!(
                "Lines {}-{}: unterminated multi-line deck directive",
                error.start_line, error.end_line
            ),
        };
        let span = Span::new(
            fm_core::Position {
                line: u32::try_from(error.start_line).unwrap_or(u32::MAX),
                col: 1,
                byte: u32::try_from(error.start_byte).unwrap_or(u32::MAX),
            },
            fm_core::Position {
                line: u32::try_from(error.end_line).unwrap_or(u32::MAX),
                col: 1,
                byte: u32::try_from(error.end_byte).unwrap_or(u32::MAX),
            },
        );
        builder.add_warning(message.clone());
        builder.add_init_error(message, span);
    }
    let body_content = blank_multiline_deck_directives(content, &deck_directives.blocks);

    parse_init_directives(content, &mut builder);
    // The deck pass reads the ORIGINAL text (block byte offsets index into it); keep a handle
    // before `content` is shadowed by the blanked body copy.
    let deck_source = content;
    let content = body_content.as_ref();

    match diagram_type {
        DiagramType::Flowchart => parse_flowchart(content, &mut builder),
        DiagramType::Sequence => parse_sequence(content, &mut builder),
        DiagramType::Class => parse_class(content, &mut builder),
        DiagramType::State => parse_state(content, &mut builder),
        DiagramType::Requirement => parse_requirement(content, &mut builder),
        DiagramType::Mindmap => parse_mindmap(content, &mut builder),
        DiagramType::Er => parse_er(content, &mut builder),
        DiagramType::Journey => parse_journey(content, &mut builder),
        DiagramType::Timeline => parse_timeline(content, &mut builder),
        DiagramType::Sankey => parse_sankey(content, &mut builder),
        DiagramType::ArchitectureBeta => parse_architecture(content, &mut builder),
        DiagramType::C4Context
        | DiagramType::C4Container
        | DiagramType::C4Component
        | DiagramType::C4Dynamic
        | DiagramType::C4Deployment => parse_c4(content, &mut builder),
        DiagramType::PacketBeta => parse_packet(content, &mut builder),
        DiagramType::XyChart => parse_xychart(content, &mut builder),
        DiagramType::Gantt => parse_gantt(content, &mut builder),
        DiagramType::Pie => parse_pie(content, &mut builder),
        DiagramType::QuadrantChart => parse_quadrant(content, &mut builder),
        DiagramType::GitGraph => parse_gitgraph(content, &mut builder),
        DiagramType::BlockBeta => parse_block_beta(content, &mut builder),
        DiagramType::Kanban => parse_kanban(content, &mut builder),
        DiagramType::Treemap => parse_treemap(content, &mut builder),
        DiagramType::Radar => parse_radar(content, &mut builder),
        DiagramType::Info => parse_info(content, &mut builder),
        DiagramType::Unknown => {
            apply_unknown_contract(content, &mut builder, parse_mode);
        }
    }

    // Extract accessibility directives (accTitle / accDescr) from any diagram type.
    extract_accessibility_directives(content, &mut builder);

    // Promote a `title` directive that the statement loop dropped rather than promoted (bd-193x
    // sibling). No-op when a type-specific parser already set one.
    extract_generic_diagram_title(content, &mut builder);

    // Extract style/classDef/linkStyle directives for all diagram types.
    // (Previously only called from parse_flowchart; now runs generically
    // so that class, state, block-beta, etc. all support styling.)
    if diagram_type != DiagramType::Flowchart {
        extract_style_directives(content, &mut builder);
    }

    // Deck pass (bd-jw8m8): consume %%{deck: …}%% directives into ir.deck, after the body so
    // the semantic selector pass that follows can see every node id.
    parse_deck_directives(deck_source, &mut builder);
    // Semantic deck validation (bd-m2qzi): resolve every selector against the finished
    // diagram, purely for diagnostics — resolution results are never stored.
    validate_deck_semantics(&mut builder);

    // A treemap holds its whole diagram in `treemap_meta` and declares no nodes or edges, so the
    // generic emptiness check would report every valid treemap as unparseable. Keyed on the meta
    // being POPULATED rather than on the diagram type, so an actually-empty treemap still warns.
    // An `info` diagram declares no nodes and no edges by construction — its whole content is
    // the renderer's version, resolved at render time — so the generic emptiness check below would
    // report every valid one as unparseable.
    let carried_by_meta = diagram_type == DiagramType::Info
        || builder
            .ir_mut()
            .treemap_meta
            .as_ref()
            .is_some_and(|meta| !meta.nodes.is_empty())
        || builder
            .ir_mut()
            .radar_meta
            .as_ref()
            .is_some_and(|meta| !meta.axes.is_empty());
    if builder.node_count() == 0 && builder.edge_count() == 0 && !carried_by_meta {
        // The unimplemented-TYPE message is NOT emitted here. `unsupported_upstream_keyword` in
        // lib.rs already names those at DETECTION, and its warning reaches this builder through the
        // `detection.warnings` loop above — so a second, differently-worded message from this site
        // would be a duplicate diagnostic that drifts from the first (bd-8z4fk).
        builder.add_warning("No parseable nodes or edges were found");
    }

    builder.finish(detection.confidence, detection.method)
}

fn apply_unknown_contract(content: &str, builder: &mut IrBuilder, parse_mode: MermaidParseMode) {
    match parse_mode {
        MermaidParseMode::Strict => {
            builder.add_diagnostic(
                Diagnostic::error(
                    "Unable to detect a supported diagram family in strict mode; refusing fallback",
                )
                .with_category(DiagnosticCategory::Compatibility)
                .with_suggestion(
                    "Add an explicit Mermaid diagram header or switch to --parse-mode compat/recover"
                        .to_string(),
                ),
            );
        }
        MermaidParseMode::Compat => {
            builder.add_diagnostic(
                Diagnostic::warning(
                    "Unable to detect diagram family; attempting compatibility-mode flowchart salvage",
                )
                .with_category(DiagnosticCategory::Compatibility)
                .with_suggestion(
                    "Add an explicit Mermaid header to avoid compatibility fallback".to_string(),
                ),
            );
            builder.add_warning(
                "Unable to detect diagram type; using compatibility-mode flowchart salvage",
            );
            parse_flowchart(content, builder);
        }
        MermaidParseMode::Recover => {
            builder.add_diagnostic(
                Diagnostic::warning(
                    "Unable to detect diagram family; falling back to flowchart-style recovery",
                )
                .with_category(DiagnosticCategory::Recovery)
                .with_suggestion(
                    "Add an explicit Mermaid header to reduce recovery guesswork".to_string(),
                ),
            );
            builder.add_warning(
                "Unable to detect diagram type; using recovery-mode flowchart salvage",
            );
            parse_flowchart(content, builder);
        }
    }
}

#[allow(dead_code)] // Reserved for future detectible diagram families that still need fallback handling.
fn apply_support_contract(
    content: &str,
    builder: &mut IrBuilder,
    diagram_type: DiagramType,
    parse_mode: MermaidParseMode,
) {
    let support_level = diagram_type.support_level();
    if support_level != MermaidSupportLevel::Unsupported {
        builder.add_diagnostic(
            Diagnostic::info(format!(
                "Diagram family '{}' is parsed with declared support level '{}'",
                diagram_type.as_str(),
                diagram_type.support_label()
            ))
            .with_category(DiagnosticCategory::Compatibility),
        );
        parse_flowchart(content, builder);
        return;
    }

    match parse_mode {
        MermaidParseMode::Strict => {
            builder.add_diagnostic(
                Diagnostic::error(format!(
                    "Diagram family '{}' is unsupported in strict mode; no fallback applied",
                    diagram_type.as_str()
                ))
                .with_category(DiagnosticCategory::Compatibility)
                .with_suggestion(
                    "Choose a supported family or switch to --parse-mode compat/recover"
                        .to_string(),
                ),
            );
        }
        MermaidParseMode::Compat => {
            builder.add_diagnostic(
                Diagnostic::warning(format!(
                    "Diagram family '{}' is unsupported; applying best-effort flowchart salvage",
                    diagram_type.as_str()
                ))
                .with_category(DiagnosticCategory::Compatibility)
                .with_suggestion(
                    "Treat this output as degraded compatibility mode, not full semantic support"
                        .to_string(),
                ),
            );
            builder.add_warning(format!(
                "Diagram type '{}' is unsupported; using compatibility-mode flowchart salvage",
                diagram_type.as_str()
            ));
            parse_flowchart(content, builder);
        }
        MermaidParseMode::Recover => {
            builder.add_diagnostic(
                Diagnostic::warning(format!(
                    "Diagram family '{}' is unsupported; applying recovery-mode flowchart salvage",
                    diagram_type.as_str()
                ))
                .with_category(DiagnosticCategory::Recovery)
                .with_suggestion(
                    "Expect partial semantics; recovery mode prioritizes extracting structure"
                        .to_string(),
                ),
            );
            builder.add_warning(format!(
                "Diagram type '{}' is unsupported; using recovery-mode flowchart salvage",
                diagram_type.as_str()
            ));
            parse_flowchart(content, builder);
        }
    }
}

// ---------------------------------------------------------------------------
// Chumsky-based flowchart parser — intermediate AST
// ---------------------------------------------------------------------------

/// Intermediate AST node produced by the chumsky flowchart parser.
/// Lowered to IR via [`lower_flowchart`].
#[derive(Debug, Clone, PartialEq, Eq)]
#[allow(dead_code)] // Subgraph variant used in future expansion
enum FlowAst {
    Direction(GraphDirection),
    Node(FlowAstNode),
    Edge {
        from: FlowAstNode,
        arrow: ArrowType,
        label: Option<String>,
        edge_id: Option<String>,
        to: FlowAstNode,
    },
    ClassAssign {
        nodes: Vec<String>,
        class: String,
    },
    ClickDirective {
        node: String,
        target: String,
        tooltip: Option<String>,
        /// Browser target from `click A "url" _blank` (bd-vn7s). `None` means the author declared
        /// none, which every renderer treats as `_blank` — mermaid's default and ours.
        link_target: Option<String>,
        is_callback: bool,
    },
    /// `edgeId@{ animate: … }` — a march speed for an ALREADY-DECLARED edge.
    ///
    /// A statement, not a field on [`FlowAst::Edge`], because upstream applies it by id lookup
    /// after the fact: measured against the pinned 11.15.0 bundle, the same metadata written one
    /// line EARLIER than its edge animates nothing at all.
    EdgeAnimation {
        id: String,
        animation: EdgeAnimation,
    },
    StyleOrLinkStyle,
    ClassDef,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FlowAstNode {
    id: String,
    label: Option<ParsedLabel>,
    icon: Option<String>,
    shape: NodeShape,
    /// `:::className` classes carried from the token (bd-8n2b5), applied by `intern_flow_ast_node`.
    classes: Vec<String>,
}

impl From<NodeToken> for FlowAstNode {
    fn from(value: NodeToken) -> Self {
        Self {
            id: value.id,
            label: value.label,
            icon: value.icon,
            shape: value.shape,
            classes: value.classes,
        }
    }
}

#[derive(Debug, Clone)]
enum FlowDocumentItem<'a> {
    FastEdge {
        from: &'a str,
        arrow: ArrowType,
        to: &'a str,
        line_number: usize,
        source_line: &'a str,
    },
    FastNode {
        id: &'a str,
        label: Option<ParsedLabel>,
        icon: Option<String>,
        line_number: usize,
        source_line: &'a str,
    },
    Statements {
        asts: Vec<FlowAst>,
        line_number: usize,
        source_line: &'a str,
    },
    Subgraph {
        id: String,
        title: Option<String>,
        line_number: usize,
        source_line: &'a str,
        body: Vec<Self>,
    },
}

#[derive(Debug, Default)]
struct FlowDocumentParseResult<'a> {
    items: Vec<FlowDocumentItem<'a>>,
    warnings: Vec<String>,
    header_direction: Option<GraphDirection>,
}

#[derive(Debug, Clone)]
enum BlockBetaStatement {
    Columns(usize),
    Edges(Vec<FlowAst>),
    Blocks(Vec<BlockDef>),
}

#[derive(Debug, Clone)]
enum BlockBetaDocumentItem {
    Statement {
        statement: BlockBetaStatement,
        line_number: usize,
        source_line: String,
    },
    Group {
        id: String,
        span_cols: Option<usize>,
        line_number: usize,
        source_line: String,
        body: Vec<Self>,
    },
}

#[derive(Debug, Default)]
struct BlockBetaDocumentParseResult {
    items: Vec<BlockBetaDocumentItem>,
    warnings: Vec<String>,
}

// ---------------------------------------------------------------------------
// Chumsky flowchart statement parser (character-level on &str)
// ---------------------------------------------------------------------------
// Parses a single semicolon-free statement (trimmed line or `;`-split segment).
// Document structure (lines, comments, header) is handled by the outer loop.

/// Build a chumsky parser for a single flowchart statement.
// Error type is `EmptyErr` (not `Rich`): the caller only checks `errors.is_empty()` (success/failure)
// and discards the error content, so tracking the expected-token alternatives that `Rich` records at
// every choice point — `InputRef::add_alt` + `Vec<Located<Rich>>::truncate`, ~30% of shaped-node parse
// (hexagon/diamond/…) on SUCCESSFUL parses — is pure waste. Output-identical: the combinators and their
// success/failure are unchanged; only the discarded error detail is cheaper, and no `recover_with` uses it.
fn flow_statement_parser<'a>()
-> impl Parser<'a, &'a str, FlowAst, extra::Err<chumsky::error::EmptyErr>> {
    // -- Whitespace helpers --------------------------------------------------
    let ws_char = any().filter(|c: &char| *c == ' ' || *c == '\t');
    let inline_ws = ws_char.repeated().to(());
    let required_ws = ws_char.repeated().at_least(1).to(());

    // -- Identifier (bare word) ---------------------------------------------
    let ident = any()
        .filter(|c: &char| c.is_ascii_alphanumeric() || matches!(*c, '_' | '-' | '.' | '/'))
        .repeated()
        .at_least(1)
        .to_slice();

    // -- Node shapes ---------------------------------------------------------
    // Multi-char delimiters must be tried before single-char ones.
    // `(((x)))` is the DOUBLE circle and `((x))` is the plain circle. This rule used to match `((`
    // and call the result `DoubleCircle`, with no `(((` rule at all — so both syntaxes collapsed
    // into one shape before rendering, which is why a double circle and a circle came out
    // geometrically identical (bd-vfxu). Order matters as much as the patterns: `(((` must be tried
    // first or the `((` rule matches its opening pair and leaves a stray `)` in the label.
    let double_circle_content = just("(((")
        .ignore_then(any().and_is(just(")))").not()).repeated().to_slice())
        .then_ignore(just(")))"));

    let circle_content = just("((")
        .ignore_then(any().and_is(just("))").not()).repeated().to_slice())
        .then_ignore(just("))"));

    let hexagon_content = just("{{")
        .ignore_then(any().and_is(just("}}").not()).repeated().to_slice())
        .then_ignore(just("}}"));

    // Stadium `([…])` must precede the single-char `(…)` rule below (bd-3w93). Without it the
    // rounded rule matches — `(` opens, `[Stadium]` is consumed as ordinary content, `)` closes — so
    // the node parses as Rounded carrying its own shape delimiters as label text.
    let stadium_content = just("([")
        .ignore_then(any().and_is(just("])").not()).repeated().to_slice())
        .then_ignore(just("])"));

    // Same precedence trap as stadium, in the other direction: `[(…)]` opens with `[` and closes
    // with `]`, so the rect rule below swallows it whole and yields Rect labelled "(Database)".
    let cylinder_content = just("[(")
        .ignore_then(any().and_is(just(")]").not()).repeated().to_slice())
        .then_ignore(just(")]"));

    // The slanted family, all of which open `[` and close `]` and are therefore all swallowed by
    // the rect rule below. Each pair must be tried whole: `[/Trap\]` shares its opener with
    // `[/Para/]`, so the closing delimiter is what separates them and a rule that matched on the
    // opener alone would mis-assign them to each other.
    let parallelogram_content = just("[/")
        .ignore_then(any().and_is(just("/]").not()).repeated().to_slice())
        .then_ignore(just("/]"));

    let inv_parallelogram_content = just("[\\")
        .ignore_then(any().and_is(just("\\]").not()).repeated().to_slice())
        .then_ignore(just("\\]"));

    let trapezoid_content = just("[/")
        .ignore_then(any().and_is(just("\\]").not()).repeated().to_slice())
        .then_ignore(just("\\]"));

    let inv_trapezoid_content = just("[\\")
        .ignore_then(any().and_is(just("/]").not()).repeated().to_slice())
        .then_ignore(just("/]"));

    let rect_content = just('[')
        .ignore_then(any().filter(|c: &char| *c != ']').repeated().to_slice())
        .then_ignore(just(']'));

    let rounded_content = just('(')
        .ignore_then(any().filter(|c: &char| *c != ')').repeated().to_slice())
        .then_ignore(just(')'));

    let diamond_content = just('{')
        .ignore_then(any().filter(|c: &char| *c != '}').repeated().to_slice())
        .then_ignore(just('}'));

    let node_shape = choice((
        double_circle_content.map(|label: &str| (label, NodeShape::DoubleCircle)),
        circle_content.map(|label: &str| (label, NodeShape::Circle)),
        hexagon_content.map(|label: &str| (label, NodeShape::Hexagon)),
        stadium_content.map(|label: &str| (label, NodeShape::Stadium)),
        cylinder_content.map(|label: &str| (label, NodeShape::Cylinder)),
        parallelogram_content.map(|label: &str| (label, NodeShape::Parallelogram)),
        inv_parallelogram_content.map(|label: &str| (label, NodeShape::InvParallelogram)),
        trapezoid_content.map(|label: &str| (label, NodeShape::Trapezoid)),
        inv_trapezoid_content.map(|label: &str| (label, NodeShape::InvTrapezoid)),
        rect_content.map(|label: &str| (label, NodeShape::Rect)),
        rounded_content.map(|label: &str| (label, NodeShape::Rounded)),
        diamond_content.map(|label: &str| (label, NodeShape::Diamond)),
    ));

    let node = ident.then(node_shape.or_not()).map(
        |(id_str, shape_opt): (&str, Option<(&str, NodeShape)>)| {
            let id = id_str.to_string();
            match shape_opt {
                Some((label_raw, shape)) => {
                    let trimmed = label_raw.trim();
                    let mut label = parse_label((!trimmed.is_empty()).then_some(trimmed));
                    let icon = extract_icon_prefix(label.as_mut());
                    clear_empty_label(&mut label);
                    FlowAstNode {
                        id,
                        label,
                        icon,
                        shape,
                        // The chumsky `ident` excludes `:`, so a `:::` statement never parses here
                        // — it falls through to the manual matchers, which do carry the suffix.
                        classes: Vec::new(),
                    }
                }
                None => FlowAstNode {
                    id,
                    label: None,
                    icon: None,
                    shape: NodeShape::Rect,
                    classes: Vec::new(),
                },
            }
        },
    );

    // -- Arrow operators (longest-first) -------------------------------------
    let arrow = choice((
        just("-.->").to(ArrowType::DottedArrow),
        just("==>").to(ArrowType::ThickArrow),
        just("-->").to(ArrowType::Arrow),
        just("---").to(ArrowType::Line),
        just("--o").to(ArrowType::Circle),
        just("--x").to(ArrowType::Cross),
    ));

    // -- Pipe label  |text| -------------------------------------------------
    let pipe_label = just('|')
        .ignore_then(any().filter(|c: &char| *c != '|').repeated().to_slice())
        .then_ignore(just('|'))
        .map(|s: &str| {
            let t = s.trim();
            (!t.is_empty()).then(|| t.to_string())
        });

    // -- direction directive: direction LR ----------------------------------
    let direction = just("direction")
        .then(required_ws)
        .ignore_then(choice((
            just("LR").to(GraphDirection::LR),
            just("RL").to(GraphDirection::RL),
            just("TB").to(GraphDirection::TB),
            just("TD").to(GraphDirection::TD),
            just("BT").to(GraphDirection::BT),
        )))
        .then_ignore(inline_ws)
        .then_ignore(end())
        .map(FlowAst::Direction);

    // -- Edge: node arrow [|label|] node ------------------------------------
    let edge = node
        .then_ignore(inline_ws)
        .then(arrow)
        .then_ignore(inline_ws)
        .then(pipe_label.or_not())
        .then_ignore(inline_ws)
        .then(node)
        .then_ignore(inline_ws)
        .then_ignore(end())
        .map(|(((from, arrow_type), label_opt), to)| FlowAst::Edge {
            from,
            arrow: arrow_type,
            label: label_opt.flatten(),
            edge_id: None,
            to,
        });

    // -- class directive: class nodeA,nodeB className -----------------------
    let class_assign = just("class")
        .then(required_ws)
        .ignore_then(
            ident
                .separated_by(just(','))
                .at_least(1)
                .collect::<Vec<_>>(),
        )
        .then_ignore(required_ws)
        .then(any().repeated().at_least(1).to_slice())
        .then_ignore(end())
        .map(|(node_ids, class_raw): (Vec<&str>, &str)| {
            let nodes: Vec<String> = node_ids
                .iter()
                .map(std::string::ToString::to_string)
                .collect();
            FlowAst::ClassAssign {
                nodes,
                class: class_raw.trim().to_string(),
            }
        });

    // -- click directive: click nodeId target ["tooltip"] -------------------
    let bare_word = any()
        .filter(|c: &char| !c.is_whitespace())
        .repeated()
        .at_least(1)
        .to_slice()
        .map(|s: &str| s.to_string());

    let quoted_string = just('"')
        .ignore_then(any().filter(|c: &char| *c != '"').repeated().to_slice())
        .then_ignore(just('"'))
        .map(|s: &str| s.to_string());

    let click_callback_directive = just("click")
        .then(required_ws)
        .ignore_then(ident)
        .then_ignore(required_ws)
        .then(choice((just("call"), just("callback"))))
        .then_ignore(required_ws)
        .then(bare_word)
        .then(required_ws.ignore_then(quoted_string).or_not())
        .then_ignore(end())
        .map(
            |(((node_id, _keyword), callback), tooltip): (
                ((&str, &str), String),
                Option<String>,
            )| {
                FlowAst::ClickDirective {
                    node: node_id.to_string(),
                    target: callback,
                    tooltip,
                    // This grammar requires a QUOTED tooltip and closes with `end()`, so a bare
                    // `_blank` never parses here — it falls through to the hand-written path.
                    link_target: None,
                    is_callback: true,
                }
            },
        );

    let quoted_string_link = just('"')
        .ignore_then(any().filter(|c: &char| *c != '"').repeated().to_slice())
        .then_ignore(just('"'))
        .map(|s: &str| s.to_string());

    let quoted_string_tooltip = just('"')
        .ignore_then(any().filter(|c: &char| *c != '"').repeated().to_slice())
        .then_ignore(just('"'))
        .map(|s: &str| s.to_string());

    let click_link_directive = just("click")
        .then(required_ws)
        .ignore_then(ident)
        .then_ignore(required_ws)
        .then(quoted_string_link.or(bare_word))
        .then(required_ws.ignore_then(quoted_string_tooltip).or_not())
        .then_ignore(end())
        .map(
            |((node_id, target), tooltip): ((&str, String), Option<String>)| {
                FlowAst::ClickDirective {
                    node: node_id.to_string(),
                    target,
                    tooltip,
                    link_target: None,
                    is_callback: false,
                }
            },
        );

    let click_directive = choice((click_callback_directive, click_link_directive));

    // -- style/linkStyle/classDef (skip) ------------------------------------
    let skip_directive = choice((
        just("style ").to(()),
        just("linkStyle ").to(()),
        just("classDef ").to(()),
    ))
    .then(any().repeated())
    .then_ignore(end())
    .to(FlowAst::StyleOrLinkStyle);

    // -- Statement: try edge first (more specific), then directives, then node
    choice((
        skip_directive,
        class_assign,
        click_directive,
        direction,
        edge,
        node.then_ignore(inline_ws)
            .then_ignore(end())
            .map(FlowAst::Node),
    ))
}

// ---------------------------------------------------------------------------
// Lowering: FlowAst → IrBuilder calls
// ---------------------------------------------------------------------------

fn lower_flow_ast(
    ast: &FlowAst,
    line_number: usize,
    source_line: &str,
    builder: &mut IrBuilder,
    active_clusters: &[usize],
    active_subgraphs: &[usize],
) {
    let span = span_for(line_number, source_line);

    match ast {
        FlowAst::Direction(dir) => {
            // If inside a subgraph, set the subgraph's direction override;
            // otherwise set the global diagram direction.
            if let Some(&subgraph_index) = active_subgraphs.last() {
                builder.set_subgraph_direction(subgraph_index, *dir);
            } else {
                builder.set_direction(*dir);
            }
        }
        FlowAst::Node(n) => {
            if let Some(node_id) = intern_flow_ast_node(builder, n, span) {
                add_node_to_active_groups(builder, active_clusters, active_subgraphs, node_id);
            }
        }
        FlowAst::Edge {
            from,
            arrow,
            label,
            edge_id,
            to,
        } => {
            let from_id = intern_flow_ast_node(builder, from, span);
            let to_id = intern_flow_ast_node(builder, to, span);
            if let (Some(f), Some(t)) = (from_id, to_id) {
                add_node_to_active_groups(builder, active_clusters, active_subgraphs, f);
                add_node_to_active_groups(builder, active_clusters, active_subgraphs, t);
                builder.push_edge(f, t, *arrow, label.as_deref(), span);
                if let Some(edge_id) = edge_id {
                    builder.set_last_edge_id(edge_id);
                }
            }
        }
        FlowAst::ClassAssign { nodes, class } => {
            for class_name in class.split(',').map(trim_fast).filter(|s| !s.is_empty()) {
                for node_key in nodes {
                    // ⚠️ THE SECOND `class` PATH, and the one that actually drew the phantom box.
                    // `class one big` on a SUBGRAPH id was guarded in `extract_style_directives`
                    // (bd-xfmm), but that is a different code path: this one runs during LOWERING,
                    // earlier, and `add_class_to_node` interns whatever key it is given — so the
                    // phantom was created here and the later guard never got the chance to matter.
                    // The fix only looked correct until it was first compiled.
                    //
                    // mermaid does not create a vertex here either: `setClass` reads
                    // `let n = this.vertices.get(i); n && n.classes.push(r)` — a miss is a no-op.
                    //
                    // Skipping an unresolved key loses nothing, because `extract_style_directives`
                    // re-reads every `class` line AFTER all lowering: a node declared later in the
                    // document still gets its class there, and a SUBGRAPH id is resolved to its
                    // cluster there. This path can therefore be strictly non-interning.
                    if builder.node_id_by_key(node_key).is_some() {
                        builder.add_class_to_node(node_key, class_name, span);
                    }
                }
            }
        }
        FlowAst::ClickDirective {
            node,
            target,
            tooltip,
            link_target,
            is_callback,
        } => {
            apply_click_directive(
                builder,
                node,
                target,
                tooltip.as_ref(),
                link_target.as_ref(),
                *is_callback,
                line_number,
                span,
            );
        }
        FlowAst::EdgeAnimation { id, animation } => {
            builder.set_edge_animation(id, *animation);
        }
        FlowAst::StyleOrLinkStyle | FlowAst::ClassDef => {
            // Intentionally skipped — same as the hand-written parser
        }
    }
}

/// Apply one parsed `click` directive to a node that already exists.
///
/// EXTRACTED so the gantt path can reuse it (bd-gydqv) instead of forking it. A second copy of
/// this is exactly the shape that has bitten this file repeatedly: the safety gate, the quote
/// stripping, the callback-vs-link split and the `link_target`-only-on-links rule would all have
/// to be kept in step by hand, and the `_blank`-in-the-tooltip defect above is what that costs.
///
/// `node` is a node id that must already be interned — the setters here are non-interning, which
/// is what stops a click on an unknown id from inventing a phantom.
///
/// The parameter list is the `ClickDirective` variant's own fields plus the two the caller must
/// supply for diagnostics. Bundling them into a struct would add a type whose only purpose is to be
/// destructured immediately on both sides of one call, so the lint is allowed rather than worked
/// around — the same choice the SVG renderer makes for its stream writers.
#[allow(clippy::too_many_arguments)]
fn apply_click_directive(
    builder: &mut IrBuilder,
    node: &str,
    target: &str,
    tooltip: Option<&String>,
    link_target: Option<&String>,
    is_callback: bool,
    line_number: usize,
    span: Span,
) {
    let cleaned = target
        .trim()
        .trim_matches('"')
        .trim_matches('\'')
        .trim_matches('`')
        .trim();
    if cleaned.is_empty() {
        builder.add_warning(format!(
            "Line {line_number}: click directive target is empty after normalization"
        ));
    } else if is_callback {
        // Callback: store function name, add interactive class.
        builder.add_class_to_node(node, "has-callback", span);
        builder.set_node_callback(node, cleaned, span);
        if let Some(tip) = tooltip {
            let tip_cleaned = tip
                .trim()
                .trim_matches('"')
                .trim_matches('\'')
                .trim_matches('`')
                .trim();
            if !tip_cleaned.is_empty() {
                builder.set_node_tooltip(node, tip_cleaned, span);
            }
        }
    } else if !is_safe_link_target(cleaned, builder.sanitize_mode()) {
        builder.add_warning(format!(
            "Line {line_number}: unsafe click link target blocked: {cleaned}"
        ));
    } else {
        builder.add_class_to_node(node, "has-link", span);
        builder.set_node_link(node, cleaned, span);
        // The declared browser target, if any (bd-vn7s). Applied only on the LINK branch:
        // `setLink` is the only mermaid function that takes one, and a callback has no
        // frame to open in. Runs after `set_node_link` so the node is guaranteed to exist,
        // which is why the setter can be non-interning.
        if let Some(link_target) = link_target {
            builder.set_node_link_target(node, link_target);
        }
        if let Some(tip) = tooltip {
            let tip_cleaned = tip
                .trim()
                .trim_matches('"')
                .trim_matches('\'')
                .trim_matches('`')
                .trim();
            if !tip_cleaned.is_empty() {
                builder.set_node_tooltip(node, tip_cleaned, span);
            }
        }
    }
}

fn lower_flow_document_item(
    item: FlowDocumentItem<'_>,
    builder: &mut IrBuilder,
    active_clusters: &[usize],
    active_subgraphs: &[usize],
) {
    // `add_node_to_active_groups` only does work when a cluster or subgraph is open; on a flat
    // flowchart both are empty (this fn is entered with `&[], &[]` and only recurses non-empty inside
    // a subgraph body), so it is a no-op called ~2400×/parse (both endpoints per edge + each node).
    // Gate the calls on this once-computed flag — byte-identical (skips a provable no-op).
    let in_groups = !active_clusters.is_empty() || !active_subgraphs.is_empty();
    match item {
        FlowDocumentItem::FastEdge {
            from,
            arrow,
            to,
            line_number,
            source_line,
        } => {
            let span = span_for(line_number, source_line);
            // `from`/`to` come from `parse_fast_simple_flowchart_edge_parts`, already `trim_ascii`'d and
            // `is_fast_flow_identifier`-validated — intern through the pre-trimmed endpoint path.
            let from_id = if is_dangling_placeholder_node_id(from) {
                builder.intern_placeholder_node(from, span)
            } else {
                builder.intern_edge_endpoint_pretrimmed(from, span)
            };
            let to_id = if is_dangling_placeholder_node_id(to) {
                builder.intern_placeholder_node(to, span)
            } else {
                builder.intern_edge_endpoint_pretrimmed(to, span)
            };
            if let (Some(f), Some(t)) = (from_id, to_id) {
                if in_groups {
                    add_node_to_active_groups(builder, active_clusters, active_subgraphs, f);
                    add_node_to_active_groups(builder, active_clusters, active_subgraphs, t);
                }
                builder.push_edge(f, t, arrow, None, span);
            }
        }
        FlowDocumentItem::FastNode {
            id,
            label,
            icon,
            line_number,
            source_line,
        } => {
            // Exact mirror of the `FlowAst::Node` arm of `lower_flow_ast` / `intern_flow_ast_node`
            // for a Rect node — interns straight from the borrowed id slice. `item` is consumed by
            // value so the owned `label` is MOVED into the interner (no `String` clone; see
            // `intern_node_label_owned`) instead of being cloned from a borrow.
            let span = span_for(line_number, source_line);
            let node_id = if is_dangling_placeholder_node_id(id) {
                builder.intern_placeholder_node(id, span)
            } else {
                builder.intern_node_label_owned(id, label, NodeShape::Rect, span)
            };
            if let Some(node_id) = node_id {
                if let Some(icon) = icon.as_deref() {
                    builder.set_node_icon(node_id, icon);
                }
                if in_groups {
                    add_node_to_active_groups(builder, active_clusters, active_subgraphs, node_id);
                }
            }
        }
        FlowDocumentItem::Statements {
            asts,
            line_number,
            source_line,
        } => {
            for ast in &asts {
                lower_flow_ast(
                    ast,
                    line_number,
                    source_line,
                    builder,
                    active_clusters,
                    active_subgraphs,
                );
            }
        }
        FlowDocumentItem::Subgraph {
            id,
            title,
            line_number,
            source_line,
            body,
        } => {
            let span = span_for(line_number, source_line);
            let lookup_key = flow_subgraph_lookup_key(&id, title.as_deref());
            let Some(cluster_index) = builder.ensure_cluster(&lookup_key, title.as_deref(), span)
            else {
                return;
            };
            let parent_subgraph = active_subgraphs.last().copied();
            let Some(subgraph_index) = builder.ensure_subgraph(
                &lookup_key,
                &id,
                title.as_deref(),
                span,
                parent_subgraph,
                Some(cluster_index),
            ) else {
                return;
            };

            let mut child_clusters = active_clusters.to_vec();
            child_clusters.push(cluster_index);
            let mut child_subgraphs = active_subgraphs.to_vec();
            child_subgraphs.push(subgraph_index);

            for child in body {
                lower_flow_document_item(child, builder, &child_clusters, &child_subgraphs);
            }
        }
    }
}

fn flow_subgraph_lookup_key(id: &str, title: Option<&str>) -> String {
    match clean_label(title) {
        Some(title_text) => format!("{id}@title:{title_text}"),
        None => id.to_string(),
    }
}

/// Parsed syntax for a complete, closed flowchart-prefix subgraph.
///
/// Every related diagram seeds a worker-local reusable builder from the immutable, already-lowered
/// snapshot, then parses its unique suffix. This removes repeated tokenization, lowering,
/// interning, allocation, and membership rebuilds without coordinating workers.
#[derive(Default)]
pub(crate) struct CompiledFlowchartScratch {
    builder: Option<IrBuilder>,
    prefix_identity: Option<Arc<str>>,
    prefix_unchanged: bool,
}

pub(crate) struct CompiledFlowchartPrefix {
    prefix: Arc<str>,
    builder: IrBuilder,
    detection: DetectedType,
    line_offset: usize,
    reusable_prefix: FlowchartBatchPrefix,
}

impl CompiledFlowchartPrefix {
    pub(crate) fn new(
        prefix: &str,
        parse_mode: MermaidParseMode,
        config: &ParserConfig,
    ) -> Option<Self> {
        let detection = crate::detect_type_with_confidence_and_config(prefix, config);
        if detection.diagram_type != DiagramType::Flowchart
            || detection.method != crate::DetectionMethod::ExactKeyword
        {
            return None;
        }

        let document = parse_flowchart_document(prefix, 0, config);
        let input_lines = memchr::memchr_iter(b'\n', prefix.as_bytes()).count() + 1;
        let mut builder = IrBuilder::with_capacity_hint(DiagramType::Flowchart, input_lines);
        builder.set_parse_mode(parse_mode);
        builder.set_parser_config(*config);
        for warning in &detection.warnings {
            builder.add_warning(warning.clone());
        }
        if let Some(direction) = document.header_direction {
            builder.set_direction(direction);
        }
        for warning in document.warnings {
            builder.add_warning(warning);
        }
        for item in document.items {
            lower_flow_document_item(item, &mut builder, &[], &[]);
        }

        let line_offset = memchr::memchr_iter(b'\n', prefix.as_bytes()).count();
        let prefix: Arc<str> = Arc::from(prefix);
        Some(Self {
            reusable_prefix: FlowchartBatchPrefix {
                identity: Arc::clone(&prefix),
                node_count: builder.node_count(),
                edge_count: builder.edge_count(),
            },
            prefix,
            builder,
            detection,
            line_offset,
        })
    }

    pub(crate) fn parse(&self, input: &str) -> Option<ParseResult> {
        let suffix = input.strip_prefix(self.prefix.as_ref())?;
        let mut builder = self.builder.clone();
        parse_flowchart_with_line_offset(suffix, self.line_offset, &mut builder);
        if builder.node_count() == 0 && builder.edge_count() == 0 {
            builder.add_warning("No parseable nodes or edges were found");
        }
        Some(builder.finish(self.detection.confidence, self.detection.method))
    }

    pub(crate) fn parse_with_scratch<'a>(
        &'a self,
        input: &str,
        scratch: &'a mut CompiledFlowchartScratch,
    ) -> Option<FlowchartBatchParseRef<'a>> {
        let suffix = input.strip_prefix(self.prefix.as_ref())?;
        let same_prefix = scratch
            .prefix_identity
            .as_ref()
            .is_some_and(|identity| Arc::ptr_eq(identity, &self.prefix));
        if let Some(builder) = scratch.builder.as_mut() {
            if same_prefix && scratch.prefix_unchanged {
                builder.reset_reusable_suffix_from(&self.builder);
            } else {
                builder.reset_from(&self.builder);
            }
        } else {
            scratch.builder = Some(self.builder.clone());
        }
        if !same_prefix {
            scratch.prefix_identity = Some(Arc::clone(&self.prefix));
        }
        let builder = scratch.builder.as_mut()?;
        builder.begin_reusable_suffix(&self.builder);
        parse_flowchart_with_line_offset(suffix, self.line_offset, builder);
        if builder.node_count() == 0 && builder.edge_count() == 0 {
            builder.add_warning("No parseable nodes or edges were found");
        }
        builder.finish_reusable();
        scratch.prefix_unchanged = builder.reusable_prefix_unchanged(&self.builder);
        let reusable_prefix = scratch.prefix_unchanged.then_some(&self.reusable_prefix);
        Some(FlowchartBatchParseRef {
            ir: builder.ir(),
            warnings: builder.warnings(),
            confidence: self.detection.confidence,
            detection_method: self.detection.method,
            reusable_prefix,
        })
    }
}

/// Return the largest exact prefix containing the header followed by one or more complete,
/// top-level subgraph blocks.
///
/// Global directives are deliberately excluded: their extraction happens after whole-document
/// lowering and can refer forward into a suffix. Such inputs stay on the ordinary parser. The
/// accepted subset is therefore an isomorphism, not a best-effort cache: prefix lowering order,
/// interning order, source lines, warnings, and suffix semantics match a full parse exactly.
pub(crate) fn reusable_flowchart_prefix(input: &str) -> Option<&str> {
    let mut offset = 0usize;
    let mut saw_header = false;
    let mut saw_subgraph = false;
    let mut depth = 0usize;
    let mut last_complete_end = None;

    for raw_line in input.split_inclusive('\n') {
        let source_line = raw_line
            .strip_suffix("\r\n")
            .or_else(|| raw_line.strip_suffix('\n'))
            .unwrap_or(raw_line);
        let trimmed = trim_fast(source_line);
        let line_end = offset + raw_line.len();

        if shared_prefix_global_directive(trimmed) {
            return None;
        }

        if !saw_header {
            if trimmed.is_empty() || is_comment(trimmed) {
                offset = line_end;
                continue;
            }
            if !is_flowchart_header(trimmed) {
                return None;
            }
            saw_header = true;
            offset = line_end;
            continue;
        }

        if depth == 0 {
            if trimmed.is_empty() || is_comment(trimmed) {
                offset = line_end;
                continue;
            }
            if is_subgraph_block_start(trimmed) {
                depth = 1;
                saw_subgraph = true;
                offset = line_end;
                continue;
            }
            break;
        }

        if is_subgraph_block_start(trimmed) {
            depth += 1;
        } else if trimmed == "end" {
            depth -= 1;
            if depth == 0 {
                last_complete_end = Some(line_end);
            }
        }
        offset = line_end;
    }

    let end = last_complete_end?;
    if !saw_header || !saw_subgraph || depth != 0 || end >= input.len() || end < 128 {
        return None;
    }

    // Directives in the suffix can target prefix nodes, so the whole input must be free of the
    // post-lowering global directive families before prefix compilation is legal.
    if byte_lines(&input[end..])
        .map(trim_fast)
        .any(shared_prefix_global_directive)
    {
        return None;
    }
    Some(&input[..end])
}

/// Return the largest reusable complete-subgraph prefix ending at or before `byte_limit`.
///
/// The caller has already found a common byte prefix across a batch. Reusing only a complete
/// top-level subgraph boundary keeps the compiled fragment isomorphic to an ordinary full parse;
/// partial lines and partial nested subgraphs are never admitted.
pub(crate) fn reusable_flowchart_prefix_at_or_before(
    input: &str,
    byte_limit: usize,
) -> Option<&str> {
    let largest_prefix = reusable_flowchart_prefix(input)?;
    let byte_limit = byte_limit.min(largest_prefix.len());
    let mut offset = 0usize;
    let mut saw_header = false;
    let mut depth = 0usize;
    let mut candidate_end = None;

    for raw_line in largest_prefix.split_inclusive('\n') {
        let source_line = raw_line
            .strip_suffix("\r\n")
            .or_else(|| raw_line.strip_suffix('\n'))
            .unwrap_or(raw_line);
        let trimmed = trim_fast(source_line);
        let line_end = offset + raw_line.len();

        if !saw_header {
            if !trimmed.is_empty() && !is_comment(trimmed) {
                saw_header = true;
            }
        } else if is_subgraph_block_start(trimmed) {
            depth += 1;
        } else if trimmed == "end" {
            depth = depth.saturating_sub(1);
            if depth == 0 && line_end >= 128 && line_end <= byte_limit {
                candidate_end = Some(line_end);
            }
        }
        offset = line_end;
    }

    candidate_end.map(|end| &input[..end])
}

/// Check another batch input against an already-validated reusable prefix.
///
/// The expensive structural walk belongs to the first member of an exact-prefix group. Subsequent
/// members only need a vectorized byte-prefix comparison plus a scan of their unique suffix for
/// directives whose scope could cross the boundary.
pub(crate) fn can_reuse_flowchart_prefix(input: &str, prefix: &str) -> bool {
    let Some(suffix) = input.strip_prefix(prefix) else {
        return false;
    };
    !suffix.is_empty()
        && !byte_lines(suffix)
            .map(trim_fast)
            .any(shared_prefix_global_directive)
}

fn is_subgraph_block_start(line: &str) -> bool {
    line.strip_prefix("subgraph")
        .is_some_and(|rest| rest.chars().next().is_some_and(char::is_whitespace))
}

fn shared_prefix_global_directive(line: &str) -> bool {
    line.starts_with("%%{")
        || is_non_graph_statement(line)
        || line.starts_with("accTitle")
        || line.starts_with("accDescr")
}

// ---------------------------------------------------------------------------
// Top-level parse_flowchart — line-by-line with chumsky statement parser
// ---------------------------------------------------------------------------

fn parse_flowchart(input: &str, builder: &mut IrBuilder) {
    parse_flowchart_with_line_offset(input, 0, builder);
}

/// Parse a flowchart fragment whose first line follows `line_offset` lines already compiled into
/// `builder`.
///
/// A render batch can contain many diagrams that begin with the same complete subgraph block. The
/// shared-prefix compiler lowers that block once, clones the interned builder state, and sends only
/// each unique suffix through this function. Offsetting line numbers preserves the exact spans and
/// diagnostics that a full-source parse would produce.
fn parse_flowchart_with_line_offset(input: &str, line_offset: usize, builder: &mut IrBuilder) {
    let document = parse_flowchart_document(input, line_offset, builder.parser_config());
    if let Some(direction) = document.header_direction {
        builder.set_direction(direction);
    }
    for warning in &document.warnings {
        builder.add_warning(warning.clone());
    }
    for item in document.items {
        lower_flow_document_item(item, builder, &[], &[]);
    }

    // Extract style directives from the raw input and add to IR.
    // This runs AFTER lowering so node IDs are resolved for `style nodeId` lookups.
    extract_style_directives(input, builder);
}

/// Iterator over `input`'s lines, byte-identical to [`str::lines`] but implemented with a
/// `[u8]::position(== b'\n')` byte scan instead of `lines()`'s single-`char` `'\n'` `CharSearcher`.
/// `str::lines()`'s CharSearcher `next_match` measured as a top parse self-time symbol (~6% of
/// flowchart parse), and every diagram parser scans the input line-by-line. Semantics match
/// `lines()` exactly: split on `\n`, strip one trailing `\r` per line, and do not yield a trailing
/// empty line after a final `\n`. Pinned against `str::lines()` by `byte_lines_matches_std_lines`.
struct ByteLines<'a> {
    input: &'a str,
    start: usize,
}

impl<'a> Iterator for ByteLines<'a> {
    type Item = &'a str;

    fn next(&mut self) -> Option<&'a str> {
        let bytes = self.input.as_bytes();
        if self.start > bytes.len() {
            return None;
        }
        match memchr::memchr(b'\n', &bytes[self.start..]) {
            Some(rel) => {
                let nl = self.start + rel;
                let end = if nl > self.start && bytes[nl - 1] == b'\r' {
                    nl - 1
                } else {
                    nl
                };
                let line = &self.input[self.start..end];
                self.start = nl + 1;
                Some(line)
            }
            None => {
                // Final segment (no more `\n`). `lines()` yields it only when non-empty and never
                // yields a trailing empty line after a final `\n`; mark exhausted either way. A
                // trailing `\r` here is a LONE carriage return (not a `\r\n` terminator), which
                // `str::lines()` does NOT strip — so the final segment is emitted verbatim.
                let out = if self.start < bytes.len() {
                    Some(&self.input[self.start..])
                } else {
                    None
                };
                self.start = bytes.len() + 1;
                out
            }
        }
    }
}

/// Byte-based [`str::lines`] replacement — see [`ByteLines`].
fn byte_lines(input: &str) -> ByteLines<'_> {
    ByteLines { input, start: 0 }
}

fn parse_flowchart_document<'a>(
    input: &'a str,
    line_offset: usize,
    config: &ParserConfig,
) -> FlowDocumentParseResult<'a> {
    let lines: Vec<(usize, &str)> = byte_lines(input)
        .enumerate()
        .map(|(i, line)| (line_offset + i + 1, line))
        .collect();
    let mut next_index = 0;
    let mut warnings = Vec::new();
    let mut header_direction = None;
    let (items, unclosed_subgraphs) = parse_flowchart_document_items(
        &lines,
        &mut next_index,
        true,
        &mut warnings,
        &mut header_direction,
        config,
        0,
    );
    if unclosed_subgraphs > 0 {
        warnings.push(format!(
            "Flowchart ended with {unclosed_subgraphs} unclosed subgraph block(s)"
        ));
    }
    FlowDocumentParseResult {
        items,
        warnings,
        header_direction,
    }
}

/// ASCII-fast equivalent of [`str::trim`], byte-identical on the common all-ASCII-boundary case.
///
/// The flowchart document loop trims every source line and every `;`-split statement; `str::trim`
/// uses the Unicode `char::is_whitespace` char scan, which a symbolized parse profile showed as
/// ~4.5% of parse self-time. This trims ASCII whitespace by byte, then falls back to `str::trim`
/// only when a non-ASCII byte sits at a trimmed boundary — where a multi-byte Unicode-whitespace
/// char could remain — so the returned slice is exactly what `str::trim` would return in every case.
pub(crate) fn trim_fast(s: &str) -> &str {
    let b = s.as_bytes();
    let mut start = 0;
    let mut end = b.len();
    while start < end && b[start].is_ascii_whitespace() {
        start += 1;
    }
    while end > start && b[end - 1].is_ascii_whitespace() {
        end -= 1;
    }
    // A non-ASCII byte at either trimmed boundary may be part of a Unicode-whitespace char that
    // `str::trim` would strip but the ASCII scan above left in place — defer to `str::trim` to stay
    // byte-identical. Otherwise both boundaries sit on ASCII bytes (always char boundaries), so the
    // slice is valid and identical to the Unicode trim.
    if start < end && (b[start] >= 0x80 || b[end - 1] >= 0x80) {
        return s.trim();
    }
    &s[start..end]
}

/// `str::trim_start` equivalent that skips ASCII leading whitespace by byte (auto-vectorizable),
/// falling back to the Unicode `char::is_whitespace` scan only when a non-ASCII byte sits at the
/// trimmed start boundary — where a multi-byte Unicode-whitespace char could remain. Byte-identical
/// to `str::trim_start` in every case; used on the per-statement flowchart path where a symbolized
/// profile showed `trim_start_matches::<char::is_whitespace>` as a self-symbol.
fn trim_start_fast(s: &str) -> &str {
    let b = s.as_bytes();
    let mut start = 0;
    while start < b.len() && b[start].is_ascii_whitespace() {
        start += 1;
    }
    // A non-ASCII byte at the trimmed start may begin a Unicode-whitespace char the ASCII scan left;
    // defer to `str::trim_start` to stay byte-identical. Otherwise `start` sits on an ASCII byte (a
    // char boundary), so the slice is valid and identical to the Unicode trim.
    if start < b.len() && b[start] >= 0x80 {
        return s.trim_start();
    }
    &s[start..]
}

/// `str::trim_end` equivalent that skips ASCII trailing whitespace by byte, falling back to the
/// Unicode `char::is_whitespace` scan only when a non-ASCII byte sits at the trimmed end boundary —
/// where a multi-byte Unicode-whitespace char could remain. Byte-identical to `str::trim_end` in
/// every case; used on the class-relation parse path where a symbolized profile showed
/// `trim_end_matches::<char::is_whitespace>` / `CharSearcher::next_match_back` as self-symbols.
fn trim_end_fast(s: &str) -> &str {
    let b = s.as_bytes();
    let mut end = b.len();
    while end > 0 && b[end - 1].is_ascii_whitespace() {
        end -= 1;
    }
    // A non-ASCII byte at the trimmed end may be part of a Unicode-whitespace char the ASCII scan
    // left; defer to `str::trim_end` to stay byte-identical. Otherwise `end` sits just past an ASCII
    // byte (a char boundary), so the slice is valid and identical to the Unicode trim.
    if end > 0 && b[end - 1] >= 0x80 {
        return s.trim_end();
    }
    &s[..end]
}

fn parse_flowchart_document_items<'a>(
    lines: &[(usize, &'a str)],
    next_index: &mut usize,
    is_root: bool,
    warnings: &mut Vec<String>,
    header_direction: &mut Option<GraphDirection>,
    config: &ParserConfig,
    depth: usize,
) -> (Vec<FlowDocumentItem<'a>>, usize) {
    // Pre-size to the number of remaining lines: each source line yields at most a small
    // constant number of document items (usually exactly one node/edge), so this is a tight
    // upper bound that removes the ~log2(N) reallocs the empty `Vec::new()` incurred while
    // growing to hundreds/thousands of items on wide flowcharts. Recursive subgraph-body
    // calls over-estimate (the body ends before end-of-input), but the unused tail capacity
    // is never written, so its pages never fault — it costs address space, not RSS or time.
    let mut items = Vec::with_capacity(lines.len().saturating_sub(*next_index));
    let mut unclosed_subgraphs = 0;
    // `subgraph` opens seen at the depth cap and flattened into THIS level instead of
    // recursing. Their `end`s must still be swallowed here, or the first one would close
    // the enclosing block early and desynchronize the whole document.
    let mut flattened_opens = 0_usize;
    let mut depth_warned = false;
    // Inside a multi-line `accDescr { … }` block (bd-0di8). Its BODY lines look like ordinary node
    // statements, so without this the description text is interned as nodes of its own.
    let mut in_acc_descr_block = false;

    while let Some((line_number, line)) = lines.get(*next_index).copied() {
        *next_index += 1;

        let trimmed = trim_fast(line);
        if trimmed.is_empty() || is_comment(trimmed) {
            continue;
        }

        // Accessibility directives are extracted from the original input AFTER parsing, so they
        // need no item here — but they must not fall through to the node fallback either, which
        // interned `accTitle: My Title` as a NODE displayed as that text and announced to screen
        // readers as `aria-label="accTitle: My Title"` on a role="graphics-symbol". The directive
        // meant to improve accessibility was degrading it. The class path has guarded this all
        // along via `is_class_non_node_statement`; the flowchart path was the outlier, exactly as
        // it was for subgraph titles in bd-ka77.
        if in_acc_descr_block {
            if trimmed == "}" || trimmed.ends_with('}') {
                in_acc_descr_block = false;
            }
            continue;
        }
        // bd-ij0f: `title My Flow` was still interned as `title_My_Flow` after bd-0di8 covered the
        // accessibility pair.
        //
        // ⚠️ ONLY `title` here, deliberately. The flowchart path already HANDLES
        // classDef/style/linkStyle via `is_non_graph_statement`, and `click …` as a real
        // `FlowAst::ClickDirective`. Applying the whole shared predicate on this path swallowed
        // `click` before it was parsed and broke eight click tests; a guard belongs only where the
        // path would otherwise intern a phantom.
        //
        // ⚠️ THIS COMMENT USED TO CLAIM click/link/callback WERE ALL HANDLED HERE, AND ONLY `click`
        // EVER WAS (bd-rnc6l). Both grammars are `just("click")`, so a bare `link A "url"` or
        // `callback A fn "tip"` fell through to the node parser and was DRAWN. The guard for those
        // three is immediately below.
        if trimmed
            .strip_prefix("title")
            .is_some_and(|rest| rest.starts_with(char::is_whitespace))
        {
            continue;
        }
        // ⚠️ AND `click`'s THREE SIBLINGS, which this path does NOT parse (bd-rnc6l). The comment
        // above says click/link/callback arrive as `FlowAst::ClickDirective`; that is true of the
        // `click …` spellings only — the grammar is `just("click")`. A bare `link A "url"`,
        // `callback A fn "tip"` or `cssClass "A" mine` fell straight through to the node parser and
        // was DRAWN as a box captioned with the directive. mermaid rejects all three outright,
        // measured in Chromium 151 against the pinned 11.15.0 bundle, with and without the
        // `classDef` the cssClass docs pair it with — so the box is ours alone.
        //
        // `click` is deliberately NOT in this list: swallowing it here is exactly what broke eight
        // click tests in bd-ij0f.
        if starts_with_directive_keyword(trimmed, &UNPARSED_INTERACTION_DIRECTIVES) {
            continue;
        }
        if let Some(rest) = flowchart_accessibility_directive(trimmed) {
            // `accDescr {` opens a block whose body must be swallowed too; `accDescr: text` and
            // `accTitle: text` are complete on their own line.
            if rest.starts_with('{') && !rest.contains('}') {
                in_acc_descr_block = true;
            }
            continue;
        }

        // Single byte scan for the only two bytes that drive the comment-strip (`%`) and statement-split
        // (`;`) passes; a line with neither — the overwhelmingly common case — is one clean statement
        // equal to `trimmed`, so skip both passes (their per-line calls AND their internal `%`/`;` scans)
        // entirely. Byte-identical: `strip_flowchart_inline_comment` returns `trimmed` unchanged when there
        // is no `%`, and `split_statements` yields exactly `[trimmed]` when there is no `;`.
        let has_special = memchr::memchr2(b'%', b';', trimmed.as_bytes()).is_some();
        let uncommented_line = if has_special {
            strip_flowchart_inline_comment(trimmed)
        } else {
            trimmed
        };
        if uncommented_line.is_empty() {
            continue;
        }

        // Push document items straight into `items` rather than staging them in a per-line `Vec` that is
        // immediately `extend`ed in — that staging Vec allocated once per content line (~1 alloc/statement
        // on wide flowcharts) for no benefit: every branch below flushes it unconditionally (the bottom
        // `extend` on normal completion, or the `end` early-return), and items keep insertion order either
        // way. Removing it is behavior-identical.
        let mut parsed_line = false;

        let statements = if has_special {
            split_statements(uncommented_line)
        } else {
            SplitStatements::Single(std::iter::once(uncommented_line))
        };
        for statement in statements {
            // `split_statements` already yields trimmed segments: its `;`-split path `trim`s each
            // segment, and its no-`;` fast path yields `uncommented_line` verbatim — which is itself
            // the `trim_fast`'d `trimmed` (optionally `trim_end`'d by comment stripping). So this
            // statement is already trimmed; the previous `trim_fast(statement)` here re-scanned it for
            // nothing. Downstream `parse_fast_simple_*` still trim their input defensively.
            let normalized_statement = statement;
            if normalized_statement.is_empty() {
                parsed_line = true;
                continue;
            }

            if is_flowchart_header(normalized_statement) {
                if !is_root {
                    warnings.push(format!(
                        "Line {line_number}: nested flowchart header ignored inside subgraph"
                    ));
                } else if let Some(dir) = parse_graph_direction(normalized_statement) {
                    *header_direction = Some(dir);
                }
                parsed_line = true;
                continue;
            }

            if let Some((cluster_key, cluster_title)) =
                parse_subgraph_statement(normalized_statement, config)
            {
                // Nesting depth is stack depth here (recursive descent, a recursively
                // nested item tree, and a recursive `Drop` for it), and input SIZE does not
                // bound it: an unindented `subgraph S\n…\nend\n` pair costs a constant
                // handful of bytes per level. Past the cap, flatten the block into this
                // level rather than recursing: its nodes and edges still land in `items`,
                // only the surplus grouping is lost.
                if depth >= config.max_nesting_depth {
                    if !depth_warned {
                        depth_warned = true;
                        warnings.push(format!(
                            "Line {line_number}: subgraph nesting deeper than {} is flattened",
                            config.max_nesting_depth
                        ));
                    }
                    flattened_opens += 1;
                    parsed_line = true;
                    continue;
                }
                let (body, child_unclosed) = parse_flowchart_document_items(
                    lines,
                    next_index,
                    false,
                    warnings,
                    header_direction,
                    config,
                    depth + 1,
                );
                unclosed_subgraphs += child_unclosed;
                items.push(FlowDocumentItem::Subgraph {
                    id: cluster_key,
                    title: cluster_title,
                    line_number,
                    source_line: line,
                    body,
                });
                parsed_line = true;
                continue;
            }

            if normalized_statement == "end" {
                // Close a flattened open before this level's own `end`: those blocks were
                // absorbed here, so their terminators belong to this frame.
                if flattened_opens > 0 {
                    flattened_opens -= 1;
                    parsed_line = true;
                    continue;
                }
                if !is_root {
                    return (items, unclosed_subgraphs);
                }
                warnings.push(format!(
                    "Line {line_number}: encountered 'end' without matching 'subgraph'"
                ));
                parsed_line = true;
                continue;
            }

            if let Some((from, arrow, to)) =
                parse_fast_simple_flowchart_edge_parts(normalized_statement)
            {
                items.push(FlowDocumentItem::FastEdge {
                    from,
                    arrow,
                    to,
                    line_number,
                    source_line: line,
                });
                parsed_line = true;
                continue;
            }

            // Simple `id` / `id[label]` node statement: intern straight from the borrowed slice,
            // skipping the `FlowAst::Node` String + single-element `vec![ast]` the general path makes.
            // Same matcher (and the same edge-before-node priority) as the fast path inside
            // `parse_flowchart_statement_asts`, so this is behavior-identical — only allocation-cheaper.
            if let Some((id, label, icon)) =
                parse_fast_simple_flowchart_node_borrowed(normalized_statement)
            {
                items.push(FlowDocumentItem::FastNode {
                    id,
                    label,
                    icon,
                    line_number,
                    source_line: line,
                });
                parsed_line = true;
                continue;
            }

            if let Some(asts) = parse_flowchart_statement_asts(
                normalized_statement,
                line_number,
                line,
                warnings,
                config,
            ) {
                items.push(FlowDocumentItem::Statements {
                    asts,
                    line_number,
                    source_line: line,
                });
                parsed_line = true;
            }
        }

        if !parsed_line {
            warnings.push(format!(
                "Line {line_number}: unsupported flowchart syntax: {trimmed}"
            ));
        }
    }

    // Reaching end-of-input with flattened opens outstanding means those blocks never got
    // an `end`; report them like any other unclosed subgraph.
    unclosed_subgraphs += flattened_opens;
    if !is_root {
        unclosed_subgraphs += 1;
    }

    (items, unclosed_subgraphs)
}

/// Byte index of the first `:::` (the inline-class suffix) in `s`, or `None`. Locates it via `memchr`
/// on `:` plus a cheap prefix verify, avoiding the `TwoWaySearcher` (maximal-suffix factorization) that
/// `str::contains(":::")` / `str::split(":::")` build per call — a per-statement + per-`:::`-node cost on
/// flowchart parse. Byte-identical to those std searches (memchr keeps the SIMD first-byte skip, so a
/// `:`-free statement — the common plain flowchart line — returns `None` in one vectorized scan).
fn find_triple_colon(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut from = 0;
    while let Some(rel) = memchr::memchr(b':', &bytes[from..]) {
        let idx = from + rel;
        if bytes[idx..].starts_with(b":::") {
            return Some(idx);
        }
        from = idx + 1;
    }
    None
}

fn parse_flowchart_statement_asts(
    statement: &str,
    line_number: usize,
    source_line: &str,
    warnings: &mut Vec<String>,
    config: &ParserConfig,
) -> Option<Vec<FlowAst>> {
    if let Some(ast) = parse_fast_simple_flowchart_statement_ast(statement) {
        return Some(vec![ast]);
    }

    // A trailing `:::className` inline-class suffix has no rule in `flow_statement_parser`: the node
    // grammar requires `end()` immediately after the shape, so any node statement carrying a `:::`
    // suffix fails the full chumsky parse and falls through to the cheaper manual matchers below (which
    // strip the suffix via `parse_node_token_with_config`). Skipping the doomed combinator attempt for
    // exactly those statements saves ~1.1 µs/node on styled flowcharts (measured). The guard fires only
    // when chumsky provably fails: `style `/`linkStyle `/`classDef ` still parse via `skip_directive`,
    // and any statement with a flow operator (e.g. `A -->|x:::y| B`, `A:::x --> B`) keeps its normal
    // edge handling — both stay on the chumsky path. Behavior-identical: for the skipped statements
    // chumsky returned a parse error and contributed nothing.
    // Capture the operator position for `:::`-class statements ONCE: the chumsky-skip guard AND the
    // edge-vs-node decision at the tail both need it, and on a long `:::`-suffixed node line (styled
    // flowcharts) `find_operator` was re-scanning the whole statement up to 3× (guard + the tail's
    // `parse_edge_statement_asts` + its `is_some()` re-check). Non-`:::` statements keep the lazy path,
    // so plain flowcharts (no `:::`) do not pay an extra scan.
    let class_suffix_op = find_triple_colon(statement).is_some().then(|| {
        // Every flow operator starts with one of `- < = .` (the first bytes of `FLOW_OPERATORS` /
        // `FLOW_OP_GATE`). A `:::` node declaration (`A[Label]:::class…`) contains none of them, so this
        // auto-vectorizing byte-set scan skips the depth-tracking `find_operator` SCALAR scan of the
        // (often long) node line. Byte-identical: no such byte ⇒ no operator ⇒ `find_operator` is `None`.
        statement
            .as_bytes()
            .iter()
            .any(|&b| matches!(b, b'-' | b'<' | b'=' | b'.'))
            .then(|| find_operator(statement, &FLOW_OPERATORS, FLOW_OP_GATE))
            .flatten()
    });
    let chumsky_would_fail = matches!(
        &class_suffix_op,
        Some(op)
            if op.is_none()
                && !statement.starts_with("style ")
                && !statement.starts_with("linkStyle ")
                && !statement.starts_with("classDef ")
    );
    // ⚠️ THE THIRD DOOR TO A NODE ID (bd-6s6sx). `fast_path_cannot_classify_run` guards the two
    // hand-written fast paths, but the CHUMSKY grammar is a third way in and it is tried first:
    // its `ident` accepts `-` and `.` as identifier bytes, so `A---xB` and `A-.-B` are perfectly
    // good node names to it. It answered `FlowAst::Node` before the full operator matcher ever saw
    // the statement, which is why the deferral looked inert on both the statement and document
    // paths even with both fast-path guards in place.
    //
    // Same predicate, same rule, one more door — rather than teaching the chumsky grammar about
    // runs, which would put the rule in two places.
    if !chumsky_would_fail && !fast_path_cannot_classify_run(statement) {
        let (ast, errors) = flow_statement_parser()
            .parse(statement)
            .into_output_errors();
        if errors.is_empty()
            && let Some(ast_node) = ast
        {
            return Some(vec![ast_node]);
        }
    }

    if let Some(ast) = parse_class_assignment_ast(statement) {
        return Some(vec![ast]);
    }
    // Returns one `ClickDirective` PER NODE — `click A,B "url"` is two (bd-8mlk).
    if let Some(asts) = parse_click_directive_ast(statement, line_number, warnings) {
        return Some(asts);
    }
    if is_non_graph_statement(statement) {
        // Parse the style directive into IR style refs instead of discarding.
        // We still return StyleOrLinkStyle to the chumsky lowerer (which skips it),
        // but the side effect populates ir.style_refs via the builder.
        return Some(vec![FlowAst::StyleOrLinkStyle]);
    }
    // Reuse the `:::`-class operator position found above to avoid re-scanning: a `:::` node line has
    // no operator, so it goes straight to `parse_node_token_with_config` — skipping the edge-parse scan
    // and its `is_some()` re-scan (styled flowcharts are node-declaration-heavy). Non-`:::` statements
    // take the original lazy path. Byte-identical: `parse_edge_statement_asts` returns `None` for a
    // no-operator statement anyway, and the `is_some()` branch only mattered when an operator existed.
    match &class_suffix_op {
        Some(op) => {
            if op.is_some() {
                if let Some(asts) = parse_edge_statement_asts(
                    statement,
                    &FLOW_OPERATORS,
                    FLOW_OP_GATE,
                    true,
                    config,
                    line_number,
                ) {
                    return Some(asts);
                }
                return None;
            }
        }
        None => {
            if let Some(asts) = parse_edge_statement_asts(
                statement,
                &FLOW_OPERATORS,
                FLOW_OP_GATE,
                true,
                config,
                line_number,
            ) {
                return Some(asts);
            }
            if find_operator(statement, &FLOW_OPERATORS, FLOW_OP_GATE).is_some() {
                return None;
            }
        }
    }
    // `id@{ shape: …, label: … }` before the generic node token parse (bd-9x8r): otherwise the whole
    // directive is interned as one node whose displayed name is the directive text.
    if let Some(handled) = parse_flowchart_node_metadata(statement, config, warnings) {
        // `Nothing` = recognised as `@{…}` metadata but declaring no node and addressing no edge.
        // Returning an empty statement list is what stops the generic fallback below from interning
        // the directive text (bd-yrxu).
        return Some(match handled {
            FlowMetadata::Node(node) => vec![FlowAst::Node(*node)],
            FlowMetadata::EdgeAnimation { id, animation } => {
                vec![FlowAst::EdgeAnimation { id, animation }]
            }
            FlowMetadata::Nothing => Vec::new(),
        });
    }

    if let Some(node) = parse_node_token_with_config(statement, config) {
        return Some(vec![FlowAst::Node(FlowAstNode {
            id: node.id,
            label: node.label,
            icon: node.icon,
            shape: node.shape,
            // The bare `A[Label]:::urgent` declaration — one of the two positions that was silently
            // dropping the class. The token already carries it; it just has to survive the move.
            classes: node.classes,
        })]);
    }

    let _ = source_line;
    None
}

/// True when a statement is a non-node DIRECTIVE rather than a node declaration (bd-ij0f).
///
/// Three partial guards existed — `is_class_non_node_statement` (class), `is_non_graph_statement`
/// (style/classDef/linkStyle) and `flowchart_accessibility_directive` (bd-0di8) — and no path
/// covered everything, so each unguarded combination interned the directive text as a phantom node:
/// `title My State` became a node `title_My_State`, `click A "…"` became `click_A`, and so on. The
/// phantom also carried the raw syntax as its accessible name, so assistive technology announced it.
///
/// Keys on the DIRECTIVE FORM — the keyword followed by whitespace, or by `:` for the accessibility
/// pair — never on the bare identifier. That is what keeps a node legitimately named `title[Box]`
/// or `click(Round)` a node.
fn is_non_node_directive_statement(statement: &str) -> bool {
    let statement = trim_fast(statement);
    let followed_by_space = |name: &str| {
        statement
            .strip_prefix(name)
            .is_some_and(|rest| rest.starts_with(char::is_whitespace))
    };
    // `accTitle`/`accDescr` accept `:` immediately, and `accDescr` may open a `{` block.
    let accessibility = |name: &str| {
        statement.strip_prefix(name).is_some_and(|rest| {
            rest.starts_with(':') || rest.starts_with(char::is_whitespace) || rest.is_empty()
        })
    };

    accessibility("accTitle")
        || accessibility("accDescr")
        || followed_by_space("title")
        || followed_by_space("style")
        || followed_by_space("classDef")
        || followed_by_space("linkStyle")
        || followed_by_space("cssClass")
        || followed_by_space("click")
        || followed_by_space("link")
        || followed_by_space("callback")
}

/// The interaction directives, as author-facing first tokens.
///
/// `click` is separated from the rest because the flowchart path PARSES it into a real
/// `FlowAst::ClickDirective`, and swallowing it before that broke eight click tests once already
/// (bd-ij0f). Every other family reaches these lines with nothing to do but ignore them.
const INTERACTION_DIRECTIVES: [&str; 4] = ["click", "link", "callback", "cssClass"];

/// The three the flowchart path does NOT parse — `INTERACTION_DIRECTIVES` minus `click`.
const UNPARSED_INTERACTION_DIRECTIVES: [&str; 3] = ["link", "callback", "cssClass"];

/// The interaction directives `journey` must NOT swallow, because the reference draws them here.
///
/// ⚠️ MEASURED AS EXACT DRAWN TEXT, NOT AS A SUBSTRING MATCH (bd-umqc6). mermaid's journey takes
/// `click A "https://example.com"` as a TASK and captions it `click A "https` — truncated at the
/// URL's own colon, because a journey line is `text: score: actors`. We produce the identical
/// caption. That is real agreement rather than two manglings that merely share a substring, which
/// is what a `contains("click A")` check could not have told apart.
///
/// So `click` and `link` stay content here, and only the two the reference refuses are guarded.
const JOURNEY_INTERACTION_DIRECTIVES: [&str; 2] = ["callback", "cssClass"];

/// The same for `timeline`, which inverts journey's answer.
///
/// ⚠️ THE TWO FAMILIES DISAGREE WITH EACH OTHER, AND THAT IS THE REFERENCE'S DOING. A timeline line
/// is `period : event`, so `cssClass "A" mine` — no colon — is taken as a PERIOD and drawn, while
/// `click A "url"` is refused; journey's colon-bearing URL makes it the other way round. There is no
/// rule behind it to implement, only two grammars' accidents, so this is a MEASURED LIST and not a
/// derived one. Reproducing the accident itself, by sniffing the line for colons, would be
/// conformance metastasis.
const TIMELINE_INTERACTION_DIRECTIVES: [&str; 3] = ["click", "link", "callback"];

/// True when `statement` opens with one of `keywords` used as a DIRECTIVE — keyword, then space.
///
/// ⚠️ ONE FUNCTION WITH AN EXPLICIT LIST PER CALL SITE, NOT TWO NEAR-IDENTICAL PREDICATES. The lists
/// genuinely differ by family (see `INTERACTION_DIRECTIVES`), and a second copy of this matcher is
/// how the duplicated-helper defects in this parser have started — one copy gets fixed, its fork
/// does not.
///
/// ⚠️ AND IT KEYS ON THE KEYWORD PLUS WHITESPACE, never on a bare prefix, so `linkage` and
/// `clickable` are still node ids.
fn starts_with_directive_keyword(statement: &str, keywords: &[&str]) -> bool {
    let statement = trim_fast(statement);
    keywords.iter().any(|name| {
        statement
            .strip_prefix(name)
            .is_some_and(|rest| rest.starts_with(char::is_whitespace))
    })
}

/// True for a DIAGRAM-LEVEL directive that is extracted centrally and must never become content.
///
/// ⚠️ THE POINT IS THE RENDERED OUTPUT, NOT THE WARNING. `direction TB` and `title X` were reaching
/// the node parsers of six families and being DRAWN — a box captioned with the author's own
/// directive, sitting in the diagram, exactly the phantom bd-871ka found for
/// `hide empty description` and bd-9x8r for `shape:`. Measured against the pinned mermaid 11.15.0
/// bundle, four of those six disagree with the reference outright: class, er and timeline parse
/// `direction` and draw nothing, and packet does the same for `title` (bd-92kw1).
///
/// ⚠️ NARROWER THAN [`is_non_node_directive_statement`] ON PURPOSE, in the other direction. That one
/// also swallows `click`/`link`/`callback`/`style`, which some paths parse into real items —
/// swallowing a directive a path already handles is a regression, not a fix, and bd-ij0f broke eight
/// click tests that way. These two are safe everywhere they are used below because every caller
/// either has no concept of them or honours them explicitly before this is reached.
///
/// ⚠️ AND `block-beta` DELIBERATELY DOES NOT USE THIS. mermaid's block renderer DRAWS a stray
/// `direction` line as a block — measured, both engines agree — so adding the skip there would
/// replace agreement with a divergence.
fn is_diagram_level_directive_statement(statement: &str) -> bool {
    let statement = trim_fast(statement);
    ["direction", "title"].iter().any(|name| {
        statement
            .strip_prefix(name)
            .is_some_and(|rest| rest.starts_with(char::is_whitespace))
    })
}

/// True for an accessibility directive only — `accTitle:` / `accDescr:` / `accDescr {` (bd-7oyz).
///
/// Deliberately NARROWER than `is_non_node_directive_statement`. Paths differ in which directives
/// they already parse into real items: timeline promotes `title …` into diagram meta, and the
/// flowchart path parses `click`/`link`/`callback` into `FlowAst::ClickDirective`. Swallowing a
/// directive a path already handles is a regression, not a fix — bd-ij0f broke eight click tests
/// that way and this predicate exists so the remaining paths can be guarded without repeating it.
fn is_accessibility_directive_statement(statement: &str) -> bool {
    let statement = trim_fast(statement);
    ["accTitle", "accDescr"].iter().any(|name| {
        statement.strip_prefix(name).is_some_and(|rest| {
            rest.starts_with(':') || rest.starts_with(char::is_whitespace) || rest.is_empty()
        })
    })
}

/// Recognise a flowchart accessibility directive, returning what follows the keyword (bd-0di8).
///
/// Matches `accTitle: …`, `accDescr: …` and the block opener `accDescr {`. Keys on the DIRECTIVE
/// form — the keyword followed by `:` or whitespace — rather than on the identifier, so a node
/// legitimately named `accTitle` (`accTitle[Box]`) is still a node.
///
/// Mirrors the `accessibility(..)` arm of `is_class_non_node_statement`, which has guarded the class
/// path against this since it was written.
fn flowchart_accessibility_directive(statement: &str) -> Option<&str> {
    for keyword in ["accTitle", "accDescr"] {
        if let Some(rest) = statement.strip_prefix(keyword) {
            let rest_trimmed = trim_fast(rest);
            if let Some(after_colon) = rest_trimmed.strip_prefix(':') {
                return Some(trim_fast(after_colon));
            }
            if rest.starts_with(char::is_whitespace) || rest.is_empty() {
                return Some(rest_trimmed);
            }
        }
    }
    None
}

/// Drop a mermaid 11 edge-id prefix from an edge's left-hand side (bd-yrxu).
///
/// `A e1@--> B` names the EDGE `e1`. Everything left of the operator was interned as one endpoint,
/// so `A e1@` normalised to a class called `A_e1` — an invented node — and the edge ran from it,
/// leaving the real `A` unconnected to anything.
///
/// The id is the last whitespace-separated token and must end in `@` with an otherwise ordinary
/// identifier body. Requiring BOTH a preceding token and that shape is what keeps this off every
/// other endpoint: a bare `A@` (no left neighbour) is left alone, so a node whose id genuinely ends
/// in `@` is not mangled.
///
/// The identifier is returned separately by [`trailing_edge_id`] where a parser surface needs to
/// retain it for a subsequent directive. Most diagram types still only need the stripped endpoint.
fn strip_trailing_edge_id(left: &str) -> &str {
    trailing_edge_id(left).map_or(left, |(head, _)| head)
}

/// Split `A edgeId@` into its endpoint text and Mermaid edge ID.
fn trailing_edge_id(left: &str) -> Option<(&str, &str)> {
    let (head, last) = left.rsplit_once(char::is_whitespace)?;
    let id = last.strip_suffix('@')?;
    if id.is_empty() || !id.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_') {
        return None;
    }
    let head = trim_end_fast(head);
    (!head.is_empty()).then_some((head, id))
}

/// Map a mermaid 11 `shape:` name onto the `NodeShape` its bracket spelling produces (bd-9x8r).
///
/// Returns `None` for an unrecognised name so the caller can keep the node's existing shape rather
/// than invent one — the same tolerance `curve` already applies to unknown names.
fn flowchart_metadata_shape(name: &str) -> Option<NodeShape> {
    Some(match name {
        "rect" | "rectangle" | "box" | "proc" | "process" => NodeShape::Rect,
        "rounded" | "round" | "event" => NodeShape::Rounded,
        "stadium" | "pill" | "terminal" => NodeShape::Stadium,
        "subroutine" | "subprocess" | "subproc" | "framed-rectangle" | "fr-rect" => {
            NodeShape::Subroutine
        }
        "cylinder" | "cyl" | "database" | "db" => NodeShape::Cylinder,
        "circle" | "circ" => NodeShape::Circle,
        "double-circle" | "doublecircle" | "dbl-circ" => NodeShape::DoubleCircle,
        "diamond" | "decision" | "diam" | "question" => NodeShape::Diamond,
        "hexagon" | "hex" | "prepare" => NodeShape::Hexagon,
        "parallelogram" | "lean-r" | "lean-right" | "in-out" => NodeShape::Parallelogram,
        "trapezoid" | "trap-b" | "trapezoid-bottom" | "priority" => NodeShape::Trapezoid,
        // ── THE MIRRORED HALF (bd-3ra5y) ──────────────────────────────────────────────────────
        // Every name below is a shape this renderer ALREADY DRAWS, reachable today through its
        // bracket spelling, whose mermaid 11 `shape:` name simply was not listed. `lean-r` mapped
        // and `lean-l` did not; `trap-b` mapped and `trap-t` did not. Because they were also absent
        // from `UNIMPLEMENTED_UPSTREAM_SHAPES`, an author writing a correct name was told the name
        // was unrecognised — sent to fix a spelling that was already right, for a shape we render.
        // Aliases are taken verbatim from the pinned 11.15.0 shape registry, not invented.
        "lean-l" | "lean-left" | "out-in" => NodeShape::InvParallelogram,
        "trap-t" | "trapezoid-top" | "inv-trapezoid" | "manual" => NodeShape::InvTrapezoid,
        // `odd` carries no public aliases in the registry — only the internal `rect_left_inv_arrow`,
        // which is not author-facing syntax and is deliberately NOT accepted here.
        "odd" => NodeShape::Asymmetric,
        "tri" | "triangle" | "extract" => NodeShape::Triangle,
        "f-circ" | "filled-circle" | "junction" => NodeShape::FilledCircle,
        "cross-circ" | "crossed-circle" | "summary" => NodeShape::CrossedCircle,
        "cloud" => NodeShape::Cloud,
        // ── ANOTHER MIRRORED PAIR (bd-3ra5y's family) ─────────────────────────────────────────
        // `fork` and `join` are the SAME shape in mermaid and this renderer already draws it: a thin
        // bar, reached today only through `state f <<fork>>` and the sequence `queue` participant,
        // with no flowchart spelling at all. Measured in Chromium 151 against the pinned 11.15.0
        // bundle, both names produce the identical outline `M-35 -5 L35 -5 L35 5 L-35 5` — a 70x10
        // bar (the second path in mermaid's output is rough.js' sketch overlay of that same
        // rectangle, not extra geometry). `HorizontalBar` draws 72x8 rounded, the same silhouette.
        //
        // They were listed as unimplemented, so an author writing a correct name was warned that a
        // shape we DO draw was unsupported, and got a plain rectangle instead of the bar.
        "fork" | "join" => NodeShape::HorizontalBar,
        // ── mermaid 11 shapes drawn for the first time (bd-7ls21) ─────────────────────────────
        // Aliases taken verbatim from the pinned 11.15.0 shape registry, not invented.
        // ── the last of the registry's unimplemented names (bd-7ls21) ────────────────────────
        // These six silhouettes were the whole remainder of `UNIMPLEMENTED_UPSTREAM_SHAPES`, so the
        // list is now empty and every author-facing shape name the pinned 11.15.0 registry
        // publishes maps to a drawn shape.
        "win-pane" | "window-pane" | "internal-storage" => NodeShape::WindowPane,
        "datastore" | "data-store" => NodeShape::DataStore,
        "text" => NodeShape::TextBlock,
        // `comment` and `brace-l` are ALIASES of `brace` in the registry, not shapes of their own;
        // `brace-r` and `braces` each have their own handler and are separate arms below.
        "brace" | "comment" | "brace-l" => NodeShape::BraceLeft,
        "brace-r" => NodeShape::BraceRight,
        "braces" => NodeShape::Braces,
        "notch-rect" | "card" | "notched-rectangle" => NodeShape::NotchedRect,
        "lin-rect" | "lined-rectangle" | "lined-process" | "lin-proc" | "shaded-process" => {
            NodeShape::LinedRect
        }
        "sm-circ" | "small-circle" | "start" => NodeShape::SmallCircle,
        "div-rect" | "div-proc" | "divided-rectangle" | "divided-process" => NodeShape::DividedRect,
        "fr-circ" | "framed-circle" | "stop" => NodeShape::FramedCircle,
        "flip-tri" | "flipped-triangle" | "manual-file" => NodeShape::FlippedTriangle,
        "notch-pent" | "notched-pentagon" | "loop-limit" => NodeShape::NotchedPentagon,
        "sl-rect" | "sloped-rectangle" | "manual-input" => NodeShape::SlopedRect,
        "h-cyl" | "horizontal-cylinder" | "das" => NodeShape::HorizontalCylinder,
        "tag-rect" | "tagged-rectangle" | "tag-proc" | "tagged-process" => NodeShape::TaggedRect,
        "lin-cyl" | "lined-cylinder" | "disk" => NodeShape::LinedCylinder,
        "doc" | "document" => NodeShape::Document,
        "lin-doc" | "lined-document" => NodeShape::LinedDocument,
        "bolt" | "lightning-bolt" | "com-link" => NodeShape::LightningBolt,
        "flag" | "paper-tape" => NodeShape::Flag,
        "delay" | "half-rounded-rectangle" => NodeShape::HalfRoundedRect,
        "docs" | "documents" | "st-doc" | "stacked-document" => NodeShape::StackedDocument,
        "st-rect" | "procs" | "processes" | "stacked-rectangle" => NodeShape::StackedRect,
        "bang" => NodeShape::Bang,
        "curv-trap" | "curved-trapezoid" | "display" => NodeShape::CurvedTrapezoid,
        "tag-doc" | "tagged-document" => NodeShape::TaggedDocument,
        "bow-rect" | "bow-tie-rectangle" | "stored-data" => NodeShape::BowTieRect,
        "hourglass" | "collate" => NodeShape::Hourglass,
        _ => return None,
    })
}

/// Split an `@{ ... }` body on commas that are OUTSIDE quotes.
///
/// A naive `split(',')` breaks `label: "one, two"` into two bogus pairs, which is negative case 4 of
/// bd-9x8r. Quote tracking is the minimum needed to keep a comma inside a label.
fn split_metadata_pairs(body: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0_usize;
    let mut quote: Option<char> = None;
    for (index, ch) in body.char_indices() {
        match ch {
            '"' | '\'' => {
                if quote == Some(ch) {
                    quote = None;
                } else if quote.is_none() {
                    quote = Some(ch);
                }
            }
            ',' if quote.is_none() => {
                out.push(&body[start..index]);
                start = index + 1;
            }
            _ => {}
        }
    }
    out.push(&body[start..]);
    out
}

/// Parse a standalone `id@{ key: value, … }` flowchart node-metadata statement (bd-9x8r).
///
/// mermaid 11 documents this as the unified way to give a node a shape and a label. We did not
/// recognise it on the flowchart path, so `parse_node_token_with_config` interned the whole line and
/// the diagram gained a class whose displayed name was the directive text itself —
/// `shape: rect, label: "Shaped` — with the declared shape and label both lost.
///
/// Returns `None` for anything that is not this exact form, so every other statement falls through
/// to the existing node/edge parsing untouched.
/// mermaid 11 shape names MEASURED as present in the pinned 11.15.0 bundle and absent from
/// [`flowchart_metadata_shape`] (bd-laocw).
///
/// This list exists to split one message into two, because the two say different things to an
/// author: a name in here means "your syntax is right, we have not built this shape", and a name
/// not in here means "check the spelling". Collapsing them would send half the readers to the wrong
/// fix. Same reasoning as `unsupported_upstream_keyword` in the detection layer.
///
/// ⚠️ A NAME ADDED TO `flowchart_metadata_shape` MUST BE REMOVED FROM HERE, or implementing a shape
/// leaves behind a warning claiming it is unimplemented. The `every_unimplemented_shape_is_really
/// _unimplemented` test enforces exactly that, so the two lists cannot drift apart silently.
/// ⚠️ THIS LIST HELD 12 OF 80 (bd-3ra5y). It carried only shortNames and none of their ALIASES, so
/// `shape: card` was told to check its spelling while `shape: notch-rect` — the same shape, the
/// other name for it — was correctly told the shape is unbuilt. The registry publishes both, so a
/// list of shortNames alone can only ever answer for the half of authors who happened to pick one.
/// Every entry below is a name the pinned 11.15.0 registry publishes as author-facing syntax
/// (`shortName` or `aliases`); internal aliases like `rect_left_inv_arrow` are deliberately absent.
///
/// ⚠️ IT IS NOW EMPTY, AND EMPTY IS A REAL STATE RATHER THAN A DELETED FEATURE. Every author-facing
/// name the pinned 11.15.0 registry publishes maps to a drawn shape (bd-7ls21), so there is nothing
/// left for this arm of [`unimplemented_shape_warning`] to say. The constant and its arm stay
/// because the next mermaid release will add names — emptying the list is the milestone, removing
/// the mechanism would mean the next unknown name gets the "check your spelling" message instead of
/// the honest "not built yet" one.
const UNIMPLEMENTED_UPSTREAM_SHAPES: [&str; 0] = [];

/// Message for a `shape:` name that [`flowchart_metadata_shape`] does not map.
///
/// Both arms name the shape and both state the CONSEQUENCE -- that the node kept its previous
/// shape -- because the consequence is the part the author cannot see: the diagram still renders,
/// just as the wrong shape.
fn unimplemented_shape_warning(name: &str) -> String {
    shape_warning_against(name, &UNIMPLEMENTED_UPSTREAM_SHAPES)
}

/// The message itself, against an EXPLICIT list of unbuilt names.
///
/// ⚠️ THE LIST IS A PARAMETER SO THE "NOT BUILT YET" ARM STAYS PROVABLE WHILE
/// [`UNIMPLEMENTED_UPSTREAM_SHAPES`] IS EMPTY (bd-7ls21). With every published name now drawn, no
/// real input can reach that arm, and the test that used to pin it did so by naming a shape it
/// expected to stay unbuilt — which stopped being true the moment `brace` was implemented. Pinning
/// the message through a supplied list tests the branch without asserting anything false about
/// which shapes exist.
fn shape_warning_against(name: &str, unimplemented: &[&str]) -> String {
    if unimplemented.contains(&name) {
        format!(
            "shape '{name}' is a mermaid 11 shape this renderer does not implement yet; \
             the node kept its previous shape"
        )
    } else {
        format!("shape '{name}' is not a recognised shape name; the node kept its previous shape")
    }
}

/// What a recognised `id@{ … }` statement turned out to describe.
///
/// Three outcomes rather than two because the statement's `id` addresses two different namespaces:
/// a node it DECLARES, or an edge it merely REFERS to. The old `Option<Option<FlowAstNode>>` could
/// only say "a node" or "nothing", so an edge statement had to be filed under "nothing".
enum FlowMetadata {
    /// The statement declared a node.
    Node(Box<FlowAstNode>),
    /// The statement named an edge and asked it to march.
    EdgeAnimation {
        id: String,
        animation: EdgeAnimation,
    },
    /// Recognised `@{…}` metadata that declares nothing and addresses nothing.
    Nothing,
}

/// Map one `animate:` / `animation:` value to a march speed (bd-euyt4).
///
/// MEASURED upstream (pinned 11.15.0, Chromium 151): `animate: true` and `animation: fast` both
/// produce `edge-animation-fast`; `animation: slow` produces `edge-animation-slow`; `animate:
/// false` produces no animation class at all.
///
/// `Err(())` means the value is one upstream would interpolate into a class name it does not
/// style — `animation: turbo` measurably yields `edge-animation-turbo`, which no rule matches, so
/// upstream draws a plain edge. We draw the same plain edge and say why, the same split
/// [`unimplemented_shape_warning`] makes for an unmapped `shape:` name.
fn parse_edge_animation_value(key: &str, value: &str) -> Result<Option<EdgeAnimation>, ()> {
    let lowered = value.to_ascii_lowercase();
    match (key, lowered.as_str()) {
        ("animate", "true") | ("animation", "fast") => Ok(Some(EdgeAnimation::Fast)),
        ("animation", "slow") => Ok(Some(EdgeAnimation::Slow)),
        // `animate: false` is a real, spelled-out opt-OUT, not a typo: no animation, no warning.
        ("animate", "false") => Ok(None),
        _ => Err(()),
    }
}

fn parse_flowchart_node_metadata(
    statement: &str,
    config: &ParserConfig,
    warnings: &mut Vec<String>,
) -> Option<FlowMetadata> {
    let at_pos = statement.find("@{")?;
    let close = statement.rfind('}')?;
    if close < at_pos + 2 || !trim_fast(&statement[close + 1..]).is_empty() {
        return None;
    }
    let id = trim_fast(&statement[..at_pos]);
    if id.is_empty() || id.contains(char::is_whitespace) {
        return None;
    }
    // Reuse the ordinary token parser for the id so shaped spellings and `:::class` keep working.
    let base = parse_node_token_with_config(id, config)?;

    let mut shape = base.shape;
    let mut label = base.label;
    // Whether any key that describes a NODE was present. `e1@{ animate: true }` names an EDGE, and
    // mermaid declares no node for it; declaring one leaves a stray empty box in the diagram
    // (bd-yrxu). Recognising the statement but emitting nothing is the honest outcome: we cannot
    // attach the metadata to its edge without an edge-id concept, but we can stop inventing a node.
    let mut saw_node_key = false;
    // The march speed an `animate:`/`animation:` key asked for, and whether such a key was present
    // at all — `animate: false` sets the flag while leaving the speed `None`, so it stays a
    // recognised statement rather than falling through to be interned as a node.
    let mut animation = None;
    let mut saw_animation_key = false;
    for pair in split_metadata_pairs(&statement[at_pos + 2..close]) {
        let Some((key, value)) = pair.split_once(':') else {
            continue;
        };
        let value = trim_fast(value).trim_matches('"').trim_matches('\'');
        match trim_fast(key).to_ascii_lowercase().as_str() {
            // An unrecognised shape name leaves the shape alone rather than inventing one -- and
            // now SAYS SO (bd-laocw). Falling back silently meant an author who wrote valid
            // mermaid 11 got a plain rectangle with nothing pointing at why.
            "shape" => {
                saw_node_key = true;
                let lowered = value.to_ascii_lowercase();
                if let Some(mapped) = flowchart_metadata_shape(&lowered) {
                    shape = mapped;
                } else if !lowered.is_empty() {
                    warnings.push(unimplemented_shape_warning(&lowered));
                }
            }
            "label" | "title" => {
                saw_node_key = true;
                if !value.is_empty() {
                    label = Some(ParsedLabel::plain(value));
                }
            }
            key @ ("animate" | "animation") => {
                saw_animation_key = true;
                match parse_edge_animation_value(key, value) {
                    Ok(speed) => animation = speed,
                    Err(()) => warnings.push(format!(
                        "edge animation '{value}' is not a speed this renderer draws; \
                         the edge is drawn unanimated"
                    )),
                }
            }
            _ => {}
        }
    }
    // A node key WINS over an animation key on the same statement. `animate:` addresses the edge
    // namespace, so on a statement that also declares a node the id is a node id, which no edge
    // can be registered under — routing it to the edge map could only ever miss.
    if saw_node_key {
        return Some(FlowMetadata::Node(Box::new(FlowAstNode {
            id: base.id,
            label,
            icon: base.icon,
            shape,
            classes: base.classes,
        })));
    }
    if saw_animation_key && let Some(animation) = animation {
        return Some(FlowMetadata::EdgeAnimation {
            id: id.to_string(),
            animation,
        });
    }
    Some(FlowMetadata::Nothing)
}

/// Does this statement carry a dash/dot run the FAST tables cannot classify (bd-6s6sx)?
///
/// The fast path has its own 9-entry operator table and no run logic, so any run longer than those
/// literals belongs to the full matcher. Deferring is always safe: it costs a fast path, never a
/// wrong answer.
///
/// ⚠️ THIS MUST BE CHECKED ON THE NODE PATH, NOT ONLY THE EDGE PATH, and that is the whole reason
/// it is a named predicate instead of an early return. The first version of this guard lived inside
/// the edge matcher and returned `None` meaning "defer to the full matcher" — but `None` from the
/// edge matcher means "not an edge" to its callers, which then hand the SAME text to the fast node
/// parser. `-`, `o` and `x` are all identifier bytes, so `A---xB` was claimed as a node id and the
/// full matcher was never reached: the deferral was swallowed one line below where it was written.
/// Diagnosed by BeigeHill against a built binary after the throttle lifted.
///
/// There are TWO node entry points — the `or_else` in `parse_fast_simple_flowchart_statement_ast`
/// and the document loop's direct call to `parse_fast_simple_flowchart_node_borrowed` — so the
/// check sits at the shared chokepoint each of them passes through, not at either caller.
fn fast_path_cannot_classify_run(statement: &str) -> bool {
    let bytes = statement.as_bytes();
    let mut i = 0_usize;
    while i < bytes.len() {
        if bytes[i] != b'-' {
            i += 1;
            continue;
        }

        if bytes.get(i + 1) == Some(&b'.') {
            // Dotted family. A dotted LINK is `-` `.`+ `-`; a bare `-.` with no closing dash is
            // just text (a node id like `v1-.2`) and must stay on the fast path. Of the real link
            // spellings the fast table carries exactly `-.->`, so every other one defers.
            let mut j = i + 1;
            while bytes.get(j) == Some(&b'.') {
                j += 1;
            }
            if bytes.get(j) == Some(&b'-') {
                let is_fast_dotted_arrow = j == i + 2 && bytes.get(j + 1) == Some(&b'>');
                if !is_fast_dotted_arrow {
                    return true;
                }
                i = j + 2;
                continue;
            }
            i = j;
            continue;
        }

        let mut j = i;
        while bytes.get(j) == Some(&b'-') {
            j += 1;
        }
        // A run ending in `>` needs no help: `>` is not an identifier byte, so the node path
        // rejects it and the full matcher gets the statement anyway. `o` and `x` ARE identifier
        // bytes, and that is precisely the defect.
        if j - i >= 3 && matches!(bytes.get(j), Some(b'o' | b'x')) {
            return true;
        }
        i = j;
    }
    false
}

fn parse_fast_simple_flowchart_statement_ast(statement: &str) -> Option<FlowAst> {
    parse_fast_simple_flowchart_edge_ast(statement)
        .or_else(|| parse_fast_simple_flowchart_node_ast(statement).map(FlowAst::Node))
}

fn parse_fast_simple_flowchart_edge_ast(statement: &str) -> Option<FlowAst> {
    // Mermaid 11 edge IDs are written on the left endpoint as `A edgeId@--> B`. The fast parser
    // only has plain endpoint tokens, so accepting `@` here turns the ID into part of a phantom
    // node. Defer to the full parser, which splits and retains the ID for `class edgeId name`.
    if statement.as_bytes().contains(&b'@') {
        return None;
    }
    let (left, arrow, right) = parse_fast_simple_flowchart_edge_parts(statement)?;
    Some(FlowAst::Edge {
        from: FlowAstNode {
            id: left.to_string(),
            label: None,
            icon: None,
            shape: NodeShape::Rect,
            // FAST edge path: `FAST_EDGE_REJECT` lists `:`, so a `:::` statement cannot reach here.
            classes: Vec::new(),
        },
        arrow,
        label: None,
        edge_id: None,
        to: FlowAstNode {
            id: right.to_string(),
            label: None,
            icon: None,
            shape: NodeShape::Rect,
            classes: Vec::new(),
        },
    })
}

/// Byte-classification table: `true` for the bytes whose presence forces a flowchart statement off
/// the fast edge path (bracket/paren/brace shapes, quotes, `|` edge labels, `&` node lists, `:`/`,`).
/// A single indexed load per byte replaces the 12-way `matches!` compare chain on this hot scan.
static FAST_EDGE_REJECT: [bool; 256] = {
    let mut t = [false; 256];
    let rejects = b"[](){}\"'`|&:,";
    let mut i = 0;
    while i < rejects.len() {
        t[rejects[i] as usize] = true;
        i += 1;
    }
    t
};

fn parse_fast_simple_flowchart_edge_parts(statement: &str) -> Option<(&str, ArrowType, &str)> {
    // Every caller (the flowchart doc loop, directly or via the `_ast` chain) passes an already
    // `trim_fast`'d statement — no leading/trailing whitespace (ASCII or Unicode) remains — so the old
    // top `trim_ascii` was a no-op. Use `statement` directly. (`left`/`right` around the operator are
    // still trimmed below, where whitespace like `N0 --> N1` IS possible.)
    let trimmed = statement;
    // A run the fast table cannot classify belongs to the full matcher (bd-6s6sx); see
    // `fast_path_cannot_classify_run` for why the NODE path checks the same predicate.
    if fast_path_cannot_classify_run(trimmed) {
        return None;
    }
    if trimmed.is_empty() || trimmed.bytes().any(|byte| FAST_EDGE_REJECT[byte as usize]) {
        return None;
    }

    const FAST_OPERATORS: [(&str, ArrowType); 9] = [
        ("-.->", ArrowType::DottedArrow),
        ("<-.->", ArrowType::DoubleDottedArrow),
        ("==>", ArrowType::ThickArrow),
        ("<==>", ArrowType::DoubleThickArrow),
        ("-->", ArrowType::Arrow),
        ("<-->", ArrowType::DoubleArrow),
        ("---", ArrowType::Line),
        ("--o", ArrowType::Circle),
        ("--x", ArrowType::Cross),
    ];

    // Single byte scan for the leftmost operator-start byte, instead of several full `str::find`
    // substring searches. Byte-identical: fast operators start with `-`, `=`, or `<`, and no two
    // are prefixes of one another, so at most one matches at any position — the leftmost operator
    // necessarily starts at the leftmost matching byte (same result as the old leftmost-index /
    // longest tie-break).
    let bytes = trimmed.as_bytes();
    let mut matched: Option<(usize, &str, ArrowType)> = None;
    for i in 0..bytes.len() {
        if matches!(bytes[i], b'-' | b'=' | b'<') {
            for (operator, arrow) in FAST_OPERATORS {
                if bytes[i..].starts_with(operator.as_bytes()) {
                    matched = Some((i, operator, arrow));
                    break;
                }
            }
            if matched.is_some() {
                break;
            }
        }
    }

    let (operator_index, operator, arrow) = matched?;

    let left = trimmed.get(..operator_index)?.trim_ascii();
    let right = trimmed.get(operator_index + operator.len()..)?.trim_ascii();
    if !is_fast_flow_identifier(left) || !is_fast_flow_identifier(right) {
        return None;
    }
    // Reject a chained right side (e.g. `a-->b-->c`, where `right` holds a second operator).
    // Guard the substring searches behind a single byte scan: every fast operator starts with
    // `-`, `=`, or `<`, so if `right` has none of those bytes none can match. Byte-identical;
    // saves substring-search calls per edge for the common single-operator edge.
    if right.bytes().any(|byte| matches!(byte, b'-' | b'=' | b'<'))
        && FAST_OPERATORS
            .iter()
            .any(|(next_operator, _)| right.contains(next_operator))
    {
        return None;
    }

    Some((left, arrow, right))
}

fn parse_fast_simple_flowchart_node_ast(statement: &str) -> Option<FlowAstNode> {
    let (id, label, icon) = parse_fast_simple_flowchart_node_borrowed(statement)?;
    Some(FlowAstNode {
        id: id.to_string(),
        label,
        icon,
        shape: NodeShape::Rect,
        // FAST node path: `FAST_ID_CHAR` omits `:` and a bracketed `N0[x]:::c` fails the
        // `ends_with(']')` guard, so a `:::` token always defers to the general parser.
        classes: Vec::new(),
    })
}

/// Borrowed core of [`parse_fast_simple_flowchart_node_ast`]: returns the node id as a `&str` slice
/// into `statement` (instead of an owned `String`) plus the owned label/icon. Lets the document parser
/// stash a simple node as `FlowDocumentItem::FastNode` and intern it straight from the slice — skipping
/// both the `id.to_string()` and the single-element `vec![FlowAst::Node(..)]` the general path allocates.
/// Shape is always `Rect` on this fast path. Byte-identical matching to the original (same trims/guards).
fn parse_fast_simple_flowchart_node_borrowed(
    statement: &str,
) -> Option<(&str, Option<ParsedLabel>, Option<String>)> {
    // Every caller passes an already `trim_fast`'d statement (see
    // `parse_fast_simple_flowchart_edge_parts`), so the top `trim_ascii` was a no-op — use `statement`
    // directly. The `id` before `[` is still trimmed below (`N0 [x]` has interior whitespace).
    let trimmed = statement;
    // THE CHECK THAT MATTERS (bd-6s6sx). Refusing the run on the edge path alone is inert: `None`
    // there means "not an edge", and both callers then offer the same text here, where `-`, `o` and
    // `x` are all valid identifier bytes. `A---xB` became a node id and the full matcher never ran.
    if fast_path_cannot_classify_run(trimmed) {
        return None;
    }
    if trimmed.is_empty() {
        return None;
    }

    // Single scan for the first `[` OR forbidden byte (paren/brace/quote/pipe/amp/comma). Fusing them
    // keeps the early reject for `{`/`(`-shaped nodes — diamond/hexagon fail at the first byte, as the
    // old whole-line forbidden scan did — AND lets a bracketed node skip the rest of the scan when it
    // isn't `]`-terminated (a `:::`-class suffix `N0[label]:::x`, the hot styled-flowchart
    // node-declaration line). `[` is ASCII, so its byte index is a char boundary and the slices
    // reproduce `split_once('[')` exactly.
    let first_special = trimmed.as_bytes().iter().position(|&b| {
        matches!(
            b,
            b'[' | b'(' | b')' | b'{' | b'}' | b'"' | b'\'' | b'`' | b'|' | b'&' | b','
        )
    });
    match first_special {
        Some(bracket) if trimmed.as_bytes()[bracket] == b'[' => {
            // `[` came before any forbidden byte, so the id (before `[`) is already clean.
            if !trimmed.ends_with(']') {
                return None;
            }
            let id = trimmed[..bracket].trim_ascii();
            // `trim_fast` is byte-identical to `str::trim` but skips the `char::is_whitespace`
            // CharSearcher — this label trim fires once per bracketed node.
            let label_raw = trim_fast(trimmed[bracket + 1..].strip_suffix(']')?);
            // Mermaid's quoted rectangular labels deliberately carry punctuation that is syntax
            // outside the quotes (`&`, commas, braces, parentheses, apostrophes). Chumsky treats
            // all of it as label content, then `parse_label` removes the surrounding quotes. Keep
            // the conservative forbidden-byte gate for unquoted labels, but let the existing fast
            // path handle a complete double-quoted label directly. This is the dominant node form
            // in documentation batches and avoids constructing the Chumsky choice graph per node.
            let double_quoted =
                label_raw.len() >= 2 && label_raw.starts_with('"') && label_raw.ends_with('"');
            if !double_quoted
                && label_raw.as_bytes().iter().any(|&b| {
                    matches!(
                        b,
                        b'(' | b')' | b'{' | b'}' | b'"' | b'\'' | b'`' | b'|' | b'&' | b','
                    )
                })
            {
                return None;
            }
            // Byte scan for a nested `[`/`]` rather than `contains(['[', ']'])`; both are ASCII.
            if !is_fast_flow_identifier(id)
                || label_raw.as_bytes().iter().any(|&b| b == b'[' || b == b']')
            {
                return None;
            }
            // The slanted shape family `[/…/]`, `[\…\]`, `[/…\]`, `[\…/]` reaches here as a label
            // that both opens AND closes with a slash, and this path hardcodes Rect — so it was
            // silently flattening all four to rectangles whose labels kept the slashes (bd-3w93).
            // Defer exactly those to the general parser. Adding `/` to the forbidden-byte gate
            // above would work too, but would push every ordinary "TCP/IP" label off the fast path
            // for no correctness gain.
            let slanted = |b: u8| b == b'/' || b == b'\\';
            if label_raw.len() >= 2
                && label_raw.as_bytes().first().copied().is_some_and(slanted)
                && label_raw.as_bytes().last().copied().is_some_and(slanted)
            {
                return None;
            }
            // `label_raw` is `trim_fast`'d above; `parse_label_pretrimmed` skips the redundant re-trim.
            let mut label = parse_label_pretrimmed(label_raw);
            let icon = extract_icon_prefix_pretrimmed(label.as_mut());
            clear_empty_label(&mut label);
            Some((id, label, icon))
        }
        // A forbidden byte before any `[` (paren/brace/… shaped node — diamond/hexagon/…).
        Some(_) => None,
        // No `[` and no forbidden byte: a plain identifier node.
        None => is_fast_flow_identifier(trimmed).then_some((trimmed, None, None)),
    }
}

/// `[byte] -> is a valid fast-flow-identifier byte`. Replaces the per-byte
/// `is_ascii_alphanumeric() || matches!(_ - . /)` chain (≈7 comparisons) with one table load on the
/// hot fast-edge path. Byte-identical: the same accept set (`0-9 A-Z a-z _ - . /`).
static FAST_ID_CHAR: [bool; 256] = {
    let mut t = [false; 256];
    let mut i = b'0';
    while i <= b'9' {
        t[i as usize] = true;
        i += 1;
    }
    let mut i = b'A';
    while i <= b'Z' {
        t[i as usize] = true;
        i += 1;
    }
    let mut i = b'a';
    while i <= b'z' {
        t[i as usize] = true;
        i += 1;
    }
    t[b'_' as usize] = true;
    t[b'-' as usize] = true;
    t[b'.' as usize] = true;
    t[b'/' as usize] = true;
    t
};

fn is_fast_flow_identifier(value: &str) -> bool {
    !value.is_empty() && value.bytes().all(|byte| FAST_ID_CHAR[byte as usize])
}

fn add_node_to_active_clusters(
    builder: &mut IrBuilder,
    active_clusters: &[usize],
    node_id: IrNodeId,
) {
    for &cluster_index in active_clusters {
        builder.add_node_to_cluster(cluster_index, node_id);
    }
}

fn add_node_to_active_groups(
    builder: &mut IrBuilder,
    active_clusters: &[usize],
    active_subgraphs: &[usize],
    node_id: IrNodeId,
) {
    add_node_to_active_clusters(builder, active_clusters, node_id);
    for &subgraph_index in active_subgraphs {
        builder.add_node_to_subgraph(subgraph_index, node_id);
    }
}

/// Warn when a node label still holds UNMATCHED bracket syntax (bd-rrvr).
///
/// An unrecognised edge operator does not fail, warn or drop the line — it collapses the whole line
/// into one node whose label is a raw fragment of the user's own source. Measured:
/// `a[A] ~~> b[B]` yields ONE node labelled `A] ~~> b[B`, and `Alpha ~~ Beta` one labelled
/// `Alpha ~~ Beta`, both with no warning. The user sees a box containing their own syntax and gets
/// no signal that anything was misread, which is worse than a dropped line because the diagram looks
/// like it rendered.
///
/// THE RULE IS DELIBERATELY NARROW: an UNMATCHED `[` or `]` only. The tempting rule — "warn when the
/// label looks like it contains an arrow" — is a heuristic that fires on legitimate labels
/// containing `~` or `>`, and a false warning on correct input is worse than the silence it
/// replaces. A balanced bracket is left alone precisely because `a["x [y]"]` is valid and common.
///
/// IT NOW REJECTS THE NODE AS WELL AS WARNING, which is the second half of bd-rrvr. The warning
/// removed the silence; it did not remove the garbage, and `a[A] ~~> b[B]` still drew a box
/// containing `A] ~~> b[B` — a fragment of the user's own syntax presented as their content.
///
/// GROUNDED ON THE INCUMBENT, not on taste. mermaid 11.15.0 (pinned bundle, evaluated in the same
/// browserless `node:vm` sandbox `mermaid_bench.mjs` uses) THROWS on this shape:
/// `flowchart TD / a[Unclosed --> b[B]` gives `Parse error on line 2`. So the incumbent refuses the
/// line; we drew it as content. Dropping the node and keeping the warning moves us toward that
/// behaviour and is strictly more honest than a box full of syntax.
///
/// ⚠️ The flowchart `~~>` case could NOT be settled this way and I did not force it: mermaid's
/// flowchart parse path reaches DOMPurify, which needs a DOM the sandbox deliberately does not
/// provide, so it reports DNF. Stubbing a DOM to get an answer is the trade that file's comment
/// explicitly warns against. The unmatched-bracket verdict above is what the evidence supports, and
/// it is the same rule, so the fix rests on the case that WAS measured.
///
/// Returns `true` when the caller must NOT intern the node.
fn warn_if_label_holds_unmatched_bracket(builder: &mut IrBuilder, label: &str, span: Span) -> bool {
    let mut depth = 0_i32;
    let mut unmatched_close = false;
    for byte in label.bytes() {
        match byte {
            b'[' => depth += 1,
            b']' => {
                if depth == 0 {
                    unmatched_close = true;
                } else {
                    depth -= 1;
                }
            }
            _ => {}
        }
    }
    if depth == 0 && !unmatched_close {
        return false;
    }
    builder.add_warning(format!(
        "Line {}: unrecognised syntax was DROPPED rather than drawn as a node label: {label:?}. \
         A bracket is unmatched, so an operator on this line was not understood.",
        span.start.line
    ));
    true
}

fn intern_node_token(builder: &mut IrBuilder, node: &NodeToken, span: Span) -> Option<IrNodeId> {
    if let Some(label) = node.label.as_ref()
        && warn_if_label_holds_unmatched_bracket(builder, &label.text, span)
    {
        return None;
    }
    let node_id = builder.intern_node_label(&node.id, node.label.as_ref(), node.shape, span)?;
    if let Some(icon) = node.icon.as_deref() {
        builder.set_node_icon(node_id, icon);
    }
    apply_inline_classes(builder, node_id, &node.classes);
    Some(node_id)
}

/// Apply a token's `:::className` classes to the node just interned (bd-8n2b5).
///
/// ⚠️ THERE ARE TWO INTERNING FUNCTIONS, and applying this in only one of them is inert — the exact
/// shape of the guard that shipped covering one of two callers before. `intern_node_token` takes the
/// `NodeToken`, `intern_flow_ast_node` takes the `FlowAstNode` it converts into, and a flowchart
/// node can arrive through either. Both call this, so neither can drift.
///
/// The two FAST document paths (`FastNode`/`FastEdge`) deliberately do NOT: both refuse a `:::`
/// token before reaching this point — `FAST_EDGE_REJECT` lists `:`, `FAST_ID_CHAR` omits it, and a
/// bracketed `N0[x]:::c` fails the `ends_with(']')` guard — so such a statement always falls through
/// to the general path. That is checked, not assumed; `a_class_suffix_never_takes_a_fast_path` pins it.
fn apply_inline_classes(builder: &mut IrBuilder, node_id: IrNodeId, classes: &[String]) {
    for class_name in classes {
        builder.add_class_to_node_id(node_id, class_name);
    }
}

fn intern_flow_ast_node(
    builder: &mut IrBuilder,
    node: &FlowAstNode,
    span: Span,
) -> Option<IrNodeId> {
    if let Some(label) = node.label.as_ref()
        && warn_if_label_holds_unmatched_bracket(builder, &label.text, span)
    {
        return None;
    }
    let node_id = if is_dangling_placeholder_node_id(&node.id) {
        builder.intern_placeholder_node(&node.id, span)?
    } else {
        builder.intern_node_label(&node.id, node.label.as_ref(), node.shape, span)?
    };
    if let Some(icon) = node.icon.as_deref() {
        builder.set_node_icon(node_id, icon);
    }
    apply_inline_classes(builder, node_id, &node.classes);
    Some(node_id)
}

/// Parse a `subgraph …` header, defaulting the title to the subgraph's own id (bd-ka77).
///
/// mermaid displays the id when no explicit title is given, so `subgraph one` is labelled `one`.
/// We returned `None`, and `None` does not mean "draw the id" downstream — it means the cluster
/// label is never emitted at all and `build_cluster_boxes` never sizes for it, leaving the group
/// the author named anonymous in the picture.
///
/// `parse_subgraph_statement_raw` keeps the original extraction untouched, including its deliberate
/// `.filter(|value| value != &key)` redundancy drop; the difference is that a dropped-as-redundant
/// title now falls back to the id instead of to nothing. Dropping a REDUNDANT title and dropping
/// the title ENTIRELY are different outcomes and only the first was intended.
///
/// This mirrors what the state path already does: `begin_state_cluster` passes
/// `title.or(Some(name))`, so a state composite always carries a title. Flowchart subgraphs were
/// the outlier.
fn parse_subgraph_statement(
    statement: &str,
    config: &ParserConfig,
) -> Option<(String, Option<String>)> {
    let (key, title) = parse_subgraph_statement_raw(statement, config)?;
    let title = title.or_else(|| Some(key.clone()));
    Some((key, title))
}

fn parse_subgraph_statement_raw(
    statement: &str,
    config: &ParserConfig,
) -> Option<(String, Option<String>)> {
    // `trim_start_fast` is byte-identical to `str::trim_start` but skips the CharSearcher; this runs
    // once per flowchart statement (before the node/edge classifiers) on an already-trimmed line.
    let statement = trim_start_fast(statement);
    let rest = statement.strip_prefix("subgraph")?;
    let first = rest.chars().next()?;
    if !first.is_whitespace() {
        return None;
    }

    let body = rest.trim_start();
    if body.is_empty() {
        return None;
    }

    // Prefer explicit node-style labels (`id[Title]`, `id(Title)`, etc.) when
    // delimiter characters are present. This preserves the same title
    // normalization behavior as normal node parsing.
    let has_explicit_label_delimiters =
        body.contains('[') || body.contains('(') || body.contains('{') || body.contains('>');
    if has_explicit_label_delimiters && let Some(node) = parse_node_token_with_config(body, config)
    {
        let key = normalize_identifier(&node.id);
        if !key.is_empty() {
            return Some((key, node.label.map(|label| label.text)));
        }
    }

    // Mermaid commonly supports `subgraph <id> <title>` and
    // `subgraph <id> "<title>"`. Use robust quoted extraction to handle
    // spaces and escapes in either field.
    if let Some((key_raw, rest)) = extract_quoted_or_word(body) {
        let key = normalize_identifier(&key_raw);
        if !key.is_empty() {
            let title_raw = rest.trim();
            let explicit_title = matches!(title_raw.chars().next(), Some('"' | '\'' | '`'));
            if title_raw.is_empty() || explicit_title || looks_like_explicit_subgraph_id(&key_raw) {
                let title = if title_raw.is_empty() {
                    None
                } else {
                    normalize_subgraph_title(title_raw)
                };
                return Some((key, title));
            }
        }
    }

    if let Some(node) = parse_node_token_with_config(body, config) {
        let key = normalize_identifier(&node.id);
        if !key.is_empty() {
            return Some((key, node.label.map(|label| label.text)));
        }
    }

    let key = normalize_identifier(body);
    if key.is_empty() {
        return None;
    }
    let title = normalize_subgraph_title(body).filter(|value| value != &key);
    Some((key, title))
}

fn looks_like_explicit_subgraph_id(raw: &str) -> bool {
    let trimmed = raw
        .trim()
        .trim_matches('"')
        .trim_matches('\'')
        .trim_matches('`');
    !trimmed.is_empty()
        && trimmed.bytes().all(|b| {
            b.is_ascii_lowercase() || b.is_ascii_digit() || matches!(b, b'_' | b'-' | b'.' | b'/')
        })
}

fn parse_sequence(input: &str, builder: &mut IrBuilder) {
    for (index, line) in byte_lines(input).enumerate() {
        let line_number = index + 1;
        let trimmed = trim_fast(line);
        if trimmed.is_empty() || is_comment(trimmed) {
            continue;
        }

        if trimmed.starts_with("sequenceDiagram") {
            continue;
        }

        // ⚠️ CONSUMED, NOT PARSED: `extract_accessibility_directives` has ALREADY taken this line's
        // value into `ir.meta` before this loop runs, so the directive works — the value reaches
        // `<title>`/`<desc>` in every family. All this loop was adding was a warning calling a
        // working directive unsupported (bd-xym5x).
        if is_accessibility_directive_statement(trimmed) {
            continue;
        }

        let Some(statement) = parse_sequence_statement(trimmed) else {
            builder.add_warning(format!(
                "Line {line_number}: unsupported sequence syntax: {trimmed}"
            ));
            continue;
        };

        lower_sequence_statement(statement, line_number, line, builder);
    }
}

fn parse_sequence_statement(line: &str) -> Option<SequenceStatement> {
    // Fast reject: every keyword statement below begins with a lowercase ASCII letter, `Note` (`N`), or
    // the case-insensitive `hide footbox` (`h`/`H`) — all its checks are prefix (`strip_prefix`/`==`)
    // matches. A line whose first byte is anything else (an uppercase participant name like `Alice`/`P0`,
    // a digit, `[`, `"`, …) cannot match any keyword, so skip the whole ~18-check keyword chain straight
    // to the message parse (those keyword `strip_prefix`/`==` calls each invoke `memcmp` even on a
    // first-byte mismatch — ~8.9% of sequence parse). Byte-identical: each skipped check compares from
    // byte 0 and would return `None` on such a first byte, and the message parse is the existing
    // fall-through. Conservative — a lowercase/`N`/`H` first byte still runs the full chain.
    if let Some(&first) = line.as_bytes().first()
        && !(first.is_ascii_lowercase() || first == b'N' || first == b'H')
    {
        return parse_sequence_message_ast(line)
            .map(|data| SequenceStatement::Message(Box::new(data)));
    }

    if let Some(autonumber) = parse_sequence_autonumber(line) {
        return Some(autonumber);
    }

    if line.eq_ignore_ascii_case("hide footbox") {
        return Some(SequenceStatement::HideFootbox);
    }

    if let Some(link) = parse_sequence_actor_menu(line) {
        return Some(link);
    }

    if let Some(note) = parse_sequence_note(line) {
        return Some(note);
    }

    if let Some(rest) = line.strip_prefix("activate ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::Activate(name.to_string()));
        }
    }

    if let Some(rest) = line.strip_prefix("deactivate ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::Deactivate(name.to_string()));
        }
    }

    if line == "end" {
        // `end` closes both box groups and fragments; the builder
        // will dispatch appropriately based on which is open.
        return Some(SequenceStatement::FragmentEnd);
    }

    // Fragment start keywords
    if let Some(frag) = parse_sequence_fragment_start(line) {
        return Some(frag);
    }

    // Fragment else/and/option dividers — require word boundary (space or end-of-line)
    // to avoid matching e.g. "elsewhere" or "android".
    if line == "else" {
        return Some(SequenceStatement::FragmentElse {
            label: String::new(),
        });
    }
    if let Some(rest) = line.strip_prefix("else ") {
        return Some(SequenceStatement::FragmentElse {
            label: rest.trim().to_string(),
        });
    }
    if line == "and" || line == "option" {
        return Some(SequenceStatement::FragmentElse {
            label: String::new(),
        });
    }
    if let Some(rest) = line.strip_prefix("and ") {
        return Some(SequenceStatement::FragmentElse {
            label: rest.trim().to_string(),
        });
    }
    if let Some(rest) = line.strip_prefix("option ") {
        return Some(SequenceStatement::FragmentElse {
            label: rest.trim().to_string(),
        });
    }

    if let Some(rest) = line.strip_prefix("box ") {
        let rest = rest.trim();
        return Some(parse_sequence_box_start(rest));
    }
    if line == "box" {
        return Some(SequenceStatement::BoxStart {
            label: String::new(),
            color: None,
        });
    }

    if let Some(rest) = line.strip_prefix("create participant ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::CreateParticipant(name.to_string()));
        }
    }

    if let Some(rest) = line.strip_prefix("create actor ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::CreateParticipant(name.to_string()));
        }
    }

    if let Some(rest) = line.strip_prefix("destroy ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::Destroy(name.to_string()));
        }
    }

    if let Some(rest) = line.strip_prefix("participant ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::Participant(name.to_string()));
        }
    }

    if let Some(rest) = line.strip_prefix("actor ") {
        let name = rest.trim();
        if !name.is_empty() {
            return Some(SequenceStatement::Actor(name.to_string()));
        }
    }

    parse_sequence_message_ast(line).map(|data| SequenceStatement::Message(Box::new(data)))
}

fn parse_sequence_autonumber(line: &str) -> Option<SequenceStatement> {
    let rest = line.strip_prefix("autonumber")?;
    let rest = rest.trim();
    if rest.is_empty() {
        return Some(SequenceStatement::Autonumber {
            start: None,
            increment: None,
        });
    }

    // `autonumber off` STOPS numbering; it is not a start value. Without this arm `"off".parse()`
    // fails, `?` takes the whole statement to `None`, and the line falls through to the message
    // parser -- so a directive the user wrote to turn something off was silently dropped and the
    // messages stayed numbered. Same family as bd-ec1t and bd-yrxu: input the engine cannot
    // interpret is reinterpreted as content instead of being honoured or reported.
    //
    // Matched case-insensitively because mermaid's own `autonumber` handling lowercases the keyword
    // argument before comparing.
    if rest.eq_ignore_ascii_case("off") {
        return Some(SequenceStatement::AutonumberOff);
    }

    let parts: Vec<&str> = rest.split_whitespace().collect();
    match parts.as_slice() {
        [start] => Some(SequenceStatement::Autonumber {
            start: Some(start.parse().ok()?),
            increment: None,
        }),
        [start, increment] => Some(SequenceStatement::Autonumber {
            start: Some(start.parse().ok()?),
            increment: Some(increment.parse().ok()?),
        }),
        _ => None,
    }
}

/// Parse `Note left of Alice: text`, `Note right of Bob: text`,
/// `Note over Alice: text`, `Note over Alice,Bob: text`.
/// Strip `prefix` from the front of `line`, ignoring ASCII case.
///
/// mermaid's sequence lexer matches `note` case-insensitively, and so do its position words —
/// `note`, `Note`, `NOTE` and even `Note Right Of` all PARSE against the pinned bundle.
fn strip_prefix_ignore_ascii_case<'a>(line: &'a str, prefix: &str) -> Option<&'a str> {
    let head = line.get(..prefix.len())?;
    head.eq_ignore_ascii_case(prefix)
        .then(|| &line[prefix.len()..])
}

fn parse_sequence_note(line: &str) -> Option<SequenceStatement> {
    // CASE-INSENSITIVE (bd-am6a2). This required a capital `Note `, so `note right of Bob: text` —
    // the spelling mermaid's own docs use and the one the STATE parser in this same file already
    // accepts — was SILENTLY DROPPED: no note box, no text, no warning, on all four placements.
    //
    // Three independent lines of evidence, not a style preference: the pinned incumbent returns a
    // clean PARSED for `note`, `NOTE` and `Note Right Of` alike; our state parser accepts lowercase
    // and renders it; and the drop was silent, which is the worst failure mode for a keyword whose
    // case the author has no reason to think matters.
    //
    // An actor NAMED `note` needs no protection here: mermaid rejects `note->>Bob: hi` as a syntax
    // error, so the word is reserved on both sides, and this function still returns `None` unless a
    // position keyword follows.
    let rest = strip_prefix_ignore_ascii_case(line, "Note ")?;

    let (position, after_kw) = if let Some(r) = strip_prefix_ignore_ascii_case(rest, "left of ") {
        (fm_core::NotePosition::LeftOf, r)
    } else if let Some(r) = strip_prefix_ignore_ascii_case(rest, "right of ") {
        (fm_core::NotePosition::RightOf, r)
    } else {
        let r = strip_prefix_ignore_ascii_case(rest, "over ")?;
        (fm_core::NotePosition::Over, r)
    };

    // Split at colon to get participants and text
    let (participants_str, text) = after_kw.split_once(':')?;
    let participants: Vec<String> = participants_str
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect();

    if participants.is_empty() {
        return None;
    }

    let text = normalize_sequence_display_text(text);

    Some(SequenceStatement::Note {
        position,
        participants,
        text,
    })
}

fn decode_mermaid_entities(text: &str) -> String {
    let mut decoded = String::with_capacity(text.len());
    let mut cursor = 0usize;

    while cursor < text.len() {
        let amp_start = text[cursor..].find('&').map(|offset| cursor + offset);
        let hash_start = text[cursor..].find('#').map(|offset| cursor + offset);
        let Some(start) = (match (amp_start, hash_start) {
            (Some(left), Some(right)) => Some(left.min(right)),
            (Some(left), None) => Some(left),
            (None, Some(right)) => Some(right),
            (None, None) => None,
        }) else {
            break;
        };

        decoded.push_str(&text[cursor..start]);

        let Some(relative_end) = text[start..].find(';') else {
            decoded.push_str(&text[start..]);
            return decoded;
        };
        let end = start + relative_end;
        let entity = if text[start..].starts_with('&') {
            &text[start + 1..end]
        } else {
            &text[start..end]
        };

        if let Some(ch) = decode_mermaid_entity_token(entity) {
            decoded.push(ch);
        } else {
            decoded.push_str(&text[start..=end]);
        }
        cursor = end + 1;
    }

    decoded.push_str(&text[cursor..]);
    decoded
}

/// Replace the three `<br>` spellings with `\n`, gated on a cheap `'<'` byte scan.
///
/// Each `str::replace(&str, _)` builds a `TwoWaySearcher` and allocates a fresh `String` even when
/// the needle is absent — measured as ~17% of sequence-message parsing (searcher construction +
/// `str::replace` + malloc), because a message label almost never contains `'<'`. `str::contains('<')`
/// is a char pattern (memchr), not a `TwoWaySearcher`. With no `'<'` present, none of the `"<br...>"`
/// needles can match, so returning the input borrowed is byte-identical to running the replace chain.
fn replace_br_with_newlines(text: &str) -> Cow<'_, str> {
    if text.contains('<') {
        Cow::Owned(
            text.replace("<br/>", "\n")
                .replace("<br>", "\n")
                .replace("<br />", "\n"),
        )
    } else {
        Cow::Borrowed(text)
    }
}

fn normalize_sequence_display_text(text: &str) -> String {
    let with_line_breaks = replace_br_with_newlines(text.trim());
    decode_mermaid_entities(&with_line_breaks)
}

fn decode_mermaid_entity_token(token: &str) -> Option<char> {
    if token.is_empty() {
        return None;
    }

    let bare = token.strip_prefix('#').unwrap_or(token);

    if let Some(numeric) = token.strip_prefix('#') {
        if let Some(hex) = numeric.strip_prefix(['x', 'X']) {
            let value = u32::from_str_radix(hex, 16).ok()?;
            return char::from_u32(value);
        }

        if numeric.bytes().all(|b| b.is_ascii_digit()) {
            let value = numeric.parse::<u32>().ok()?;
            return char::from_u32(value);
        }
    }

    match bare {
        "amp" => Some('&'),
        "apos" => Some('\''),
        "copy" => Some('©'),
        "gt" => Some('>'),
        "hearts" => Some('♥'),
        "infin" => Some('∞'),
        "lt" => Some('<'),
        "nbsp" => Some('\u{00A0}'),
        "quot" => Some('"'),
        "semi" => Some(';'),
        "tab" => Some('\t'),
        _ => None,
    }
}

fn parse_sequence_actor_menu(line: &str) -> Option<SequenceStatement> {
    if let Some(rest) = line.strip_prefix("link ") {
        let (actor_raw, after_actor) = rest.split_once(':')?;
        let actor = normalize_identifier(actor_raw);
        if actor.is_empty() {
            return None;
        }
        let (label_raw, url_raw) = after_actor.split_once('@')?;
        let label = clean_label(Some(label_raw.trim()))?;
        let url = clean_label(Some(url_raw.trim()))?;
        return Some(SequenceStatement::Link { actor, label, url });
    }

    if let Some(rest) = line.strip_prefix("links ") {
        let (actor_raw, json_raw) = rest.split_once(':')?;
        let actor = normalize_identifier(actor_raw);
        if actor.is_empty() {
            return None;
        }
        let value = serde_json::from_str::<Value>(json_raw.trim()).ok()?;
        let object = value.as_object()?;
        let mut entries = Vec::new();
        for (label, url_value) in object {
            let Some(url) = url_value.as_str().and_then(|raw| clean_label(Some(raw))) else {
                continue;
            };
            let Some(label) = clean_label(Some(label)) else {
                continue;
            };
            entries.push((label, url));
        }
        return Some(SequenceStatement::Links { actor, entries });
    }

    None
}

/// Parse `box [color] Label` into a `BoxStart` statement.
/// Color can be a CSS color name, hex (#abc), `rgb()`, etc.
fn parse_sequence_box_start(rest: &str) -> SequenceStatement {
    let rest = rest.trim();
    let (color, label) = if let Some((color, label)) = extract_sequence_box_color(rest) {
        (Some(color), label.to_string())
    } else {
        (None, rest.to_string())
    };

    SequenceStatement::BoxStart { label, color }
}

fn extract_sequence_box_color(rest: &str) -> Option<(String, &str)> {
    let rest = rest.trim_start();
    if rest.is_empty() {
        return None;
    }

    if rest.starts_with('#') {
        let end = rest.find(char::is_whitespace).unwrap_or(rest.len());
        let color = &rest[..end];
        return Some((color.to_string(), rest[end..].trim_start()));
    }

    let lower = rest.to_ascii_lowercase();
    for prefix in ["rgba(", "rgb(", "hsla(", "hsl("] {
        if lower.starts_with(prefix)
            && let Some(color_len) = consume_css_function(rest)
        {
            let color = &rest[..color_len];
            return Some((color.to_string(), rest[color_len..].trim_start()));
        }
    }

    let token_end = rest
        .find(|ch: char| ch.is_whitespace())
        .unwrap_or(rest.len());
    let color_name = &rest[..token_end];
    if is_css_named_color(color_name) {
        return Some((color_name.to_string(), rest[token_end..].trim_start()));
    }

    None
}

fn consume_css_function(value: &str) -> Option<usize> {
    let mut depth = 0usize;
    for (idx, ch) in value.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(idx + ch.len_utf8());
                }
            }
            _ => {}
        }
    }
    None
}

