    #[test]
    fn flowchart_fast_path_matches_fallback_for_simple_edges() {
        for statement in [
            "A-->B",
            "A --> B",
            "left_1 -.-> right.2",
            "left_1 <-.-> right.2",
            "svc/api ==> db-node",
            "svc/api <==> db-node",
            "A---B",
            "A<-->B",
            "A--oB",
            "A--xB",
        ] {
            let fast = parse_fast_simple_flowchart_statement_ast(statement);
            assert!(fast.is_some(), "fast path rejected {statement:?}");
            let Some(fast) = fast else {
                return;
            };
            let fallback = parse_edge_statement_asts(
                statement,
                &FLOW_OPERATORS,
                FLOW_OP_GATE,
                true,
                &ParserConfig::default(),
                0,
            );
            assert_eq!(
                Some(vec![fast]),
                fallback,
                "fast path diverged from fallback edge parser for {statement:?}"
            );
        }
    }

    #[test]
    fn flowchart_fast_path_matches_chumsky_for_simple_nodes() {
        for statement in [
            "A",
            "node_1[Node 1]",
            "svc/api[Service API]",
            "db-node[fa:database Storage]",
            "stage.one[Stage One]",
            "N0[\"Rate limit (429)\"]",
            "N1[\"Retry & backoff\"]",
            "N2[\"User's session\"]",
            "N3[\"Parse <config>\"]",
            "N4[\"Café latency\"]",
            "N5[\"comma, braces {stay content}\"]",
        ] {
            let fast = parse_fast_simple_flowchart_statement_ast(statement);
            assert!(fast.is_some(), "fast path rejected {statement:?}");
            let Some(fast) = fast else {
                return;
            };
            let (chumsky, errors) = flow_statement_parser()
                .parse(statement)
                .into_output_errors();
            assert!(
                errors.is_empty(),
                "chumsky rejected {statement:?}: {errors:?}"
            );
            assert_eq!(Some(fast), chumsky, "fast path diverged for {statement:?}");
        }
    }

    #[test]
    fn flowchart_fast_path_rejects_complex_statements() {
        for statement in [
            "A-->B-->C",
            "A & B --> C",
            "A[Start] -->|go| B(End)",
            "class A hot",
            "click A callback \"tip\"",
            "A:::hot",
            "A[[Subroutine]]",
        ] {
            assert!(
                parse_fast_simple_flowchart_statement_ast(statement).is_none(),
                "fast path should reject complex statement {statement:?}"
            );
        }
    }

    #[test]
    fn flowchart_parallel_edge_sources_expand_cartesian_product() {
        let parsed = parse_mermaid("flowchart LR\nA & B --> C");
        assert!(
            parsed.warnings.is_empty(),
            "warnings: {:?}",
            parsed.warnings
        );
        assert_eq!(parsed.ir.edges.len(), 2);

        let edges: std::collections::BTreeSet<(String, String)> = parsed
            .ir
            .edges
            .iter()
            .filter_map(|edge| {
                let (IrEndpoint::Node(from_id), IrEndpoint::Node(to_id)) = (&edge.from, &edge.to)
                else {
                    return None;
                };
                Some((
                    parsed.ir.nodes[from_id.0].id.clone(),
                    parsed.ir.nodes[to_id.0].id.clone(),
                ))
            })
            .collect();

        assert_eq!(
            edges.len(),
            parsed.ir.edges.len(),
            "expected node endpoints"
        );

        assert_eq!(
            edges,
            std::collections::BTreeSet::from([
                ("A".to_string(), "C".to_string()),
                ("B".to_string(), "C".to_string()),
            ])
        );
    }

