    #[test]
    fn multiline_deck_directive_is_hidden_from_the_flowchart_body() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {\n  title: 'Roadmap',\n  phantom --> must_not_become_an_edge,\n  slides: [{ id: 'intro', nodes: ['A'] }],\n}%%\nA --> B",
        );

        let node_ids: Vec<&str> = parsed
            .ir
            .nodes
            .iter()
            .map(|node| node.id.as_str())
            .collect();
        assert_eq!(node_ids, ["A", "B"]);
        assert_eq!(parsed.ir.edges.len(), 1);
        // Since bd-jw8m8 the deck pass CONSUMES the block: this fixture's deliberately
        // invalid JSON5 (`phantom --> …` as a bare token) now reports as an invalid deck
        // payload — the interior still never leaks into the body, which is the point.
        assert!(
            parsed
                .ir
                .meta
                .init
                .errors
                .iter()
                .all(|error| error.to_string().contains("invalid deck directive payload")),
            "{:?}",
            parsed.ir.meta.init.errors
        );
    }

    #[test]
    fn multiline_deck_terminator_with_trailing_text_does_not_end_the_block() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {\n  phantom --> must_not_become_an_edge,\n}%% trailing text\n}%%\nA --> B",
        );

        let node_ids: Vec<&str> = parsed
            .ir
            .nodes
            .iter()
            .map(|node| node.id.as_str())
            .collect();
        assert_eq!(node_ids, ["A", "B"]);
        assert_eq!(parsed.ir.edges.len(), 1);
        // See the sibling fixture: the consumed block's invalid JSON5 reports as an invalid
        // deck payload; nothing else may error.
        assert!(
            parsed
                .ir
                .meta
                .init
                .errors
                .iter()
                .all(|error| error.to_string().contains("invalid deck directive payload")),
            "{:?}",
            parsed.ir.meta.init.errors
        );
    }

    #[test]
    fn oversized_unterminated_deck_records_an_error_and_refeeds_the_body() {
        let mut input = String::from("flowchart LR\n%%{deck: {\n");
        for _ in 0..super::MAX_DECK_BLOCK_LINES {
            input.push_str("  key: value,\n");
        }
        input.push_str("A --> B");

        let parsed = parse_mermaid(&input);
        let endpoint = |endpoint: fm_core::IrEndpoint| match endpoint {
            fm_core::IrEndpoint::Node(id) => parsed.ir.nodes[id.0].id.as_str(),
            other => panic!("expected a node endpoint, got {other:?}"),
        };
        assert!(
            parsed
                .ir
                .edges
                .iter()
                .any(|edge| endpoint(edge.from) == "A" && endpoint(edge.to) == "B")
        );
        assert!(parsed.ir.meta.init.errors.iter().any(|error| {
            error
                .to_string()
                .contains("multi-line deck directive exceeds")
        }));
    }

    // ── parse_deck_config battery (bd-jw8m8) ──────────────────────────

    fn deck_of(parsed: &crate::ParseResult) -> &fm_core::IrDeck {
        parsed.ir.deck.as_deref().expect("deck should be present")
    }

    #[test]
    fn deck_directive_parses_every_grammar_field() {
        // JSON5 payload (unquoted keys, trailing commas) in a multi-line block. Note:
        // enable_init_directives defaults to FALSE and deck must parse regardless — deck
        // directives are structural content, not rendering config.
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {\n  title: 'Engine tour',\n  options: { fitMargin: 140, zoomMax: 1.2, dimOpacity: 0.1, autoAdvanceMs: 8000 },\n  tips: { a: 'the start', b: 'the end' },\n  slides: [\n    { id: 's1', title: 'Start', caption: 'first', nodes: ['a', 'subgraph:core'],\n      reveal: [['a'], ['subgraph:core']], edges: 'touching', fitMargin: 200, zoomMax: 1.0 },\n    { id: 's2', nodes: ['*'], reveal: 'auto', edges: 'none' },\n  ],\n  overview: { title: 'All of it', caption: 'zoomed out', tour: false, enabled: true },\n}}%%\n  a --> b\n",
        );
        let deck = deck_of(&parsed);
        assert_eq!(deck.title.as_deref(), Some("Engine tour"));
        assert!((deck.options.fit_margin - 140.0).abs() < f32::EPSILON);
        assert!((deck.options.zoom_max - 1.2).abs() < f32::EPSILON);
        assert!((deck.options.dim_opacity - 0.1).abs() < f32::EPSILON);
        assert_eq!(deck.options.auto_advance_ms, 8000);
        assert_eq!(deck.tips.len(), 2);
        assert_eq!(deck.tips.get("a").map(String::as_str), Some("the start"));
        assert_eq!(deck.slides.len(), 2);
        let first = &deck.slides[0];
        assert_eq!(first.id, "s1");
        assert_eq!(first.title, "Start");
        assert_eq!(first.caption, "first");
        assert_eq!(first.nodes, ["a", "subgraph:core"]);
        assert_eq!(
            first.reveal,
            fm_core::IrDeckReveal::Groups(vec![
                vec!["a".to_string()],
                vec!["subgraph:core".to_string()],
            ])
        );
        assert_eq!(first.edges, fm_core::IrDeckEdgePolicy::Touching);
        assert_eq!(first.fit_margin, Some(200.0));
        assert_eq!(first.zoom_max, Some(1.0));
        let second = &deck.slides[1];
        assert_eq!(second.title, "s2", "title defaults to the id");
        assert_eq!(second.reveal, fm_core::IrDeckReveal::Auto);
        assert_eq!(second.edges, fm_core::IrDeckEdgePolicy::None);
        assert!(deck.overview.enabled);
        assert!(!deck.overview.tour);
        assert_eq!(deck.overview.title, "All of it");
        assert!(
            parsed.ir.meta.init.errors.is_empty(),
            "well-formed deck must not error: {:?}",
            parsed.ir.meta.init.errors
        );
    }

    #[test]
    fn single_line_deck_directive_parses() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: \"only\", nodes: [\"a\"]}]}}%%\n  a --> b\n",
        );
        let deck = deck_of(&parsed);
        assert_eq!(deck.slides.len(), 1);
        assert_eq!(deck.slides[0].id, "only");
    }

    #[test]
    fn deck_directives_merge_in_document_order() {
        // title/options/overview: last-writer-wins per key; slides concatenate; tips later-wins.
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {title: 'first', options: {fitMargin: 100}, tips: {a: 'one', b: 'keep'}, slides: [{id: 'x', nodes: ['a']}]}}%%\n  a --> b\n%%{deck: {title: 'second', options: {zoomMax: 0.9}, tips: {a: 'two'}, slides: [{id: 'y', nodes: ['b']}]}}%%\n",
        );
        let deck = deck_of(&parsed);
        assert_eq!(deck.title.as_deref(), Some("second"));
        assert!(
            (deck.options.fit_margin - 100.0).abs() < f32::EPSILON,
            "earlier key kept"
        );
        assert!(
            (deck.options.zoom_max - 0.9).abs() < f32::EPSILON,
            "later key applied"
        );
        assert_eq!(
            deck.slides
                .iter()
                .map(|slide| slide.id.as_str())
                .collect::<Vec<_>>(),
            ["x", "y"]
        );
        assert_eq!(deck.tips.get("a").map(String::as_str), Some("two"));
        assert_eq!(deck.tips.get("b").map(String::as_str), Some("keep"));
    }

    #[test]
    fn deck_numeric_clamps_warn_and_clamp() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {options: {fitMargin: -5, dimOpacity: 3.5, autoAdvanceMs: 99999999}, slides: [{id: 's', nodes: ['a']}]}}%%\n  a --> b\n",
        );
        let deck = deck_of(&parsed);
        assert!((deck.options.fit_margin - 0.0).abs() < f32::EPSILON);
        assert!((deck.options.dim_opacity - 1.0).abs() < f32::EPSILON);
        assert_eq!(deck.options.auto_advance_ms, 600_000);
        let warnings = parsed.warnings.join("\n");
        assert!(warnings.contains("fitMargin clamped"), "{warnings}");
        assert!(warnings.contains("dimOpacity clamped"), "{warnings}");
        assert!(warnings.contains("autoAdvanceMs clamped"), "{warnings}");
    }

    #[test]
    fn deck_slide_cap_truncates_with_warning() {
        let mut source = String::from("flowchart LR\n  a --> b\n%%{deck: {slides: [\n");
        for index in 0..(super::MAX_DECK_SLIDES + 3) {
            source.push_str(&format!("  {{ id: 's{index}', nodes: ['a'] }},\n"));
        }
        source.push_str("]}}%%\n");
        let parsed = parse_mermaid(&source);
        let deck = deck_of(&parsed);
        assert_eq!(deck.slides.len(), super::MAX_DECK_SLIDES);
        assert!(
            parsed
                .warnings
                .iter()
                .any(|warning| warning.contains("truncated to 64 slides")),
            "{:?}",
            parsed.warnings
        );
    }

    #[test]
    fn duplicate_deck_slide_ids_are_suffixed_never_dropped() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: 'dup', nodes: ['a']}, {id: 'dup', nodes: ['b']}, {id: 'dup', nodes: ['a']}]}}%%\n  a --> b\n",
        );
        let deck = deck_of(&parsed);
        assert_eq!(
            deck.slides
                .iter()
                .map(|slide| slide.id.as_str())
                .collect::<Vec<_>>(),
            ["dup", "dup-2", "dup-3"]
        );
        assert!(
            parsed
                .warnings
                .iter()
                .any(|warning| warning.contains("duplicate deck slide id 'dup'")),
            "{:?}",
            parsed.warnings
        );
    }

    #[test]
    fn deck_structural_errors_degrade_with_warnings() {
        // Payload not an object → init error, directive ignored, diagram still parses.
        let parsed = parse_mermaid("flowchart LR\n%%{deck: [1, 2]}%%\n  a --> b\n");
        assert!(parsed.ir.deck.is_none());
        assert!(
            parsed
                .ir
                .meta
                .init
                .errors
                .iter()
                .any(|error| error.to_string().contains("must be an object"))
        );
        assert_eq!(parsed.ir.nodes.len(), 2, "diagram must still parse");

        // Slide without id / without nodes → skipped with warnings; bad reveal/edges → defaults.
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{nodes: ['a']}, {id: 'no-nodes'}, {id: 'ok', nodes: ['a'], reveal: 42, edges: 'sideways'}]}}%%\n  a --> b\n",
        );
        let deck = deck_of(&parsed);
        assert_eq!(deck.slides.len(), 1);
        assert_eq!(deck.slides[0].id, "ok");
        assert_eq!(deck.slides[0].reveal, fm_core::IrDeckReveal::None);
        assert_eq!(deck.slides[0].edges, fm_core::IrDeckEdgePolicy::Induced);
        let warnings = parsed.warnings.join("\n");
        assert!(warnings.contains("requires a string 'id'"), "{warnings}");
        assert!(
            warnings.contains("requires a 'nodes' selector array"),
            "{warnings}"
        );
        assert!(warnings.contains("reveal must be"), "{warnings}");
        assert!(warnings.contains("edges must be"), "{warnings}");
    }

    #[test]
    fn deckless_source_has_no_deck_and_unknown_keys_warn() {
        let parsed = parse_mermaid("flowchart LR\n  a --> b\n");
        assert!(parsed.ir.deck.is_none());

        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: 's', nodes: ['a']}], pushOut: true}}%%\n  a --> b\n",
        );
        assert!(
            parsed
                .warnings
                .iter()
                .any(|warning| warning.contains("unknown deck key 'pushOut'")),
            "{:?}",
            parsed.warnings
        );
    }

    #[test]
    fn deck_directive_is_inert_on_dot_input() {
        // The DOT branch never scans Mermaid directives — a documented v1 limitation. The
        // digraph header leads so detection actually takes the DOT path.
        let parsed = crate::parse(
            "digraph G {\n  a -> b\n}\n%%{deck: {slides: [{id: 's', nodes: ['a']}]}}%%\n",
        );
        assert_eq!(parsed.ir.diagram_type, fm_core::DiagramType::Flowchart);
        assert!(
            parsed.ir.deck.is_none(),
            "deck directives must be inert on DOT input"
        );
    }

    #[test]
    fn reparse_with_changed_deck_lands_the_new_deck() {
        let body = "flowchart LR\n  a --> b\n";
        let first = parse_mermaid(&format!(
            "{body}%%{{deck: {{slides: [{{id: 'one', nodes: ['a']}}]}}}}%%\n"
        ));
        let second = parse_mermaid(&format!(
            "{body}%%{{deck: {{slides: [{{id: 'two', nodes: ['b']}}]}}}}%%\n"
        ));
        assert_eq!(deck_of(&first).slides[0].id, "one");
        assert_eq!(deck_of(&second).slides[0].id, "two");
        assert_eq!(first.ir.nodes, second.ir.nodes, "bodies identical");
    }

    // ── deck semantic validation battery (bd-m2qzi) ───────────────────

    fn deck_semantic_warnings(parsed: &crate::ParseResult) -> Vec<String> {
        parsed
            .ir
            .diagnostics
            .iter()
            .filter(|diagnostic| {
                diagnostic.severity == DiagnosticSeverity::Warning
                    && diagnostic.category == DiagnosticCategory::Semantic
                    && diagnostic.message.starts_with("deck:")
            })
            .map(|diagnostic| diagnostic.message.clone())
            .collect()
    }

    #[test]
    fn unknown_deck_selectors_warn_with_fuzzy_suggestions() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: 's', nodes: ['alpha', 'alpah', 'subgraph:core', 'subgraph:coer']}]}}%%\n  subgraph core\n    alpha --> beta\n  end\n",
        );
        let warnings = deck_semantic_warnings(&parsed);
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("unknown selector 'alpah'")),
            "{warnings:?}"
        );
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("unknown selector 'subgraph:coer'")),
            "{warnings:?}"
        );
        let suggestions: Vec<&str> = parsed
            .ir
            .diagnostics
            .iter()
            .filter_map(|d| d.suggestion.as_deref())
            .collect();
        assert!(
            suggestions.iter().any(|s| s.contains("'alpha'")),
            "fuzzy node suggestion missing: {suggestions:?}"
        );
        assert!(
            suggestions.iter().any(|s| s.contains("'subgraph:core'")),
            "fuzzy subgraph suggestion missing: {suggestions:?}"
        );
        // Valid selectors resolved: no zero-member warning for the slide.
        assert!(
            !warnings.iter().any(|w| w.contains("zero members")),
            "{warnings:?}"
        );
    }

    #[test]
    fn empty_slide_and_deckless_slideless_decks_warn() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: 'ghost', nodes: ['nothing_here']}]}}%%\n  a --> b\n",
        );
        let warnings = deck_semantic_warnings(&parsed);
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("slide 'ghost' resolves to zero members")),
            "{warnings:?}"
        );

        let parsed = parse_mermaid("flowchart LR\n%%{deck: {title: 'empty'}}%%\n  a --> b\n");
        let warnings = deck_semantic_warnings(&parsed);
        assert!(
            warnings.iter().any(|w| w.contains("no slides defined")),
            "{warnings:?}"
        );
    }

    #[test]
    fn reveal_selector_rules_warn_non_members_and_overlaps() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {slides: [{id: 's', nodes: ['a', 'b'], reveal: [['a'], ['c'], ['a']]}]}}%%\n  a --> b\n  b --> c\n",
        );
        let warnings = deck_semantic_warnings(&parsed);
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("reveal selector 'c' matches no slide member")),
            "'c' is a real node but not a slide member: {warnings:?}"
        );
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("'a' already revealed at step 1")),
            "{warnings:?}"
        );
    }

    #[test]
    fn deck_tip_rules_warn_unknown_and_unreachable_targets() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {tips: {a: 'shown', c: 'never shown', ghost: 'no node'}, slides: [{id: 's', nodes: ['a', 'b']}]}}%%\n  a --> b\n  b --> c\n",
        );
        let warnings = deck_semantic_warnings(&parsed);
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("tip references unknown node 'ghost'")),
            "{warnings:?}"
        );
        assert!(
            warnings
                .iter()
                .any(|w| w.contains("tip for 'c' is unreachable")),
            "{warnings:?}"
        );
        assert!(
            !warnings.iter().any(|w| w.contains("tip for 'a'")),
            "a reachable tip must not warn: {warnings:?}"
        );
    }

    #[test]
    fn valid_deck_produces_no_semantic_warnings() {
        let parsed = parse_mermaid(
            "flowchart LR\n%%{deck: {tips: {a: 'start'}, slides: [{id: 's1', nodes: ['a', 'subgraph:core'], reveal: [['subgraph:core']]}, {id: 's2', nodes: ['*']}]}}%%\n  a --> b\n  subgraph core\n    b --> c\n  end\n",
        );
        let warnings = deck_semantic_warnings(&parsed);
        assert!(warnings.is_empty(), "{warnings:?}");
    }

    #[test]
    fn init_curve_becomes_an_edge_routing_hint() {
        use fm_core::MermaidEdgeRoutingHint;
        for (curve, expected) in [
            ("basis", MermaidEdgeRoutingHint::Curved),
            ("cardinal", MermaidEdgeRoutingHint::Curved),
            ("natural", MermaidEdgeRoutingHint::Curved),
            ("linear", MermaidEdgeRoutingHint::Orthogonal),
            ("step", MermaidEdgeRoutingHint::Orthogonal),
        ] {
            let parsed = parse_mermaid(&format!(
                "%%{{init: {{\"flowchart\":{{\"curve\":\"{curve}\"}}}}}}%%\nflowchart TB\nA-->B"
            ));
            assert_eq!(parsed.ir.meta.edge_routing, Some(expected), "curve={curve}");
            // The string is still recorded, so nothing that read it before loses information.
            assert_eq!(
                parsed.ir.meta.init.config.flowchart_curve.as_deref(),
                Some(curve)
            );
        }
    }

    #[test]
    fn an_unknown_curve_name_still_parses_and_sets_no_hint() {
        // `curve` has always accepted any string. Rejecting unknown names would turn a tolerated
        // input into a changed layout, so an unknown name records the string and no hint.
        let parsed = parse_mermaid(
            "%%{init: {\"flowchart\":{\"curve\":\"wobbly\"}}}%%\nflowchart TB\nA-->B",
        );
        assert_eq!(parsed.ir.meta.edge_routing, None);
        assert_eq!(
            parsed.ir.meta.init.config.flowchart_curve.as_deref(),
            Some("wobbly")
        );
    }

    #[test]
    fn no_curve_directive_leaves_the_routing_hint_unset() {
        let parsed = parse_mermaid("flowchart TB\nA-->B");
        assert_eq!(parsed.ir.meta.edge_routing, None);
    }

    #[test]
    fn init_directive_maps_spacing_to_the_layout_hints() {
        let parsed = parse_mermaid(
            "%%{init: {\"flowchart\":{\"nodeSpacing\":60,\"rankSpacing\":90}}}%%\nflowchart TB\nA-->B",
        );
        // Recorded in the init config so `parse --json` still reports the directive...
        assert_eq!(parsed.ir.meta.init.config.node_spacing, Some(60));
        assert_eq!(parsed.ir.meta.init.config.rank_spacing, Some(90));
        // ...AND applied to the meta hints, which is the half fm-layout actually reads. Recording it
        // only in the init config would leave a value nothing consumes.
        assert_eq!(parsed.ir.meta.node_spacing, Some(60));
        assert_eq!(parsed.ir.meta.rank_spacing, Some(90));
    }

    #[test]
    fn constraints_directive_emits_a_non_overlap_ir_constraint() {
        let parsed = parse_mermaid(
            "%%{constraints: {nonOverlap: {nodes: ['A', 'B'], gap: 12}}}%%\nflowchart TB\nA-->B",
        );

        assert_eq!(
            parsed.ir.constraints.len(),
            1,
            "{:?}",
            parsed.ir.constraints
        );
        assert!(matches!(
            &parsed.ir.constraints[0],
            fm_core::IrConstraint::NonOverlap { node_ids, gap, .. }
                if node_ids == &["A".to_string(), "B".to_string()] && (*gap - 12.0).abs() < f64::EPSILON
        ));
        assert!(parsed.warnings.is_empty(), "{:?}", parsed.warnings);
    }

    #[test]
    fn constraints_non_overlap_rejects_a_single_node_selection() {
        let parsed =
            parse_mermaid("%%{constraints: {nonOverlap: {nodes: ['A']}}}%%\nflowchart TB\nA-->B");

        assert!(parsed.ir.constraints.is_empty());
        assert!(
            parsed
                .warnings
                .iter()
                .any(|warning| warning.contains("needs at least two node IDs"))
        );
    }

    #[test]
    fn init_directive_spacing_is_absent_when_not_given() {
        // The control: an unconditional Some would collapse every diagram to a fixed spacing.
        let parsed = parse_mermaid("flowchart TB\nA-->B");
        assert_eq!(parsed.ir.meta.node_spacing, None);
        assert_eq!(parsed.ir.meta.rank_spacing, None);
    }

    #[test]
    fn init_directive_rejects_negative_and_non_numeric_spacing() {
        // A negative gap is not a smaller gap; reading it as 0 would collapse the diagram while
        // looking like it worked, so it is refused with a typed error rather than clamped.
        for payload in [
            "{\"flowchart\":{\"nodeSpacing\":-10}}",
            "{\"flowchart\":{\"rankSpacing\":\"wide\"}}",
        ] {
            let parsed = parse_mermaid(&format!("%%{{init: {payload}}}%%\nflowchart TB\nA-->B"));
            assert_eq!(parsed.ir.meta.node_spacing, None, "{payload}");
            assert_eq!(parsed.ir.meta.rank_spacing, None, "{payload}");
            assert!(
                !parsed.ir.meta.init.errors.is_empty() || !parsed.warnings.is_empty(),
                "{payload} must be reported: {:?}",
                parsed.warnings
            );
        }
    }

    #[test]
    fn init_directive_spacing_rounds_a_fractional_request() {
        let parsed = parse_mermaid(
            "%%{init: {\"flowchart\":{\"nodeSpacing\":60.6}}}%%\nflowchart TB\nA-->B",
        );
        assert_eq!(parsed.ir.meta.node_spacing, Some(61));
    }

