    #[test]
    fn architecture_parses_services_groups_junctions_and_edges() {
        let parsed = parse_mermaid(
            r"architecture-beta
group platform(cloud)[Platform]
service api(server)[API] in platform
junction fan_in in platform
service db(database)[DB] in platform
api:R --> L:fan_in
fan_in:B --> T:db",
        );
        assert_eq!(parsed.ir.diagram_type, DiagramType::ArchitectureBeta);
        assert_eq!(parsed.ir.nodes.len(), 3);
        assert_eq!(parsed.ir.edges.len(), 2);
        assert_eq!(parsed.ir.clusters.len(), 1);
        assert_eq!(parsed.ir.graph.subgraphs.len(), 1);
        assert!(
            parsed.warnings.is_empty(),
            "unexpected warnings: {:?}",
            parsed.warnings
        );

        let api = parsed
            .ir
            .nodes
            .iter()
            .find(|node| node.id == "api")
            .expect("api node");
        assert!(
            api.classes
                .iter()
                .any(|class_name| class_name == "architecture-service")
        );
        assert!(
            api.classes
                .iter()
                .any(|class_name| class_name == "architecture-icon-server")
        );
        assert_eq!(api.icon(), Some("server"));

        let junction = parsed
            .ir
            .nodes
            .iter()
            .find(|node| node.id == "fan_in")
            .expect("junction node");
        assert_eq!(junction.shape, NodeShape::Circle);

        let platform_cluster = &parsed.ir.clusters[0];
        let title = platform_cluster
            .title
            .and_then(|label_id| parsed.ir.labels.get(label_id.0))
            .map(|label| label.text.as_str());
        assert_eq!(title, Some("Platform"));
        assert_eq!(platform_cluster.members.len(), 3);
    }

    #[test]
    fn architecture_reverse_and_bidirectional_edges_map_cleanly() {
        let parsed = parse_mermaid(
            r"architecture-beta
service api[API]
service db[DB]
db <-- api
api <--> db",
        );
        assert_eq!(parsed.ir.diagram_type, DiagramType::ArchitectureBeta);
        assert_eq!(parsed.ir.nodes.len(), 2);
        assert_eq!(parsed.ir.edges.len(), 2);
        assert_eq!(parsed.ir.edges[0].arrow, ArrowType::Arrow);
        // STRENGTHENED, not relaxed: this asserted ArrowType::Line, which pinned the defect rather
        // than the specification — `api <--> db` is bidirectional and a bare line states nothing
        // about direction at all. The `<--` row above is the control: a one-way edge must stay
        // single-headed, so this cannot have made every architecture edge bidirectional.
        assert_eq!(parsed.ir.edges[1].arrow, ArrowType::DoubleArrow);

        let first_edge = &parsed.ir.edges[0];
        let endpoints_are_nodes = matches!(
            (&first_edge.from, &first_edge.to),
            (fm_core::IrEndpoint::Node(_), fm_core::IrEndpoint::Node(_))
        );
        assert!(endpoints_are_nodes, "expected architecture node endpoint");
        if !endpoints_are_nodes {
            return;
        }
        let (from_id, to_id) = match (&first_edge.from, &first_edge.to) {
            (fm_core::IrEndpoint::Node(from_id), fm_core::IrEndpoint::Node(to_id)) => {
                (from_id, to_id)
            }
            _ => return,
        };
        let first_from = parsed.ir.nodes[from_id.0].id.as_str();
        let first_to = parsed.ir.nodes[to_id.0].id.as_str();
        assert_eq!(first_from, "api");
        assert_eq!(first_to, "db");
    }

    #[test]
    fn c4_parses_people_systems_relationships_and_boundaries() {
        let parsed = parse_mermaid(
            r#"C4Context
Person(customer, "Customer")
System_Boundary(bank, "Banking System") {
    System(core, "Core Banking")
}
Rel(customer, core, "Uses", "HTTPS")"#,
        );
        assert_eq!(parsed.ir.diagram_type, DiagramType::C4Context);
        assert_eq!(parsed.ir.nodes.len(), 2);
        assert_eq!(parsed.ir.edges.len(), 1);
        assert_eq!(parsed.ir.clusters.len(), 1);
        assert_eq!(parsed.ir.graph.subgraphs.len(), 1);

        let customer = parsed
            .ir
            .nodes
            .iter()
            .find(|node| node.id == "customer")
            .expect("customer node");
        assert!(
            customer
                .classes
                .iter()
                .any(|class_name| class_name == "c4-person")
        );

        let core = parsed
            .ir
            .nodes
            .iter()
            .find(|node| node.id == "core")
            .expect("core node");
        assert!(
            core.classes
                .iter()
                .any(|class_name| class_name == "c4-system")
        );

        let cluster_title = parsed.ir.clusters[0]
            .title
            .and_then(|label_id| parsed.ir.labels.get(label_id.0))
            .map(|label| label.text.as_str());
        // Was `Some("System_Boundary(bank, Banking System)")` — the reconstructed source syntax,
        // which this test pinned as correct for as long as it was wrong (bd-039t).
        assert_eq!(cluster_title, Some("Banking System"));

        let edge_label = parsed.ir.edges[0]
            .label
            .and_then(|label_id| parsed.ir.labels.get(label_id.0))
            .map(|label| label.text.as_str());
        // The technology is no longer fused into the label: mermaid draws it as a separate italic
        // row, so it rides on the edge's extras and the label is the label alone.
        assert_eq!(edge_label, Some("Uses"));
        assert_eq!(
            parsed.ir.edges[0]
                .extras
                .as_ref()
                .and_then(|extras| extras.technology.as_deref()),
            Some("HTTPS"),
            "the technology must still reach the IR, just not inside the label"
        );
    }

