    // --- Flowchart node shape tests ---

    #[test]
    fn flowchart_node_shapes_basic() {
        let input = "flowchart TB\n  A[Rectangle]\n  B(Rounded)\n  C{Diamond}\n  D([Stadium])\n  E[[Subroutine]]\n  F[(Database)]\n  G((Circle))\n  H>Asymmetric]\n  I(((DoubleCircle)))";
        let parsed = parse_mermaid(input);
        assert!(
            parsed.ir.nodes.len() >= 9,
            "Should have 9 shaped nodes, got {}",
            parsed.ir.nodes.len()
        );

        // Assert the SHAPES, not just the count (bd-3w93). Counting alone is satisfied by every
        // node parsing as Rounded, and that is exactly what happened: `D([Stadium])` parsed as
        // Rounded with the literal label `[Stadium]` while this test stayed green for months.
        // Each shape's delimiters are also its label boundary, so checking the label catches a
        // delimiter drifting into the text even when the shape happens to be right.
        let expected = [
            ("A", NodeShape::Rect, "Rectangle"),
            ("B", NodeShape::Rounded, "Rounded"),
            ("C", NodeShape::Diamond, "Diamond"),
            ("D", NodeShape::Stadium, "Stadium"),
            ("E", NodeShape::Subroutine, "Subroutine"),
            ("F", NodeShape::Cylinder, "Database"),
            // `((x))` is a PLAIN circle. This row asserted DoubleCircle until bd-vfxu / 57767867
            // made the parser distinguish the two syntaxes, and the stale expectation then failed —
            // it was encoding the very conflation that commit removed. The fixture always said
            // `G((Circle))`, so the expectation contradicted its own input.
            ("G", NodeShape::Circle, "Circle"),
            ("H", NodeShape::Asymmetric, "Asymmetric"),
            // The CONTROL for the row above, and the reason this is a correction rather than a
            // re-bless: `(((x)))` must still be DoubleCircle. Asserting only that `((x))` is Circle
            // would be satisfied by a parser that had simply lost DoubleCircle altogether.
            ("I", NodeShape::DoubleCircle, "DoubleCircle"),
        ];
        for (id, shape, label) in expected {
            let node = parsed
                .ir
                .nodes
                .iter()
                .find(|n| n.id == id)
                .unwrap_or_else(|| panic!("node {id} not parsed"));
            assert_eq!(node.shape, shape, "node {id} shape");
            let text = node
                .label
                .and_then(|label_id| parsed.ir.labels.get(label_id.0))
                .map(|value| value.text.as_str());
            assert_eq!(
                text,
                Some(label),
                "node {id} label — shape delimiters must not survive into the text"
            );
        }
    }

    /// Every multi-char shape delimiter must beat the single-char delimiter nested inside it
    /// (bd-3w93). `[(x)]` starts with `[` and ends with `]`, `([x])` starts with `(` and ends with
    /// `)`, and `[/x/]` starts with `[` and ends with `]` — so a greedy single-char rule swallows
    /// each of them and yields a plausible wrong shape whose label keeps the inner delimiters.
    #[test]
    fn flowchart_multi_char_shape_delimiters_beat_their_nested_single_char_forms() {
        let input = "flowchart LR\n  A([Stadium])\n  B[(Database)]\n  C[/Para/]\n  D[\\Inv\\]\n  \
                     E[/Trap\\]\n  F[\\InvTrap/]";
        let parsed = parse_mermaid(input);
        let got = |id: &str| {
            parsed.ir.nodes.iter().find(|n| n.id == id).map(|n| {
                (
                    n.shape,
                    n.label
                        .and_then(|label_id| parsed.ir.labels.get(label_id.0))
                        .map(|value| value.text.clone()),
                )
            })
        };
        for (id, shape, label) in [
            ("A", NodeShape::Stadium, "Stadium"),
            ("B", NodeShape::Cylinder, "Database"),
            ("C", NodeShape::Parallelogram, "Para"),
            ("D", NodeShape::InvParallelogram, "Inv"),
            ("E", NodeShape::Trapezoid, "Trap"),
            ("F", NodeShape::InvTrapezoid, "InvTrap"),
        ] {
            assert_eq!(
                got(id),
                Some((shape, Some(label.to_string()))),
                "node {id} must keep its declared shape and shed its delimiters"
            );
        }
    }

    /// A stadium and a rounded rectangle are different shapes and must stay different (bd-3w93).
    #[test]
    fn flowchart_stadium_is_not_parsed_as_rounded() {
        let parsed = parse_mermaid("flowchart LR\n  pill([Pill])\n  soft(Soft)");
        let shape_of = |id: &str| {
            parsed.ir.nodes.iter().find(|n| n.id == id).map(|n| {
                (
                    n.shape,
                    n.label
                        .and_then(|label_id| parsed.ir.labels.get(label_id.0))
                        .map(|value| value.text.clone()),
                )
            })
        };
        assert_eq!(
            shape_of("pill"),
            Some((NodeShape::Stadium, Some("Pill".to_string())))
        );
        assert_eq!(
            shape_of("soft"),
            Some((NodeShape::Rounded, Some("Soft".to_string())))
        );
    }

