    fn create_placeholder_nodes_toggle_controls_dangling_edge_recovery() {
        let baseline = parse_mermaid("flowchart LR\nA -->");
        assert_eq!(baseline.ir.edges.len(), 1);
        assert!(baseline.ir.nodes.iter().any(|node| node.implicit));

        let no_placeholders = parse_with_mode_and_config(
            "flowchart LR\nA -->",
            MermaidParseMode::Compat,
            &ParserConfig {
                create_placeholder_nodes: false,
                ..ParserConfig::default()
            },
        );
        assert_eq!(no_placeholders.ir.edges.len(), 0);
        assert!(!no_placeholders.ir.nodes.iter().any(|node| node.implicit));
    }

    #[test]
    fn auto_close_delimiters_toggle_controls_unclosed_acc_descr_blocks() {
        let baseline = parse_mermaid("flowchart LR\n  accDescr {\n    Unclosed content");
        assert_eq!(
            baseline.ir.meta.acc_descr.as_deref(),
            Some("Unclosed content")
        );

        let strict_delimiters = parse_with_mode_and_config(
            "flowchart LR\n  accDescr {\n    Unclosed content",
            MermaidParseMode::Compat,
            &ParserConfig {
                auto_close_delimiters: false,
                ..ParserConfig::default()
            },
        );
        assert!(strict_delimiters.ir.meta.acc_descr.is_none());
    }

    #[test]
    fn front_matter_title_is_promoted_to_diagram_meta() {
        let parsed = parse_mermaid("---\ntitle: Front Matter Title\n---\nflowchart LR\nA --> B");
        assert_eq!(parsed.ir.meta.title.as_deref(), Some("Front Matter Title"));
    }

    #[test]
    fn timeline_inline_title_is_promoted_to_diagram_meta() {
        let parsed = parse_mermaid("timeline\n  title Shipping History\n  2024 : Launch");
        assert_eq!(parsed.ir.meta.title.as_deref(), Some("Shipping History"));
    }

    #[test]
    fn gantt_inline_title_overrides_front_matter_title() {
        let parsed = parse_mermaid(
            "---\ntitle: Front Matter\n---\ngantt\n  title Inline Gantt\n  section Alpha\n  Task :a1, 2024-01-01, 1d",
        );
        assert_eq!(parsed.ir.meta.title.as_deref(), Some("Inline Gantt"));
        assert_eq!(
            parsed
                .ir
                .gantt_meta
                .as_ref()
                .and_then(|meta| meta.title.as_deref()),
            Some("Inline Gantt")
        );
    }

    // ── Click tooltip tests ────────────────────────────────────────────

    #[test]
    fn click_directive_extracts_tooltip() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A[Node]\n  click A \"https://example.com\" \"My Tooltip\"",
        );
        let node = parsed.ir.nodes.iter().find(|n| n.id == "A").unwrap();
        assert_eq!(node.href(), Some("https://example.com"));
        assert_eq!(node.tooltip(), Some("My Tooltip"));
    }

    // ── linkStyle default tests ────────────────────────────────────────

    #[test]
    fn linkstyle_default_creates_link_default_style_ref() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  linkStyle default stroke:#f00,stroke-width:2",
        );
        let has_default = parsed
            .ir
            .style_refs
            .iter()
            .any(|sr| sr.target == fm_core::IrStyleTarget::LinkDefault);
        assert!(has_default, "should have LinkDefault style ref");
    }

    /// `linkStyle 0,2 ...` styles BOTH named links — and ONLY those.
    ///
    /// The index position is a list in mermaid's grammar (`updateLink` forEach's over an array), but
    /// this parser ran `parse::<usize>()` over the whole position. `"0,2"` is not a `usize`, the
    /// parse failed, and there was no else branch — so the whole directive vanished silently.
    ///
    /// The `!has(1)` assertion is the one that matters: without it, a change that simply applied the
    /// style to EVERY link would pass. That is the failure mode a list feature invites.
    #[test]
    fn linkstyle_applies_to_every_index_in_a_comma_list() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  B --> C\n  C --> D\n  linkStyle 0,2 stroke:#ff0000",
        );

        let has = |index: usize| {
            parsed
                .ir
                .style_refs
                .iter()
                .any(|sr| sr.target == fm_core::IrStyleTarget::Link(index))
        };
        assert!(
            has(0) && has(2),
            "the comma list did not reach both links: {:?}",
            parsed.ir.style_refs
        );
        assert!(
            !has(1),
            "an unnamed link was styled — the list is being ignored rather than parsed: {:?}",
            parsed.ir.style_refs
        );
    }

    /// CONTROL: the single-index form still works. The list split must not have replaced it.
    #[test]
    fn linkstyle_with_one_index_still_styles_that_link() {
        let parsed =
            parse_mermaid("flowchart LR\n  A --> B\n  B --> C\n  linkStyle 1 stroke:#00ff00");

        let links: Vec<_> = parsed
            .ir
            .style_refs
            .iter()
            .filter(|sr| matches!(sr.target, fm_core::IrStyleTarget::Link(_)))
            .map(|sr| sr.target.clone())
            .collect();
        assert_eq!(
            links,
            vec![fm_core::IrStyleTarget::Link(1)],
            "the single-index form changed behaviour"
        );
    }

    /// An out-of-range index is NAMED, not silently dropped.
    ///
    /// mermaid throws here. Throwing away the diagram over one bad number is not this parser's
    /// contract, so the index is dropped — but pushing a `Link(9)` that matches no edge would be the
    /// same invisible nothing this whole change is about, so it is reported instead.
    #[test]
    fn linkstyle_out_of_bounds_index_warns_and_styles_nothing() {
        let parsed = parse_mermaid("flowchart LR\n  A --> B\n  linkStyle 9 stroke:#ff0000");

        assert!(
            !parsed
                .ir
                .style_refs
                .iter()
                .any(|sr| matches!(sr.target, fm_core::IrStyleTarget::Link(_))),
            "an out-of-range index produced a style ref: {:?}",
            parsed.ir.style_refs
        );
        assert!(
            parsed.warnings.iter().any(|w| w.contains("out of bounds")),
            "the out-of-range index was dropped in silence: {:?}",
            parsed.warnings
        );
    }

    /// `click A,B "url"` links BOTH nodes (bd-8mlk).
    ///
    /// We read one token and `normalize_identifier` breaks at the comma, so only `A` was linked and
    /// `,B` was dropped without a word. `setLink` in mermaid splits its node position the same way
    /// every other directive in that db does.
    #[test]
    fn click_links_every_node_in_a_comma_list() {
        let parsed =
            parse_mermaid("flowchart LR\n  A --> B\n  click A,B \"https://example.com\"\n");

        for id in ["A", "B"] {
            let node = parsed
                .ir
                .nodes
                .iter()
                .find(|n| n.id == id)
                .unwrap_or_else(|| panic!("node {id} should exist"));
            assert_eq!(
                node.href(),
                Some("https://example.com"),
                "node {id} was not linked"
            );
        }
    }

    /// Whitespace around the separator is legal in mermaid (`click A, B "url"` parses), so the list
    /// cannot be one whitespace-delimited token. This is the case that fails if the parser simply
    /// splits the first token on commas.
    #[test]
    fn click_node_list_tolerates_spaces_around_the_comma() {
        let parsed =
            parse_mermaid("flowchart LR\n  A --> B\n  click A, B \"https://example.com\"\n");

        for id in ["A", "B"] {
            let node = parsed
                .ir
                .nodes
                .iter()
                .find(|n| n.id == id)
                .unwrap_or_else(|| panic!("node {id} should exist"));
            assert_eq!(
                node.href(),
                Some("https://example.com"),
                "node {id} was not linked"
            );
        }
    }

    /// CONTROL: a single-node click is unchanged, and the accumulator did not swallow the target.
    /// If the loop over-consumed, the URL would become part of the node list and `A` would have no
    /// href at all — so this pins the stop condition, not just the happy path.
    #[test]
    fn click_with_one_node_is_unchanged() {
        let parsed = parse_mermaid("flowchart LR\n  A --> B\n  click A \"https://example.com\"\n");

        let node = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "A")
            .expect("node A should exist");
        assert_eq!(node.href(), Some("https://example.com"));
        assert_eq!(
            parsed.ir.nodes.len(),
            2,
            "the click directive invented nodes: {:?}",
            parsed.ir.nodes.iter().map(|n| &n.id).collect::<Vec<_>>()
        );
    }

    /// `click A "url" _blank` must not put the BROWSER TARGET in the tooltip.
    ///
    /// The third position is either a tooltip or a link target. We assumed tooltip, so `_blank` was
    /// rendered to the reader as hover text — visible text the author never wrote, not a silent
    /// drop. mermaid lexes `_self`/`_blank`/`_parent`/`_top` as keywords and stores the value as
    /// `linkTarget`, separate from the tooltip.
    ///
    /// The href assertion is the non-vacuity control: without it, a click line that failed to parse
    /// at all would also leave the tooltip empty and pass.
    #[test]
    fn click_link_target_is_not_mistaken_for_a_tooltip() {
        let parsed =
            parse_mermaid("flowchart LR\n  A --> B\n  click A \"https://example.com\" _blank\n");

        let node = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "A")
            .expect("node A should exist");
        assert_eq!(
            node.href(),
            Some("https://example.com"),
            "the click directive did not take effect at all"
        );
        assert_eq!(
            node.tooltip(),
            None,
            "the browser link target was rendered as tooltip text"
        );
    }

    /// CONTROL: a real tooltip in that position still lands. A fix that simply dropped the third
    /// token would pass the test above.
    #[test]
    fn click_tooltip_in_the_third_position_still_lands() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  click A \"https://example.com\" \"open the thing\"\n",
        );

        let node = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "A")
            .expect("node A should exist");
        assert_eq!(node.tooltip(), Some("open the thing"));
    }

    /// A QUOTED `"_blank"` is tooltip text, because that is the only thing the author can have
    /// meant by quoting it. This is why the keyword is matched before quote stripping.
    #[test]
    fn click_quoted_blank_is_still_a_tooltip() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  click A \"https://example.com\" \"_blank\"\n",
        );

        let node = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "A")
            .expect("node A should exist");
        assert_eq!(node.tooltip(), Some("_blank"));
    }

    /// An `interpolate <curve>` clause must not end up INSIDE the CSS declaration.
    ///
    /// We had no concept of the clause, so the whole tail became the style string and the link was
    /// handed `"interpolate basis stroke:#ff0000"`. That corrupts a declaration that was otherwise
    /// valid — worse than dropping it, because the author's colour silently stops working.
    ///
    /// The exact-equality assertion is the point: `contains("stroke")` would pass on the old
    /// behaviour too.
    #[test]
    fn linkstyle_interpolate_clause_is_stripped_from_the_style() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  linkStyle 0 interpolate basis stroke:#ff0000",
        );

        let link = parsed
            .ir
            .style_refs
            .iter()
            .find(|sr| sr.target == fm_core::IrStyleTarget::Link(0))
            .expect("the link should still be styled");
        assert_eq!(
            link.style, "stroke:#ff0000",
            "the interpolate clause leaked into the CSS declaration"
        );
    }

    /// The clause on its own leaves nothing to style, and says so rather than inventing a
    /// declaration out of the curve name.
    #[test]
    fn linkstyle_interpolate_alone_styles_nothing_and_warns() {
        let parsed = parse_mermaid("flowchart LR\n  A --> B\n  linkStyle 0 interpolate basis");

        assert!(
            !parsed
                .ir
                .style_refs
                .iter()
                .any(|sr| matches!(sr.target, fm_core::IrStyleTarget::Link(_))),
            "a curve name was turned into a style declaration: {:?}",
            parsed.ir.style_refs
        );
        assert!(
            parsed.warnings.iter().any(|w| w.contains("interpolate")),
            "the unimplemented curve was dropped in silence: {:?}",
            parsed.warnings
        );
    }

    /// The keyword is case-insensitive in mermaid (`INTERPOLATE basis` parses), so it is here.
    #[test]
    fn linkstyle_interpolate_keyword_is_case_insensitive() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A --> B\n  linkStyle 0 INTERPOLATE basis stroke:#00ff00",
        );

        let link = parsed
            .ir
            .style_refs
            .iter()
            .find(|sr| sr.target == fm_core::IrStyleTarget::Link(0))
            .expect("the link should still be styled");
        assert_eq!(link.style, "stroke:#00ff00");
    }

    /// CONTROL: an ordinary declaration is untouched. The clause is matched as a WHOLE WORD, so
    /// this also pins that a property merely starting with those letters is not eaten.
    #[test]
    fn linkstyle_without_an_interpolate_clause_is_unchanged() {
        let parsed = parse_mermaid("flowchart LR\n  A --> B\n  linkStyle 0 stroke:#ff0000");

        let link = parsed
            .ir
            .style_refs
            .iter()
            .find(|sr| sr.target == fm_core::IrStyleTarget::Link(0))
            .expect("the link should be styled");
        assert_eq!(link.style, "stroke:#ff0000");
        assert!(
            !parsed.warnings.iter().any(|w| w.contains("interpolate")),
            "an ordinary linkStyle produced a curve warning: {:?}",
            parsed.warnings
        );
    }

    /// A target that is neither a number nor `default` is reported rather than dropped.
    #[test]
    fn linkstyle_unparseable_target_warns() {
        let parsed = parse_mermaid("flowchart LR\n  A --> B\n  linkStyle nope stroke:#ff0000");

        assert!(
            parsed.warnings.iter().any(|w| w.contains("`nope`")),
            "an unparseable linkStyle target was dropped in silence: {:?}",
            parsed.warnings
        );
    }

    // ── Requirement metadata tests ─────────────────────────────────────

    #[test]
    fn requirement_parser_extracts_metadata() {
        let input = "requirementDiagram\n  requirement MyReq {\n    id: REQ-001\n    text: Must do X\n    risk: High\n    verifymethod: Test\n  }";
        let parsed = parse_mermaid(input);
        let req_node = parsed.ir.nodes.iter().find(|n| n.id == "MyReq");
        assert!(req_node.is_some(), "should find MyReq node");
        let meta = req_node
            .unwrap()
            .requirement_meta
            .as_ref()
            .expect("requirement_meta should be set");
        assert_eq!(meta.req_id.as_deref(), Some("REQ-001"));
        assert_eq!(meta.text.as_deref(), Some("Must do X"));
        assert_eq!(meta.risk.as_deref(), Some("High"));
        assert_eq!(meta.verify_method.as_deref(), Some("Test"));
    }

    /// `verifyMethod:` — the spelling mermaid documents — must not be dropped (bd-lzhm).
    ///
    /// The field match ran against the RAW text with a lowercase-only arm, so the camelCase form
    /// every author is told to write fell through and the value vanished. bd-qdmn had already hit
    /// this for `docRef` and fixed it by listing both spellings, which left the same trap armed for
    /// every other field.
    #[test]
    fn requirement_verify_method_is_matched_case_insensitively() {
        let input = "requirementDiagram\n  requirement MyReq {\n    id: REQ-001\n    verifyMethod: Test\n  }";
        let parsed = parse_mermaid(input);

        let meta = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "MyReq")
            .and_then(|n| n.requirement_meta.as_ref())
            .expect("requirement_meta should be set");
        assert_eq!(meta.verify_method.as_deref(), Some("Test"));
    }

    /// Every other field is case-insensitive too, which is the point of canonicalising rather than
    /// enumerating spellings: a capitalised `Text:` at the start of a line is ordinary prose habit.
    #[test]
    fn requirement_fields_survive_arbitrary_casing() {
        let input = "requirementDiagram\n  requirement MyReq {\n    ID: REQ-001\n    Text: hello\n    Risk: high\n    DocRef: spec.md\n  }";
        let parsed = parse_mermaid(input);

        let meta = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "MyReq")
            .and_then(|n| n.requirement_meta.as_ref())
            .expect("requirement_meta should be set");
        assert_eq!(meta.req_id.as_deref(), Some("REQ-001"));
        assert_eq!(meta.text.as_deref(), Some("hello"));
        assert_eq!(meta.risk.as_deref(), Some("high"));
        assert_eq!(meta.doc_ref.as_deref(), Some("spec.md"));
    }

    /// CONTROL: a field name that is not one of the six is still ignored. Case-insensitive matching
    /// must not turn into matching anything — `notafield:` has to stay unrecognised, or the block
    /// would start absorbing arbitrary lines.
    #[test]
    fn requirement_unknown_field_is_still_ignored() {
        let input =
            "requirementDiagram\n  requirement MyReq {\n    id: REQ-001\n    notafield: nope\n  }";
        let parsed = parse_mermaid(input);

        let meta = parsed
            .ir
            .nodes
            .iter()
            .find(|n| n.id == "MyReq")
            .and_then(|n| n.requirement_meta.as_ref())
            .expect("requirement_meta should be set");
        assert_eq!(meta.req_id.as_deref(), Some("REQ-001"));
        assert_eq!(meta.text, None, "an unknown field leaked into a known one");
    }

    // ── ER notation storage tests ──────────────────────────────────────

    /// A styled quadrant point lands where it was WRITTEN (bd-8dk0m).
    ///
    /// Everything after the first colon was taken as coordinate text, so
    /// `A: [0.3, 0.6] radius: 10` split on the comma into a y of `0.6] radius: 10`, which fails to
    /// parse and fell through `unwrap_or(0.5)` to the middle of the chart. In a quadrant chart the
    /// POSITION IS THE CONTENT, so the point was drawn confidently somewhere the author never put
    /// it, with no diagnostic.
    #[test]
    fn a_styled_quadrant_point_keeps_its_coordinates() {
        let parsed = parse_mermaid(
            "quadrantChart\n  x-axis Low --> High\n  A: [0.3, 0.6] radius: 10, color: #ff0000\n",
        );

        let points = parsed
            .ir
            .quadrant_meta
            .as_ref()
            .map(|meta| meta.points.clone())
            .unwrap_or_default();
        let point = points
            .iter()
            .find(|p| p.label == "A")
            .unwrap_or_else(|| panic!("point A was lost: {points:?}"));
        assert!(
            (point.x - 0.3).abs() < 1e-6 && (point.y - 0.6).abs() < 1e-6,
            "the styling clause moved the point: {point:?}"
        );
        assert!(
            parsed.warnings.iter().any(|w| w.contains("point styling")),
            "the unapplied styling was dropped in silence: {:?}",
            parsed.warnings
        );
    }

    /// CONTROL: an UNSTYLED point is unchanged and raises no warning — including the bracket-less
    /// spelling, whose fallback path this fix deliberately left byte-for-byte.
    #[test]
    fn unstyled_quadrant_points_are_unchanged() {
        for source in [
            "quadrantChart\n  x-axis Low --> High\n  A: [0.3, 0.6]\n",
            "quadrantChart\n  x-axis Low --> High\n  A: 0.3, 0.6\n",
        ] {
            let parsed = parse_mermaid(source);
            let points = parsed
                .ir
                .quadrant_meta
                .as_ref()
                .map(|meta| meta.points.clone())
                .unwrap_or_default();
            let point = points
                .iter()
                .find(|p| p.label == "A")
                .unwrap_or_else(|| panic!("point A was lost for {source}: {points:?}"));
            assert!(
                (point.x - 0.3).abs() < 1e-6 && (point.y - 0.6).abs() < 1e-6,
                "an unstyled point moved: {point:?} for {source}"
            );
            assert!(
                !parsed.warnings.iter().any(|w| w.contains("point styling")),
                "an unstyled point produced a styling warning: {:?}",
                parsed.warnings
            );
        }
    }

    /// `xychart-beta horizontal` swaps the axes and we draw vertically — say so (bd-8dk0m).
    #[test]
    fn xychart_horizontal_orientation_is_reported_as_unapplied() {
        let parsed = parse_mermaid("xychart-beta horizontal\n  x-axis [a, b]\n  bar [1, 2]\n");

        assert!(
            parsed.warnings.iter().any(|w| w.contains("horizontal")),
            "the orientation was dropped in silence: {:?}",
            parsed.warnings
        );
        // NON-VACUITY: the chart itself must still parse, or the warning is all there is.
        assert!(
            parsed
                .ir
                .xy_chart_meta
                .as_ref()
                .is_some_and(|meta| !meta.series.is_empty()),
            "the chart did not parse, so the assertion above proves little"
        );
    }

    /// CONTROL: an ordinary vertical chart raises no orientation warning.
    #[test]
    fn xychart_without_an_orientation_is_silent() {
        let parsed = parse_mermaid("xychart-beta\n  x-axis [a, b]\n  bar [1, 2]\n");

        assert!(
            !parsed.warnings.iter().any(|w| w.contains("horizontal")),
            "an ordinary chart produced an orientation warning: {:?}",
            parsed.warnings
        );
    }

    /// An UNIMPLEMENTED but real mermaid type says so, instead of blaming the author (bd-8z4fk).
    ///
    /// `treemap` renders in the incumbent. "No parseable nodes or edges were found" is true here but
    /// misleading — it invites the author to hunt for a syntax error that does not exist.
    #[test]
    fn an_unimplemented_diagram_type_is_named_rather_than_blamed() {
        // ⚠️ THE MESSAGE NAMES THE CANONICAL TYPE, NOT THE HEADER AS WRITTEN, which is why these are
        // PAIRS. `unsupported_upstream_keyword` splits the header on whitespace or `-` and matches
        // the first token, so `treemap-beta` reports `treemap`. My first version asserted the
        // message contained the header verbatim and failed on exactly that — the implementation is
        // right and the expectation was mine.
        //
        // `ishikawa` is deliberately ABSENT: it is a real mermaid 11.15.0 type we do not implement,
        // but the surviving matcher in lib.rs does not list it yet and that file belongs to another
        // session. Adding the case here before the entry exists would be a test asserting a feature
        // nobody wrote. Tracked on bd-8z4fk.
        // `treemap`/`treemap-beta` WERE HERE and are not any more: bd-9ghyo implemented the family,
        // so naming it unimplemented is now the wrong answer. `an_implemented_type_is_never_named_
        // as_unimplemented` in lib.rs asserts the opposite for it.
        // `radar-beta` WAS HERE and is not any more: bd-sk4dv implemented the family. The BARE
        // `radar` spelling is still unimplemented and still names `radar-beta` back, which is
        // now a spelling that actually renders — asserted in lib.rs.
        for (header, canonical) in [("venn-beta", "venn"), ("wardley-beta", "wardley")] {
            let parsed = parse_mermaid(&format!("{header}\n  \"A\": 1\n"));

            // Layer-AGNOSTIC on purpose: this asserts the user-visible outcome, not which function
            // produced it. The message comes from `unsupported_upstream_keyword` at detection; this
            // test survives that implementation moving, and fails if it is deleted.
            assert!(
                parsed
                    .warnings
                    .iter()
                    .any(|w| w.contains(canonical) && w.contains("does not implement")),
                "`{header}` was not named as unimplemented: {:?}",
                parsed.warnings
            );
        }
    }

    /// CONTROL: an unrecognisable document is NOT claimed as an unimplemented upstream type.
    ///
    /// ⚠️ THIS ASSERTED THE WRONG THING FIRST. It demanded the generic "No parseable nodes" message,
    /// which never fires for this input: `not a diagram at all` is detected as a flowchart and its
    /// words are interned as a node, so the document is not empty and the warning is
    /// "Could not detect diagram type; assuming flowchart" instead. The expectation was mine and the
    /// parser was right.
    ///
    /// What actually needs guarding is the OVER-CLAIM: a typo must not be reported as a real mermaid
    /// type we have not built, because that tells the author to stop looking for their own mistake.
    /// That is the failure mode the unimplemented-type message introduces, and it is what this pins.
    #[test]
    fn an_unrecognisable_document_is_not_claimed_as_an_unimplemented_type() {
        let parsed = parse_mermaid("not a diagram at all\n");

        assert!(
            !parsed
                .warnings
                .iter()
                .any(|w| w.contains("does not implement")),
            "a typo was reported as an unimplemented upstream type: {:?}",
            parsed.warnings
        );
    }

    /// `branch dev order: 2` names the branch `dev` (bd-p6sgt).
    ///
    /// The whole remainder was taken as the name, so the branch was called `dev order: 2` — the
    /// lane captioned with the author's own syntax, and a later `checkout dev` matching NOTHING
    /// because by our reckoning that branch did not exist.
    ///
    /// The checkout assertion is the one that shows the real damage: a name-only check would pass
    /// on a parse that still left the rest of the graph disconnected.
    #[test]
    fn gitgraph_branch_order_clause_is_not_part_of_the_name() {
        let parsed = parse_mermaid(
            "gitGraph\n  commit\n  branch dev order: 2\n  commit\n  checkout main\n  commit\n",
        );

        let branches = parsed
            .ir
            .git_graph_meta
            .as_ref()
            .map(|meta| meta.branches.clone())
            .unwrap_or_default();
        assert!(
            branches.iter().any(|b| b == "dev"),
            "the order clause leaked into the branch name: {branches:?}"
        );
        assert!(
            !branches.iter().any(|b| b.contains("order")),
            "a branch is still named after the directive text: {branches:?}"
        );
    }

    /// The order VALUE is not applied, and says so rather than vanishing.
    #[test]
    fn gitgraph_branch_order_value_is_reported_as_unapplied() {
        let parsed = parse_mermaid("gitGraph\n  commit\n  branch dev order: 2\n  commit\n");

        assert!(
            parsed.warnings.iter().any(|w| w.contains("branch order")),
            "an unapplied lane order was dropped in silence: {:?}",
            parsed.warnings
        );
    }

    /// CONTROL: an ordinary branch is untouched, and raises no order warning. The clause is split
    /// only when it is actually present, so no branch name that worked before can change.
    #[test]
    fn gitgraph_branch_without_an_order_clause_is_unchanged() {
        let parsed = parse_mermaid("gitGraph\n  commit\n  branch dev\n  commit\n");

        let branches = parsed
            .ir
            .git_graph_meta
            .as_ref()
            .map(|meta| meta.branches.clone())
            .unwrap_or_default();
        assert!(branches.iter().any(|b| b == "dev"), "{branches:?}");
        assert!(
            !parsed.warnings.iter().any(|w| w.contains("branch order")),
            "an ordinary branch produced an order warning: {:?}",
            parsed.warnings
        );
    }

    /// Mermaid 11.15's `gantt.topAxis` config must survive parsing (bd-c7ijh).
    #[test]
    fn gantt_top_axis_config_is_carried_to_gantt_meta() {
        let parsed = parse_mermaid(
            "%%{init: {'gantt': {'topAxis': true}} }%%\ngantt\n  dateFormat YYYY-MM-DD\n  \
             section S\n  T :a, 2026-01-01, 5d\n",
        );

        assert!(
            !parsed
                .warnings
                .iter()
                .any(|w| w.contains("unsupported gantt syntax")),
            "a valid directive was reported as unsupported: {:?}",
            parsed.warnings
        );
        // NON-VACUITY: the chart must still parse, or "no warning" would also hold for a source that
        // produced nothing at all.
        assert!(
            parsed
                .ir
                .gantt_meta
                .as_ref()
                .is_some_and(|meta| meta.top_axis && !meta.sections.is_empty()),
            "the gantt chart did not parse, so the assertion above proves nothing"
        );
    }

    /// CONTROL: genuinely unsupported gantt syntax is STILL reported. Recognising one directive must
    /// not turn the fallthrough warning off for everything else.
    #[test]
    fn unknown_gantt_syntax_is_still_reported() {
        let parsed = parse_mermaid(
            "gantt\n  dateFormat YYYY-MM-DD\n  notADirective\n  section S\n  T :a, 2026-01-01, 5d\n",
        );

        assert!(
            parsed
                .warnings
                .iter()
                .any(|w| w.contains("unsupported gantt syntax")),
            "an unknown directive stopped being reported: {:?}",
            parsed.warnings
        );
    }

    /// EVERY cardinality combination connects the two entities it names (bd-flznf).
    ///
    /// Generative over mermaid's own product — LEFT x LINE x RIGHT — rather than a handful of
    /// spot-checks, because the defect was an omission: twelve of the thirty-two combinations were
    /// listed and the rest fell through to the bare `--` fallback in the SAME table. That splits
    /// `A }o--o| B` at the middle dashes, so the endpoints normalise into MANGLED entity names and
    /// the real ones go unconnected. A test that enumerates the grid cannot miss the next omission
    /// the way a list of examples can.
    ///
    /// The node-NAME assertion is the load-bearing one: a mangled parse still yields two nodes and
    /// one edge, so counting alone would pass on the exact defect this covers.
    #[test]
    fn every_er_cardinality_pair_connects_the_named_entities() {
        for left in ["||", "|o", "}|", "}o"] {
            for line in ["--", ".."] {
                for right in ["||", "o|", "|{", "o{"] {
                    let operator = format!("{left}{line}{right}");
                    let parsed = parse_mermaid(&format!(
                        "erDiagram\n  CUSTOMER {operator} ORDER : places\n"
                    ));

                    let ids: Vec<&str> = parsed.ir.nodes.iter().map(|n| n.id.as_str()).collect();
                    assert_eq!(
                        ids,
                        vec!["CUSTOMER", "ORDER"],
                        "`{operator}` mangled the entity names"
                    );
                    assert_eq!(parsed.ir.edges.len(), 1, "`{operator}` drew no single edge");
                    assert_eq!(
                        parsed.ir.edges[0].er_notation(),
                        Some(operator.as_str()),
                        "`{operator}` lost its cardinality notation"
                    );
                }
            }
        }
    }

    /// CONTROL: the bare fallbacks still work and are still distinguishable. They are what the
    /// missing combinations were wrongly falling through to, so they must keep matching only when
    /// no cardinality is written.
    #[test]
    fn bare_er_relations_still_parse_without_cardinality() {
        for (operator, expected) in [("--", ArrowType::Line), ("..", ArrowType::DottedLine)] {
            let parsed = parse_mermaid(&format!(
                "erDiagram\n  CUSTOMER {operator} ORDER : places\n"
            ));
            let ids: Vec<&str> = parsed.ir.nodes.iter().map(|n| n.id.as_str()).collect();
            assert_eq!(ids, vec!["CUSTOMER", "ORDER"]);
            assert_eq!(parsed.ir.edges[0].arrow, expected);
        }
    }

    #[test]
    fn er_edge_stores_notation() {
        let parsed = parse_mermaid("erDiagram\n  USER ||--o{ ORDER : places");
        assert!(!parsed.ir.edges.is_empty(), "should have edges");
        let edge = &parsed.ir.edges[0];
        assert!(
            edge.er_notation().is_some(),
            "er_notation should be set on ER edges"
        );
    }

    // ── classDef parsing and structured style tests ───────────────────

    #[test]
    fn classdef_populates_style_defs() {
        let parsed = parse_mermaid(
            "flowchart LR\n  A[Node]\n  classDef important fill:#f9f,stroke:#333,stroke-width:4px",
        );
        assert!(
            !parsed.ir.style_defs.is_empty(),
            "style_defs should be populated"
        );
        let def = parsed
            .ir
            .style_defs
            .iter()
            .find(|d| d.name == "important")
            .expect("should find 'important' style def");
        assert_eq!(def.properties.get("fill").unwrap(), "#f9f");
        assert_eq!(def.properties.get("stroke").unwrap(), "#333");
        assert_eq!(def.properties.get("stroke-width").unwrap(), "4px");
    }

